//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** @author John Miller, Casey Bowman * @version 2.0 * @date Tue Feb 4 14:56:34 EST 2020 * @see LICENSE (MIT style license file). * * @note Supports Physics Models for Motion of Vehicles */
package scalation package simulation package process
import scala.math.{abs, max, min, sqrt} import scalation.mathstat.* import scalation.dynamics.* import Vehicle.*
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Enumeration for selecting the ODE integrator type for IDM dynamics. * Used for experimental comparison of numerical integration methods. */ enum IntegratorType: case DOPRI5 // Dormand-Prince (4,5) adaptive - O(Δt⁵) - current default case RK4 // Classic Runge-Kutta 4th order - O(Δt⁴) case RK3 // SSPRK3 - O(Δt³) case RK2 // Modified Euler (Explicit Midpoint) - O(Δt²) case Heun // Heun's method (Explicit Trapezoidal) - O(Δt²) - Treiber recommended case Euler // Forward Euler - O(Δt¹) - what SUMO uses case butcher // Butcher 5th order - O(Δt⁵) case Ballistic // Kinematic equations - O(Δt²) end IntegratorType
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `Dynamics` trait supports physics models for the motion of vehicles, e.g., * car-following models. */ trait Dynamics:
private [process] var disp = 0.0 // set initial current displacement to 0 private [process] var t_disp = 0.0 // set initial total displacement to 0 private [process] var velocity = v0 // set initial velocity to v0 private [process] var o_t_disp = t_disp // set initial old total displacement t_disp private [process] var o_velocity = velocity // set initial old velocity to velocity private [process] var acc = 0.0 // set initial acceleration to 0 private [process] var o_acc = acc // set initial old acceleration acc
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Find the leader of the given vehicle using per-VTransport DLLs. * First checks within the same segment (myPathNode.ahead). * If null (car is head of its segment), looks at the next segment's DLL tail. * @param car the vehicle whose leader we need * @return the leader vehicle, or null if free-flow */ protected def findLeader (car: Vehicle): Vehicle = // Step 1: within-segment leader (O(1) DLL lookup) val ref = car.myPathNode.ahead if ref != null then return ref.elem
// Step 2: cross-boundary — look at next segment's DLL tail val pw = car.myPathway if pw != null then val segs = pw.seg val nextIdx = car.segId + 1 if nextIdx < segs.length && segs(nextIdx) != null then return segs(nextIdx).getLast // most recently entered car in next seg end if null // no leader: free-flow end findLeader
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Update the values of the vehicle: velocity, displacement, lane according * to the car-following model being used. * @param motion the dynamics/physics determining the motion (e.g., car-following model) * @param car the vehivle to move
*/ def updateV (car: Vehicle, maxDisp: Double): Unit = // println (s"Dynamics.updateV: called $car") this match case GippsDynamics => { GippsDynamics.updateM (car, maxDisp) } case KraussDynamics => { KraussDynamics.updateM (car, maxDisp) } case _ => { IDMDynamics.updateM (car, maxDisp) } end updateV
end Dynamics
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `GippsDynamics` object provides equations for the Gipps car-following model. * @see https://en.wikipedia.org/wiki/Gipps%27_model */ object GippsDynamics extends Dynamics:
private val debug = debugf ("GippsDynamics", false) // debug function private[process] val easyW = new EasyWriter("simulation", "CalRoute101Model.txt")
/** Integrator type for position update (configurable, default Ballistic) */ var integratorType: IntegratorType = IntegratorType.Ballistic
/** Update the vehicle's velocity and position using Gipps' Model. * Position update method is configurable via integratorType. * * @param car the car/vehicle whose velocity and position is being updated */ /** Update the vehicle's velocity and position using Gipps' Model. * All gap and position computations use segment-local `disp` — consistent with * per-segment DLLs where the leader is always in the same or adjacent segment. * `t_disp` is updated as a derived statistic only. */ def updateM(car: Vehicle, length: Double): Unit = val car_ahead = findLeader (car) val dt = prop("rt")
// Step 1: compute next velocity using Gipps (discrete rule) val v = gipps(car, car_ahead, length) + EPSILON
// Step 2: update position in segment-local coordinates val x = integratorType match case IntegratorType.Ballistic => car.disp + car.velocity * dt case IntegratorType.butcher => butcher(car.disp, car.velocity, car.o_velocity, dt) case _ => car.disp + car.velocity * dt
// Step 3: commit velocity state AFTER position integration car.o_velocity = car.velocity car.velocity = v
// Step 4: segment-bounded displacement update car.o_t_disp = car.t_disp val new_disp = if x <= length then x else length
car.t_disp += new_disp - car.disp // derive t_disp from clamped delta car.disp = new_disp end updateM
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the velocity of the vehicle based on Gipps' model for a vehicle and its predecessor. * With per-segment DLLs, leader is always same-seg or next-seg. All positions are segment-local. * @param cn the current vehicle * @param cp the predecessor of the current vehicle (from findLeader — always same or next segment) */ def gipps (cn: Vehicle, cp: Vehicle, length: Double): Double = if cp == null then gipps (amax, bmax, len, cn.vmax, cn.disp, cn.velocity, cn.disp + 1000, cn.vmax, prop("rt")) else // Leader is in same segment or adjacent next segment val cp_r_disp = if cp.segId == cn.segId then cp.disp else length + cp.disp gipps (amax, bmax, len, cn.vmax, cn.disp, cn.velocity, cp_r_disp, cp.velocity, prop("rt")) end gipps //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** Return the velocity of the vehicle based on Gipps' model. * * @param an the max acceleration of drivers * @param bn the max deceleration of drivers (may be negative) * @param sp the size of vehicles * @param Vn the desired velocity of driver n * @param xn the current position of driver n * @param vn the current velocity of driver n * @param xp the current position of the predecessor (ahead) * @param vp the current velocity of the predecessor * @param rt the reaction time of drivers */ private def gipps(an: Double, bn: Double, sp: Double, Vn: Double, xn: Double, vn: Double, xp: Double, vp: Double, rt: Double): Double = // --------------- Parameters --------------------- val b = abs(bn) // use positive magnitude of deceleration val b_hat = b * 1.8 // expected braking ability of leader (default 0.8×b) b_hat >= b
// --------------- Free-flow branch --------------- // v_free = v_n + 2.5 * a_n * τ * (1 - v_n/V_n) * sqrt(0.025 + v_n/V_n) val free = vn + (2.5 * an * rt * (1.0 - vn / Vn)) * sqrt(0.025 + vn / Vn)
// --------------- Congested (safety) branch ------- // v_cong = b * τ + sqrt(b^2 * τ^2 - b[2(gap) - v_nτ - v_p^2/b̂]) val gap = xp - sp - xn // effective front-to-front gap val phi = 2.0 * gap - (vn * rt) - (vp * vp / b_hat) // safety term inside brackets
// When phi >= 0, spacing is large enough that braking constraint is inactive. // In that case, use free-flow velocity directly (skip sqrt computation). if phi >= 0.0 then return free
// Otherwise, apply the congested/safety branch. val inner_exp = (b * b * rt * rt) - b * phi // value inside sqrt val cong = (b * rt) + sqrt(max(0.0, inner_exp)) // braking (congested) velocity min(free, cong) end gipps
end GippsDynamics
object KraussDynamics extends Dynamics:
private val debug = debugf("KraussDynamics", false)
/** Krauss stochastic imperfection magnitude (m/s) * Must be small relative to amax*tau to allow net acceleration */ private val sigma = 0.2
/** Uniform random variate for stochastic noise */ private val noiseRV = scalation.random.Uniform(0.0, sigma)
/** Integrator type for position update (configurable, default Ballistic) */ var integratorType: IntegratorType = IntegratorType.Ballistic
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Update the vehicle's velocity and position using Krauss Model. * Position update method is configurable via integratorType. * @param car the vehicle to update * @param length the segment length */ def updateM(car: Vehicle, length: Double): Unit = val car_ahead = findLeader (car) val dt = prop("rt")
// Compute leader position and velocity val (xp, vp): (Double, Double) = if car_ahead == null then (car.disp + 1000.0, car.vmax) // phantom leader (free flow) else if car_ahead.segId == car.segId then (car_ahead.disp, car_ahead.velocity) else (length + car_ahead.disp, car_ahead.velocity)
// Step 1: Compute next velocity using Krauss val v_new = krauss( amax, bmax, len, car.vmax, car.disp, car.velocity, xp, vp, dt, s )
// Step 2: Position update based on configured integrator type val x_new = integratorType match case IntegratorType.Ballistic => car.t_disp + car.velocity * dt case IntegratorType.butcher => butcher(car.t_disp, car.velocity, car.o_velocity, dt) case _ => car.t_disp + car.velocity * dt
// Step 3: Commit velocity state AFTER position update car.o_velocity = car.velocity car.velocity = v_new
// Step 4: Segment-bounded displacement update car.o_t_disp = car.t_disp val dx = x_new - car.t_disp val new_disp = if car.disp + dx <= length then car.disp + dx else length
car.t_disp += new_disp - car.disp car.disp = new_disp end updateM
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Compute next velocity using Krauss car-following model. * Safety is enforced BEFORE stochastic noise is applied. * * @param an max acceleration * @param bn max deceleration (negative) * @param sp vehicle length * @param Vn desired speed * @param xn follower position * @param vn follower velocity * @param xp leader position * @param vp leader velocity * @param rt reaction time (timestep) * @param s0 minimum spacing */ private def krauss(an: Double, bn: Double, sp: Double, Vn: Double, xn: Double, vn: Double, xp: Double, vp: Double, rt: Double, s0: Double): Double = val b = abs(bn)
// Netto gap (front-to-rear) val gap = xp - xn - sp if gap <= 0.0 then return 0.0 // collision avoidance
// Krauss safe speed: v_safe = sqrt(v_leader^2 + 2*b*(gap - s0)) val inner = vp * vp + 2.0 * b * (gap - s0) val v_safe = sqrt(max(0.0, inner))
// Acceleration constraint: v_cap = v + a_max * tau val v_cap = vn + an * rt
// Desired speed constraint val v_des = Vn
// Deterministic candidate (minimum of all constraints) val v_star = min(v_des, min(v_safe, v_cap))
// Stochastic imperfection applied AFTER safety val eps = noiseRV.gen max(0.0, v_star - eps) end krauss
end KraussDynamics
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `IDMDynamics` object provides equations for the Intelligent Driver Model (IDM) * car-following model. * @see https://en.wikipedia.org/wiki/Intelligent_driver_model */
object IDMDynamics extends Dynamics:
private val debug = debugf ("IDMDynamics", true) // debug function
private val FREERANGE = 150.0
/** Configurable integrator type for ODE solving - default Ballistic */ var integratorType: IntegratorType = IntegratorType.Ballistic
/** Flag to print integrator type only once per simulation run */ private var integratorPrinted: Boolean = false
/** Reset the print flag - call this before each new simulation */ def resetIntegratorPrintFlag(): Unit = integratorPrinted = false
/** * @param car the vehicle to update * @param length the segment length */ def updateM(car: Vehicle, length: Double): Unit = val car_ahead = findLeader (car) val dt = rt
// Snapshot leader state (frozen during integration) val (x_leader, v_leader): (Double, Double) = // leader's (position, velocity) if car_ahead == null then (car.t_disp + 1000.0, car.velocity) // no leader: free-flow else if car_ahead.t_disp - car.t_disp > FREERANGE then (car.t_disp + 1000.0, car.velocity) // leader is far ahead: free-flow else (car_ahead.t_disp, car_ahead.velocity) // real leader: use it
// ───────────────────────────────────────────────────────────────────────── // STEP 2: Save old state for history tracking // ───────────────────────────────────────────────────────────────────────── val v_old = car.velocity val x_old = car.t_disp
/** * @param x_n Current position of driver n (from ODE solver trial values, NOT car.t_disp) * @param v_n Current velocity of driver n (from ODE solver trial values, NOT car.velocity) * @return IDM acceleration clamped to physical bounds [-bmax, amax] */ def idmAccel(x_n: Double, v_n: Double): Double = val b = abs(bmax)
// Call existing iDM with snapshotted leader state // iDM(an, bn, sp, Vn, xn, vn, xp, vp, T, s0, del) var a = iDM(amax, b, len, car.vmax, x_n, v_n, x_leader, v_leader, T, s, del)
// Clamp acceleration to physical bounds if a.isNaN || a.isInfinity then a = 0.0 if a < -b then a = -b if a > amax then a = amax a end idmAccel
// Array of derivative functions: [dx/dt, dv/dt] // dx/dt = v (velocity) returned directly from state vector // dv/dt = a (IDM acceleration) returned by idmAccel helper function val odes: Array[DerivativeV] = Array( (t: Double, y: VectorD) => y(1), // dx/dt = v (velocity) (t: Double, y: VectorD) => idmAccel(y(0), y(1)) // dv/dt = a (IDM acceleration) )
// ───────────────────────────────────────────────────────────────────────── // STEP 4: Solve the coupled system with selected integrator // ───────────────────────────────────────────────────────────────────────── val y0 = VectorD(car.t_disp, car.velocity) // initial state [x(t), v(t)]
// Print integrator type ONCE per simulation (from inside updateM, not from caller) if !integratorPrinted then println(s"[IDMDynamics.updateM] INTEGRATOR IN USE: $integratorType") integratorPrinted = true
// Select integrator based on integratorType setting val y1: VectorD = integratorType match case IntegratorType.DOPRI5 => DormandPrince.integrateVV(odes, y0, dt) case IntegratorType.RK4 => RungeKutta2.rk4.integrateVV(odes, y0, dt) case IntegratorType.RK3 => RungeKutta2.rk3.integrateVV(odes, y0, dt) case IntegratorType.RK2 => RungeKutta2.rk2.integrateVV(odes, y0, dt) case IntegratorType.Heun => RungeKutta2.heun.integrateVV(odes, y0, dt) case IntegratorType.Euler => RungeKutta2.euler.integrateVV(odes, y0, dt) case IntegratorType.butcher => // Butcher's 5th-order method (J.C. Butcher) - a quadrature rule using historical samples. // Apply twice: once for velocity (using acceleration history), once for position (using velocity history). // This maintains 5th-order accuracy for BOTH state variables.
// Step 1: Velocity via Butcher using acceleration history: a(t), a(t−τ) // v(t+τ) = v(t) + (1/90)(7k1 + 32k3 + 12k4 + 32k5 + 7k6)τ where k's interpolate a(t-τ) to a(t) val a_idm = idmAccel(car.t_disp, car.velocity) // a(t) from IDM val v_new_b = Vehicle.butcher( car.velocity, // v(t) - current velocity a_idm, // a(t) - current acceleration car.o_acc, // a(t−τ) - previous acceleration dt )
// Step 2: Position via Butcher using velocity history: v(t), v(t−τ) // x(t+τ) = x(t) + (1/90)(7k1 + 32k3 + 12k4 + 32k5 + 7k6)τ where k's interpolate v(t-τ) to v(t) val x_new_b = Vehicle.butcher( car.t_disp, // x(t) - current position car.velocity, // v(t) - current velocity car.o_velocity, // v(t−τ) - previous velocity dt ) VectorD(x_new_b, v_new_b) case IntegratorType.Ballistic => // Ballistic: compute IDM acceleration once, then kinematic update val a_idm = idmAccel(car.t_disp, car.velocity) val v_ball = car.velocity + a_idm * dt // v(t + dt) the new velocity val x_ball = car.t_disp + car.velocity * dt + 0.5 * a_idm * dt * dt // x(t + dt) VectorD(x_ball, v_ball) // construct new state vector
// ───────────────────────────────────────────────────────────────────────── // STEP 5: Extract and clamp results // ───────────────────────────────────────────────────────────────────────── val x_new = y1(0) // new position x(t + dt) var v_new = y1(1) // new velocity v(t + dt)
// Physical constraints: velocity must be non-negative and bounded if v_new < 0.0 then v_new = 0.0 // no backward motion if v_new > car.vmax then v_new = car.vmax // respect max speed
// Back-calculate acceleration for state storage val a = (v_new - v_old) / dt // average acceleration over dt
// ───────────────────────────────────────────────────────────────────────── // STEP 6: Update vehicle state // ───────────────────────────────────────────────────────────────────────── car.o_acc = car.acc // save old acceleration car.acc = a // update acceleration car.o_velocity = v_old // save old velocity car.velocity = v_new // update velocity car.o_t_disp = x_old // save old position
// ───────────────────────────────────────────────────────────────────────── // STEP 7: Segment-bounded displacement update // ───────────────────────────────────────────────────────────────────────── val dx = x_new - x_old // change in position val proposed_disp = car.disp + dx // proposed new displacement val new_disp = if proposed_disp <= length then proposed_disp else length // clamp to segment length
car.t_disp += new_disp - car.disp // update total position car.disp = new_disp // update displacement on segment end updateM
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the acceleration of the vehicle based on the Intelligent Driver Model * for a vehicle and its predecessor. * @param cn the current vehicle * @param cp the predecessor of the current vehicle * @param del the acceleration exponenent (defualts to 4) */ def iDM (cn: Vehicle, cp: Vehicle, del: Double = 4.0): Double = if cp == null then iDMFree (amax, cn.velocity, cn.vmax, del) else if cp.t_disp - cn.t_disp > FREERANGE then iDMFree (amax, cn.velocity, cn.vmax, del) else iDM (amax, abs(bmax), len, cn.vmax, cn.t_disp, cn.velocity, cp.t_disp, cp.velocity, T, s, del) end iDM
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the acceleration of the vehicle based on the Intelligent Driver Model. * @param an the max acceleration of drivers * @param bn the max deceleration of drivers (negative #) * @param sp the size of vehicles * @param Vn the desired velocity of driver n * @param xn the current position of driver n * @param vn the current velocity of driver n * @param xp the current position of the predecessor * @param vp the current velocity of the predecessor * @param T the safe min time headway * @param s0 the safe min distance headway * @param del the acceleration exponenent (defualts to 4) */ private def iDM (an: Double, bn: Double, sp: Double, Vn: Double, xn: Double, vn: Double, xp: Double, vp: Double, T: Double, s0: Double, del: Double): Double = val b = abs(bn) // use positive magnitude of deceleration val Δx = xp - xn - sp // front to rear gap val Δv = vn - vp // approach rate val ss = s0 + vn * T + (vn * Δv) / (2.0 * sqrt (an * b)) // desired gap an * (1.0 - (vn / Vn) ~^ del - (ss / Δx) ~^ 2.0) // acceleration end iDM
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the acceleration of the vehicle based on the Intelligent Driver Model * when there is no predecessor. * @param an the max acceleration of drivers * @param vn the current velocity of driver n * @param Vn the desired velocity of driver n * @param del the acceleration exponenent (defualts to 4) */ private def iDMFree (an: Double, vn: Double, Vn: Double, del: Double = 4.0): Double = an * (1.0 - (vn / Vn) ~^ del) end iDMFree
end IDMDynamics

//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** @author John Miller, Casey Bowman * @version 2.0 * @date Tue Feb 4 14:56:34 EST 2020 * @see LICENSE (MIT style license file). * * @note Supports Physics Models for Motion of Vehicles */
package scalation package simulation package process
import scala.math.{abs, max, min, sqrt} import scalation.mathstat.* import scalation.dynamics.* import Vehicle.*
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Enumeration for selecting the ODE integrator type for IDM dynamics. * Used for experimental comparison of numerical integration methods. */ enum IntegratorType: case DOPRI5 // Dormand-Prince (4,5) adaptive - O(Δt⁵) - current default case RK4 // Classic Runge-Kutta 4th order - O(Δt⁴) case RK3 // SSPRK3 - O(Δt³) case RK2 // Modified Euler (Explicit Midpoint) - O(Δt²) case Heun // Heun's method (Explicit Trapezoidal) - O(Δt²) - Treiber recommended case Euler // Forward Euler - O(Δt¹) - what SUMO uses case butcher // Butcher 5th order - O(Δt⁵) case Ballistic // Kinematic equations - O(Δt²) end IntegratorType
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `Dynamics` trait supports physics models for the motion of vehicles, e.g., * car-following models. */ trait Dynamics:
private [process] var disp = 0.0 // set initial current displacement to 0 private [process] var t_disp = 0.0 // set initial total displacement to 0 private [process] var velocity = v0 // set initial velocity to v0 private [process] var o_t_disp = t_disp // set initial old total displacement t_disp private [process] var o_velocity = velocity // set initial old velocity to velocity private [process] var acc = 0.0 // set initial acceleration to 0 private [process] var o_acc = acc // set initial old acceleration acc
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Find the leader of the given vehicle using per-VTransport DLLs. * First checks within the same segment (myPathNode.ahead). * If null (car is head of its segment), looks at the next segment's DLL tail. * @param car the vehicle whose leader we need * @return the leader vehicle, or null if free-flow */ protected def findLeader (car: Vehicle): Vehicle = // Step 1: within-segment leader (O(1) DLL lookup) val ref = car.myPathNode.ahead if ref != null then return ref.elem
// Step 2: cross-boundary — look at next segment's DLL tail val pw = car.myPathway if pw != null then val segs = pw.seg val nextIdx = car.segId + 1 if nextIdx < segs.length && segs(nextIdx) != null then return segs(nextIdx).getLast // most recently entered car in next seg end if null // no leader: free-flow end findLeader
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Update the values of the vehicle: velocity, displacement, lane according * to the car-following model being used. * @param motion the dynamics/physics determining the motion (e.g., car-following model) * @param car the vehivle to move
*/ def updateV (car: Vehicle, maxDisp: Double): Unit = // println (s"Dynamics.updateV: called $car") this match case GippsDynamics => { GippsDynamics.updateM (car, maxDisp) } case KraussDynamics => { KraussDynamics.updateM (car, maxDisp) } case _ => { IDMDynamics.updateM (car, maxDisp) } end updateV
end Dynamics
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `GippsDynamics` object provides equations for the Gipps car-following model. * @see https://en.wikipedia.org/wiki/Gipps%27_model */ object GippsDynamics extends Dynamics:
private val debug = debugf ("GippsDynamics", false) // debug function private[process] val easyW = new EasyWriter("simulation", "CalRoute101Model.txt")
/** Integrator type for position update (configurable, default Ballistic) */ var integratorType: IntegratorType = IntegratorType.Ballistic
/** Update the vehicle's velocity and position using Gipps' Model. * Position update method is configurable via integratorType. * * @param car the car/vehicle whose velocity and position is being updated */ /** Update the vehicle's velocity and position using Gipps' Model. * All gap and position computations use segment-local `disp` — consistent with * per-segment DLLs where the leader is always in the same or adjacent segment. * `t_disp` is updated as a derived statistic only. */ def updateM(car: Vehicle, length: Double): Unit = val car_ahead = findLeader (car) val dt = prop("rt")
// Step 1: compute next velocity using Gipps (discrete rule) val v = gipps(car, car_ahead, length) + EPSILON
// Step 2: update position in segment-local coordinates val x = integratorType match case IntegratorType.Ballistic => car.disp + car.velocity * dt case IntegratorType.butcher => butcher(car.disp, car.velocity, car.o_velocity, dt) case _ => car.disp + car.velocity * dt
// Step 3: commit velocity state AFTER position integration car.o_velocity = car.velocity car.velocity = v
// Step 4: segment-bounded displacement update car.o_t_disp = car.t_disp val new_disp = if x <= length then x else length
car.t_disp += new_disp - car.disp // derive t_disp from clamped delta car.disp = new_disp end updateM
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the velocity of the vehicle based on Gipps' model for a vehicle and its predecessor. * With per-segment DLLs, leader is always same-seg or next-seg. All positions are segment-local. * @param cn the current vehicle * @param cp the predecessor of the current vehicle (from findLeader — always same or next segment) */ def gipps (cn: Vehicle, cp: Vehicle, length: Double): Double = if cp == null then gipps (amax, bmax, len, cn.vmax, cn.disp, cn.velocity, cn.disp + 1000, cn.vmax, prop("rt")) else // Leader is in same segment or adjacent next segment val cp_r_disp = if cp.segId == cn.segId then cp.disp else length + cp.disp gipps (amax, bmax, len, cn.vmax, cn.disp, cn.velocity, cp_r_disp, cp.velocity, prop("rt")) end gipps //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** Return the velocity of the vehicle based on Gipps' model. * * @param an the max acceleration of drivers * @param bn the max deceleration of drivers (may be negative) * @param sp the size of vehicles * @param Vn the desired velocity of driver n * @param xn the current position of driver n * @param vn the current velocity of driver n * @param xp the current position of the predecessor (ahead) * @param vp the current velocity of the predecessor * @param rt the reaction time of drivers */ private def gipps(an: Double, bn: Double, sp: Double, Vn: Double, xn: Double, vn: Double, xp: Double, vp: Double, rt: Double): Double = // --------------- Parameters --------------------- val b = abs(bn) // use positive magnitude of deceleration val b_hat = b * 1.8 // expected braking ability of leader (default 0.8×b) b_hat >= b
// --------------- Free-flow branch --------------- // v_free = v_n + 2.5 * a_n * τ * (1 - v_n/V_n) * sqrt(0.025 + v_n/V_n) val free = vn + (2.5 * an * rt * (1.0 - vn / Vn)) * sqrt(0.025 + vn / Vn)
// --------------- Congested (safety) branch ------- // v_cong = b * τ + sqrt(b^2 * τ^2 - b[2(gap) - v_nτ - v_p^2/b̂]) val gap = xp - sp - xn // effective front-to-front gap val phi = 2.0 * gap - (vn * rt) - (vp * vp / b_hat) // safety term inside brackets
// When phi >= 0, spacing is large enough that braking constraint is inactive. // In that case, use free-flow velocity directly (skip sqrt computation). if phi >= 0.0 then return free
// Otherwise, apply the congested/safety branch. val inner_exp = (b * b * rt * rt) - b * phi // value inside sqrt val cong = (b * rt) + sqrt(max(0.0, inner_exp)) // braking (congested) velocity min(free, cong) end gipps
end GippsDynamics
object KraussDynamics extends Dynamics:
private val debug = debugf("KraussDynamics", false)
/** Krauss stochastic imperfection magnitude (m/s) * Must be small relative to amax*tau to allow net acceleration */ private val sigma = 0.2
/** Uniform random variate for stochastic noise */ private val noiseRV = scalation.random.Uniform(0.0, sigma)
/** Integrator type for position update (configurable, default Ballistic) */ var integratorType: IntegratorType = IntegratorType.Ballistic
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Update the vehicle's velocity and position using Krauss Model. * All gap and position computations use segment-local `disp` — consistent with * per-segment DLLs where the leader is always in the same or adjacent segment. * `t_disp` is updated as a derived statistic only. * @param car the vehicle to update * @param length the segment length */ def updateM(car: Vehicle, length: Double): Unit = val car_ahead = findLeader (car) val dt = prop("rt")
// Compute leader position and velocity (segment-local) val (xp, vp): (Double, Double) = if car_ahead == null then (car.disp + 1000.0, car.vmax) // phantom leader (free flow) else if car_ahead.segId == car.segId then (car_ahead.disp, car_ahead.velocity) else (length + car_ahead.disp, car_ahead.velocity)
// Step 1: Compute next velocity using Krauss val v_new = krauss( amax, bmax, len, car.vmax, car.disp, car.velocity, xp, vp, dt, s )
// Step 2: Position update in segment-local coordinates val x_new = integratorType match case IntegratorType.Ballistic => car.disp + car.velocity * dt case IntegratorType.butcher => butcher(car.disp, car.velocity, car.o_velocity, dt) case _ => car.disp + car.velocity * dt
// Step 3: Commit velocity state AFTER position update car.o_velocity = car.velocity car.velocity = v_new
// Step 4: Segment-bounded displacement update car.o_t_disp = car.t_disp val new_disp = if x_new <= length then x_new else length
car.t_disp += new_disp - car.disp // derive t_disp from clamped delta car.disp = new_disp end updateM
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Compute next velocity using Krauss car-following model. * Safety is enforced BEFORE stochastic noise is applied. * * @param an max acceleration * @param bn max deceleration (negative) * @param sp vehicle length * @param Vn desired speed * @param xn follower position * @param vn follower velocity * @param xp leader position * @param vp leader velocity * @param rt reaction time (timestep) * @param s0 minimum spacing */ private def krauss(an: Double, bn: Double, sp: Double, Vn: Double, xn: Double, vn: Double, xp: Double, vp: Double, rt: Double, s0: Double): Double = val b = abs(bn)
// Netto gap (front-to-rear) val gap = xp - xn - sp if gap <= 0.0 then return 0.0 // collision avoidance
// Krauss safe speed: v_safe = sqrt(v_leader^2 + 2*b*(gap - s0)) val inner = vp * vp + 2.0 * b * (gap - s0) val v_safe = sqrt(max(0.0, inner))
// Acceleration constraint: v_cap = v + a_max * tau val v_cap = vn + an * rt
// Desired speed constraint val v_des = Vn
// Deterministic candidate (minimum of all constraints) val v_star = min(v_des, min(v_safe, v_cap))
// Stochastic imperfection applied AFTER safety val eps = noiseRV.gen max(0.0, v_star - eps) end krauss
end KraussDynamics
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `IDMDynamics` object provides equations for the Intelligent Driver Model (IDM) * car-following model. * @see https://en.wikipedia.org/wiki/Intelligent_driver_model */
object IDMDynamics extends Dynamics:
private val debug = debugf ("IDMDynamics", true) // debug function
private val FREERANGE = 150.0
/** Configurable integrator type for ODE solving - default Ballistic */ var integratorType: IntegratorType = IntegratorType.Ballistic
/** Flag to print integrator type only once per simulation run */ private var integratorPrinted: Boolean = false
/** Reset the print flag - call this before each new simulation */ def resetIntegratorPrintFlag(): Unit = integratorPrinted = false
/** * @param car the vehicle to update * @param length the segment length */ def updateM(car: Vehicle, length: Double): Unit = val car_ahead = findLeader (car) val dt = rt
// Snapshot leader state (frozen during integration) val (x_leader, v_leader): (Double, Double) = // leader's (position, velocity) if car_ahead == null then (car.t_disp + 1000.0, car.velocity) // no leader: free-flow else if car_ahead.t_disp - car.t_disp > FREERANGE then (car.t_disp + 1000.0, car.velocity) // leader is far ahead: free-flow else (car_ahead.t_disp, car_ahead.velocity) // real leader: use it
// ───────────────────────────────────────────────────────────────────────── // STEP 2: Save old state for history tracking // ───────────────────────────────────────────────────────────────────────── val v_old = car.velocity val x_old = car.t_disp
/** * @param x_n Current position of driver n (from ODE solver trial values, NOT car.t_disp) * @param v_n Current velocity of driver n (from ODE solver trial values, NOT car.velocity) * @return IDM acceleration clamped to physical bounds [-bmax, amax] */ def idmAccel(x_n: Double, v_n: Double): Double = val b = abs(bmax)
// Call existing iDM with snapshotted leader state // iDM(an, bn, sp, Vn, xn, vn, xp, vp, T, s0, del) var a = iDM(amax, b, len, car.vmax, x_n, v_n, x_leader, v_leader, T, s, del)
// Clamp acceleration to physical bounds if a.isNaN || a.isInfinity then a = 0.0 if a < -b then a = -b if a > amax then a = amax a end idmAccel
// Array of derivative functions: [dx/dt, dv/dt] // dx/dt = v (velocity) returned directly from state vector // dv/dt = a (IDM acceleration) returned by idmAccel helper function val odes: Array[DerivativeV] = Array( (t: Double, y: VectorD) => y(1), // dx/dt = v (velocity) (t: Double, y: VectorD) => idmAccel(y(0), y(1)) // dv/dt = a (IDM acceleration) )
// ───────────────────────────────────────────────────────────────────────── // STEP 4: Solve the coupled system with selected integrator // ───────────────────────────────────────────────────────────────────────── val y0 = VectorD(car.t_disp, car.velocity) // initial state [x(t), v(t)]
// Print integrator type ONCE per simulation (from inside updateM, not from caller) if !integratorPrinted then println(s"[IDMDynamics.updateM] INTEGRATOR IN USE: $integratorType") integratorPrinted = true
// Select integrator based on integratorType setting val y1: VectorD = integratorType match case IntegratorType.DOPRI5 => DormandPrince.integrateVV(odes, y0, dt) case IntegratorType.RK4 => RungeKutta2.rk4.integrateVV(odes, y0, dt) case IntegratorType.RK3 => RungeKutta2.rk3.integrateVV(odes, y0, dt) case IntegratorType.RK2 => RungeKutta2.rk2.integrateVV(odes, y0, dt) case IntegratorType.Heun => RungeKutta2.heun.integrateVV(odes, y0, dt) case IntegratorType.Euler => RungeKutta2.euler.integrateVV(odes, y0, dt) case IntegratorType.butcher => // Butcher's 5th-order method (J.C. Butcher) - a quadrature rule using historical samples. // Apply twice: once for velocity (using acceleration history), once for position (using velocity history). // This maintains 5th-order accuracy for BOTH state variables.
// Step 1: Velocity via Butcher using acceleration history: a(t), a(t−τ) // v(t+τ) = v(t) + (1/90)(7k1 + 32k3 + 12k4 + 32k5 + 7k6)τ where k's interpolate a(t-τ) to a(t) val a_idm = idmAccel(car.t_disp, car.velocity) // a(t) from IDM val v_new_b = Vehicle.butcher( car.velocity, // v(t) - current velocity a_idm, // a(t) - current acceleration car.o_acc, // a(t−τ) - previous acceleration dt )
// Step 2: Position via Butcher using velocity history: v(t), v(t−τ) // x(t+τ) = x(t) + (1/90)(7k1 + 32k3 + 12k4 + 32k5 + 7k6)τ where k's interpolate v(t-τ) to v(t) val x_new_b = Vehicle.butcher( car.t_disp, // x(t) - current position car.velocity, // v(t) - current velocity car.o_velocity, // v(t−τ) - previous velocity dt ) VectorD(x_new_b, v_new_b) case IntegratorType.Ballistic => // Ballistic: compute IDM acceleration once, then kinematic update val a_idm = idmAccel(car.t_disp, car.velocity) val v_ball = car.velocity + a_idm * dt // v(t + dt) the new velocity val x_ball = car.t_disp + car.velocity * dt + 0.5 * a_idm * dt * dt // x(t + dt) VectorD(x_ball, v_ball) // construct new state vector
// ───────────────────────────────────────────────────────────────────────── // STEP 5: Extract and clamp results // ───────────────────────────────────────────────────────────────────────── val x_new = y1(0) // new position x(t + dt) var v_new = y1(1) // new velocity v(t + dt)
// Physical constraints: velocity must be non-negative and bounded if v_new < 0.0 then v_new = 0.0 // no backward motion if v_new > car.vmax then v_new = car.vmax // respect max speed
// Back-calculate acceleration for state storage val a = (v_new - v_old) / dt // average acceleration over dt
// ───────────────────────────────────────────────────────────────────────── // STEP 6: Update vehicle state // ───────────────────────────────────────────────────────────────────────── car.o_acc = car.acc // save old acceleration car.acc = a // update acceleration car.o_velocity = v_old // save old velocity car.velocity = v_new // update velocity car.o_t_disp = x_old // save old position
// ───────────────────────────────────────────────────────────────────────── // STEP 7: Segment-bounded displacement update // ───────────────────────────────────────────────────────────────────────── val dx = x_new - x_old // change in position val proposed_disp = car.disp + dx // proposed new displacement val new_disp = if proposed_disp <= length then proposed_disp else length // clamp to segment length
car.t_disp += new_disp - car.disp // update total position car.disp = new_disp // update displacement on segment end updateM
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the acceleration of the vehicle based on the Intelligent Driver Model * for a vehicle and its predecessor. * @param cn the current vehicle * @param cp the predecessor of the current vehicle * @param del the acceleration exponenent (defualts to 4) */ def iDM (cn: Vehicle, cp: Vehicle, del: Double = 4.0): Double = if cp == null then iDMFree (amax, cn.velocity, cn.vmax, del) else if cp.t_disp - cn.t_disp > FREERANGE then iDMFree (amax, cn.velocity, cn.vmax, del) else iDM (amax, abs(bmax), len, cn.vmax, cn.t_disp, cn.velocity, cp.t_disp, cp.velocity, T, s, del) end iDM
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the acceleration of the vehicle based on the Intelligent Driver Model. * @param an the max acceleration of drivers * @param bn the max deceleration of drivers (negative #) * @param sp the size of vehicles * @param Vn the desired velocity of driver n * @param xn the current position of driver n * @param vn the current velocity of driver n * @param xp the current position of the predecessor * @param vp the current velocity of the predecessor * @param T the safe min time headway * @param s0 the safe min distance headway * @param del the acceleration exponenent (defualts to 4) */ private def iDM (an: Double, bn: Double, sp: Double, Vn: Double, xn: Double, vn: Double, xp: Double, vp: Double, T: Double, s0: Double, del: Double): Double = val b = abs(bn) // use positive magnitude of deceleration val Δx = xp - xn - sp // front to rear gap val Δv = vn - vp // approach rate val ss = s0 + vn * T + (vn * Δv) / (2.0 * sqrt (an * b)) // desired gap an * (1.0 - (vn / Vn) ~^ del - (ss / Δx) ~^ 2.0) // acceleration end iDM
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the acceleration of the vehicle based on the Intelligent Driver Model * when there is no predecessor. * @param an the max acceleration of drivers * @param vn the current velocity of driver n * @param Vn the desired velocity of driver n * @param del the acceleration exponenent (defualts to 4) */ private def iDMFree (an: Double, vn: Double, Vn: Double, del: Double = 4.0): Double = an * (1.0 - (vn / Vn) ~^ del) end iDMFree
end IDMDynamics

//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** @author Bishi * @version 2.0 * @date Sat Mar 22 2026 * @see LICENSE (MIT style license file). * * @note Eaton Corridor Configuration — Station Map & GPS → Animation Coordinates * * Reads PeMS station_map.csv for the Eaton fire corridor (I-210 + SR-134), * categorizes stations by lane type (ML, HV, OR, FR, FF), and converts GPS * coordinates to animation screen positions using the Coordinates class. * * All stations are fed into a single Coordinates call so that I-210 and SR-134 * share one consistent animation coordinate frame. */
package scalation package simulation package process package config
import scala.io.Source import scala.collection.mutable.ArrayBuffer import scalation.banner // ScalaTion's formatted section header printer import scalation.mathstat.{VectorD, Plot}
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `StationRecord` case class represents one row from a PeMS station_map.csv. * @param stationId the PeMS station ID (e.g., 717615) * @param freeway the freeway number (e.g., 210, 134) * @param direction the direction ("W" or "E") * @param laneType the lane type ("ML", "HV", "OR", "FR", "FF") * @param latitude the GPS latitude * @param longitude the GPS longitude * @param absPM the absolute postmile (physical road ordering) * @param location the location name (e.g., "FAIR OAKS 1") * @param lanes the number of lanes at this station */ case class StationRecord (stationId: Int, freeway: Int, direction: String, laneType: String, latitude: Double, longitude: Double, absPM: Double, location: String, lanes: Int)
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `StationWithCoords` case class pairs a station record with its computed * animation screen coordinates. * @param record the station metadata from PeMS * @param screenXY the (x, y) animation screen position */ case class StationWithCoords (record: StationRecord, screenXY: (Double, Double))
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `CorridorLayout` case class bundles everything a traffic model needs * to instantiate Junction, Route, VSource, Sink, and Ramp objects from a * PeMS station_map.csv file. * * This is the intermediate representation between the CSV and the model — * analogous to SUMO's *.nod.xml + *.edg.xml + *.con.xml but derived from * a single flat file keyed on the `Lane Type` column. * * @param config the NetworkConfig topology (segments, ramps, sensors) * @param junctionNames human-readable names from the CSV Location field * @param mainlineScreenXY screen (x, y) positions for mainline Junction nodes * @param onRampScreenXY screen (x, y) positions for on-ramp Junction nodes (shifted) * @param offRampScreenXY screen (x, y) positions for off-ramp Junction nodes (shifted) * @param segmentLengths physical segment lengths in meters (from postmile differences) * @param ffStations freeway-to-freeway connector records (metadata, future use) */ case class CorridorLayout (config: NetworkConfig, junctionNames: Array [String], mainlineScreenXY: Array [(Double, Double)], onRampScreenXY: Array [(Double, Double)], offRampScreenXY: Array [(Double, Double)], segmentLengths: VectorD, ffStations: Array [StationRecord]):
/** All ramp screen positions (on-ramps first, then off-ramps). */ def allRampScreenXY: Array [(Double, Double)] = onRampScreenXY ++ offRampScreenXY
/** Number of mainline junctions. */ def numJunctions: Int = mainlineScreenXY.length
/** Number of on-ramps. */ def numOnRamps: Int = onRampScreenXY.length
/** Number of off-ramps. */ def numOffRamps: Int = offRampScreenXY.length
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Compute VSource center position and offsets for animation layout. * Center is near the first mainline junction. Each ramp VSource is offset * relative to this center using a large shift so it does not overlap the road. */ def getVSourceCenterAndOffsets: ((Int, Int), Array [(Int, Int)]) = val centerPos = ((mainlineScreenXY(0)._1 - 50.0).toInt, (mainlineScreenXY(0)._2 + 50.0).toInt) val (dx, dy) = (800.0, -350.0) val nOR = onRampScreenXY.length val offsets = new Array [(Int, Int)] (1 + nOR) offsets(0) = (0, 0) // mainline offset cfor (0, nOR) { r => offsets(r + 1) = ( (onRampScreenXY(r)._1 + dx).toInt - centerPos._1, (onRampScreenXY(r)._2 + dy).toInt - centerPos._2 ) } (centerPos, offsets) end getVSourceCenterAndOffsets
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Print a summary of this corridor layout. */ def summary (): Unit = println ("\n" + "=" * 70) println ("CORRIDOR LAYOUT SUMMARY") println ("=" * 70) println (s"Corridor: ${config.mainline.id}") println (s"Junctions: ${mainlineScreenXY.length}") println (s"Segments: ${config.mainline.segments}") println (s"Lanes: ${config.mainline.lanesPerSegment}") println (s"On-Ramps: ${onRampScreenXY.length}") println (s"Off-Ramps: ${offRampScreenXY.length}") println (s"FF Connectors: ${ffStations.length}") println (s"Sensors: ${config.sensors.length}") println (f"Total Length: ${segmentLengths.sum}%.0f m (${segmentLengths.sum / 1609.34}%.2f mi)") println ("=" * 70)
println ("\nJunctions (by postmile):") cfor (0, junctionNames.length) { i => val (sx, sy) = mainlineScreenXY(i) println (f" j$i%3d ${junctionNames(i)}%-28s Screen($sx%7.1f, $sy%7.1f)") }
println (s"\nOn-Ramps (${config.ramps.count (_.mode == RampMode.On)}):") for r <- config.ramps if r.mode == RampMode.On do println (f" ${r.id}%-35s joinSeg=${r.joinSegment}%3d [${r.lanes} lane(s)]")
println (s"\nOff-Ramps (${config.ramps.count (_.mode == RampMode.Off)}):") for r <- config.ramps if r.mode == RampMode.Off do println (f" ${r.id}%-35s joinSeg=${r.joinSegment}%3d [${r.lanes} lane(s)]")
if ffStations.nonEmpty then println (s"\nFF Connectors (${ffStations.length}):") cfor (0, ffStations.length) { i => val ff = ffStations(i) println (f" ${ff.stationId}%6d ${ff.location}%-28s PM=${ff.absPM}%7.3f") } println ("=" * 70) end summary
end CorridorLayout
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `EatonCorridorConfig` object loads the Eaton fire corridor station map * and computes animation coordinates for all stations. * * Pipeline: station_map.csv → StationRecord → GPS (lat, lon) * → Coordinates class → screen (x, y) * * Usage: * {{{ * val stations = EatonCorridorConfig.loadStationMap () * val all = EatonCorridorConfig.computeAllCoordinates (stations) * val i210wML = EatonCorridorConfig.filterByFreewayDir (all, 210, "W") * |> EatonCorridorConfig.filterByLaneType (_, "ML") * }}} */ object EatonCorridorConfig:
// Master station map — contains ALL stations for I-210 (W+E) and SR-134 (W) // 194 rows: 77 I-210 W + 73 I-210 E + 43 SR-134 W private val STATION_MAP_PATH = "data/WSC-Pems-Data-Eaton-Fire/data-eaton/pems/eaton-corridor/station_map.csv"
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Load all station records from a PeMS station_map.csv file. * @param path the path to station_map.csv (default: Eaton corridor master file) */ def loadStationMap (path: String = STATION_MAP_PATH): Array [StationRecord] = val source = Source.fromFile (path) val buf = ArrayBuffer [StationRecord] () try val lines = source.getLines ().drop (1) // skip header row for line <- lines if line.trim.nonEmpty do val c = line.split (",", -1).map (_.trim) // split CSV, keep empty trailing fields buf += StationRecord ( stationId = c(0).toInt, // PeMS VDS ID (e.g., 717615) freeway = c(1).toInt, // 210 or 134 direction = c(2), // "W" or "E" laneType = c(3), // "ML", "HV", "OR", "FR", "FF" latitude = c(4).toDouble, // GPS lat longitude = c(5).toDouble, // GPS lon absPM = c(6).toDouble, // absolute postmile — defines road order location = c(7), // human-readable name (e.g., "FAIR OAKS 1") lanes = if c.length > 8 && c(8).nonEmpty then c(8).toInt else 0 // lane count (0 if missing) ) end for finally source.close () buf.toArray end loadStationMap
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Compute animation coordinates for all stations in one shared coordinate frame. * All GPS points go into a single `Coordinates` call so that I-210 and SR-134 * are positioned correctly relative to each other on screen. * @param stations all station records to convert * @param dims animation window dimensions (width, height) in pixels */ def computeAllCoordinates (stations: Array [StationRecord], dims: (Double, Double) = (1500.0, 1500.0)): Array [StationWithCoords] = val n = stations.length val gps = Array.ofDim [(Double, Double)] (n) // collect all GPS pairs cfor (0, n) { i => gps(i) = (stations(i).latitude, stations(i).longitude) }
// ONE Coordinates call — all stations share the same animation frame // so I-210 and SR-134 appear in correct spatial relationship val coords = new scalation.Coordinates (dims._1, dims._2, gps) // GPS → CTM → screen (x, y) val result = Array.ofDim [StationWithCoords] (n) cfor (0, n) { i => result(i) = StationWithCoords (stations(i), coords.aniCoords(i)) } result end computeAllCoordinates
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Filter paired stations by freeway number and direction, sorted by postmile. * @param all all paired station-coordinate records * @param freeway the freeway number (210 or 134) * @param dir the direction ("W" or "E") */ def filterByFreewayDir (all: Array [StationWithCoords], freeway: Int, dir: String): Array [StationWithCoords] = val buf = ArrayBuffer [StationWithCoords] () cfor (0, all.length) { i => val s = all(i) if s.record.freeway == freeway && s.record.direction == dir then buf += s } buf.sortBy (_.record.absPM).toArray // sort by postmile = physical road order end filterByFreewayDir
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Filter paired stations by lane type, sorted by postmile. * @param corridor stations for a specific corridor * @param laneType the lane type ("ML", "HV", "OR", "FR", "FF") */ def filterByLaneType (corridor: Array [StationWithCoords], laneType: String): Array [StationWithCoords] = val buf = ArrayBuffer [StationWithCoords] () cfor (0, corridor.length) { i => if corridor(i).record.laneType == laneType then buf += corridor(i) } buf.sortBy (_.record.absPM).toArray // maintain road order within type end filterByLaneType
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Build a complete `CorridorLayout` from the station map for a single * freeway corridor. This is the main entry point for the CSV-to-Model * translation protocol. * * Algorithm: * 1. Load station_map.csv → StationRecord array * 2. Filter to the requested corridor (freeway + direction) * 3. Compute screen coordinates (one Coordinates call for the corridor) * 4. Classify by Lane Type → ML, OR, FR, FF * 5. ML stations sorted by absPM → junction positions and segments * 6. OR/FR stations matched to nearest ML segment by absPM → RampSpec * 7. Bundle into CorridorLayout * * @param freeway the freeway number (e.g., 210, 134) * @param direction the direction (e.g., "W", "E") * @param corridorId the identifier string (e.g., "I-210-W") * @param dims animation window dimensions (width, height) in pixels * @param rampShift lateral pixel shift for ramp junctions so they don't overlap mainline */ def buildCorridorLayout (freeway: Int, direction: String, corridorId: String, dims: (Double, Double) = (1500.0, 1500.0), rampShift: (Double, Double) = (65.0, -70.0)): CorridorLayout =
// 1. Load all stations and filter to corridor at the record level val allRecords = loadStationMap () val corridorRecords = allRecords.filter (s => s.freeway == freeway && s.direction == direction)
// 2. Compute screen coordinates for just this corridor (one shared frame) val corridorWithCoords = computeAllCoordinates (corridorRecords, dims)
// 3. Classify by lane type (each returns sorted by absPM) val mlStations = filterByLaneType (corridorWithCoords, "ML") val orStations = filterByLaneType (corridorWithCoords, "OR") val frStations = filterByLaneType (corridorWithCoords, "FR") val ffStations = filterByLaneType (corridorWithCoords, "FF")
val nML = mlStations.length assert (nML >= 2, s"buildCorridorLayout: need >= 2 ML stations, found $nML")
// 4. ML postmiles define junction positions (sorted ascending) val mlPMs = new Array [Double] (nML) cfor (0, nML) { i => mlPMs(i) = mlStations(i).record.absPM }
// 5. Lane count = statistical mode of ML station lane counts val laneCounts = new Array [Int] (nML) cfor (0, nML) { i => laneCounts(i) = mlStations(i).record.lanes } val lanesPerSegment = modeLanes (laneCounts)
// 6. Junction names from Location field val junctionNames = new Array [String] (nML) cfor (0, nML) { i => junctionNames(i) = mlStations(i).record.location }
// 7. Segment lengths from PM differences (miles → meters) val nSegments = nML - 1 val segLens = new VectorD (nSegments) cfor (0, nSegments) { i => segLens(i) = (mlPMs(i + 1) - mlPMs(i)) * 1609.34 }
// 8. Map OR stations → RampSpec (mode = On), joinSegment by absPM proximity val onRamps = ArrayBuffer [RampSpec] () cfor (0, orStations.length) { r => val pm = orStations(r).record.absPM val seg = findJoinSegment (pm, mlPMs) val loc = orStations(r).record.location.replace (" ", "_") onRamps += RampSpec ( id = s"onramp_${orStations(r).record.stationId}_$loc", joinSegment = seg, mode = RampMode.On, lanes = orStations(r).record.lanes ) }
// 9. Map FR stations → RampSpec (mode = Off), joinSegment by absPM proximity val offRamps = ArrayBuffer [RampSpec] () cfor (0, frStations.length) { r => val pm = frStations(r).record.absPM val seg = findJoinSegment (pm, mlPMs) val loc = frStations(r).record.location.replace (" ", "_") offRamps += RampSpec ( id = s"offramp_${frStations(r).record.stationId}_$loc", joinSegment = seg, mode = RampMode.Off, lanes = frStations(r).record.lanes ) }
// 10. Sensors: one per ML station, keyed by station ID val sensors = ArrayBuffer [SensorSpec] () cfor (0, nML) { i => sensors += SensorSpec ( id = s"sensor_${mlStations(i).record.stationId}", segment = i ) }
// 11. Assemble NetworkConfig val networkConfig = NetworkConfig ( mainline = MainlineSpec ( id = corridorId, segments = nSegments, lanesPerSegment = lanesPerSegment, segmentLengths = Some (segLens) ), ramps = onRamps.toList ++ offRamps.toList, sensors = sensors.toList )
// 12. Screen coordinates — mainline from ML stations val mainlineScreenXY = new Array [(Double, Double)] (nML) cfor (0, nML) { i => mainlineScreenXY(i) = mlStations(i).screenXY }
// 13. Screen coordinates — on-ramps with lateral shift val onRampScreenXY = new Array [(Double, Double)] (orStations.length) cfor (0, orStations.length) { i => val (sx, sy) = orStations(i).screenXY onRampScreenXY(i) = (sx + rampShift._1, sy + rampShift._2) }
// 14. Screen coordinates — off-ramps with lateral shift (opposite direction) val offRampScreenXY = new Array [(Double, Double)] (frStations.length) cfor (0, frStations.length) { i => val (sx, sy) = frStations(i).screenXY offRampScreenXY(i) = (sx - rampShift._1, sy + rampShift._2) }
// 15. FF station records (metadata for future use) val ffRecords = new Array [StationRecord] (ffStations.length) cfor (0, ffStations.length) { i => ffRecords(i) = ffStations(i).record }
// 16. Bundle CorridorLayout ( config = networkConfig, junctionNames = junctionNames, mainlineScreenXY = mainlineScreenXY, onRampScreenXY = onRampScreenXY, offRampScreenXY = offRampScreenXY, segmentLengths = segLens, ffStations = ffRecords ) end buildCorridorLayout
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Find the segment index where a ramp (OR/FR) merges or diverges. * Uses binary search: find the largest ML index whose postmile <= rampPM. * @param rampPM the ramp's absolute postmile * @param mlPMs the sorted array of ML station postmiles */ private def findJoinSegment (rampPM: Double, mlPMs: Array [Double]): Int = var i = mlPMs.length - 1 while i >= 0 && mlPMs(i) > rampPM do i -= 1 math.max (0, math.min (i, mlPMs.length - 2)) // clamp to valid segment range end findJoinSegment
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Compute the statistical mode (most frequent value) of an integer array. * Used to determine the representative lane count across ML stations. * @param arr the array of integer values */ private def modeLanes (arr: Array [Int]): Int = val counts = scala.collection.mutable.Map [Int, Int] () cfor (0, arr.length) { i => val v = arr(i) counts(v) = counts.getOrElse (v, 0) + 1 } counts.maxBy (_._2)._1 end modeLanes
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: // Pre-built corridor layouts (lazy — loaded on first access) //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** I-210 Westbound — Eaton fire evacuation direction (27 ML, 22 OR, 18 FR). */ lazy val I210_WB: CorridorLayout = buildCorridorLayout (210, "W", "I-210-W")
/** I-210 Eastbound — contraflow direction (future). */ lazy val I210_EB: CorridorLayout = buildCorridorLayout (210, "E", "I-210-E")
/** SR-134 Westbound — alternate evacuation route (13 ML). */ lazy val SR134_WB: CorridorLayout = buildCorridorLayout (134, "W", "SR-134-W")
end EatonCorridorConfig
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Plot station GPS positions as a spatial scatter (longitude vs latitude). * Produces a bird's-eye view comparable to Google Maps. * @param stations the stations to plot * @param title the plot window title */ private def plotGPSMap (stations: Array [StationWithCoords], title: String): Unit = val n = stations.length val lon = new VectorD (n) // x-axis: longitude (east-west) val lat = new VectorD (n) // y-axis: latitude (north-south) cfor (0, n) { i => lon(i) = stations(i).record.longitude lat(i) = stations(i).record.latitude } new Plot (lon, lat, null, title, lines = false) end plotGPSMap
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Print stations grouped by lane type for a given corridor. * @param corridor the filtered corridor stations with screen coordinates * @param laneTypes the lane types to report */ private def printStationsByType (corridor: Array [StationWithCoords], laneTypes: Array [String]): Unit = cfor (0, laneTypes.length) { t => val typed = EatonCorridorConfig.filterByLaneType (corridor, laneTypes(t)) if typed.nonEmpty then println (s"\n ${laneTypes(t)} — ${typed.length} stations:") cfor (0, typed.length) { i => val r = typed(i).record val (sx, sy) = typed(i).screenXY // animation pixel position println (f" ${r.stationId}%6d ${r.location}%-25s PM=${r.absPM}%7.3f " + f"GPS(${r.latitude}%.6f, ${r.longitude}%.6f) → " + f"Screen($sx%7.1f, $sy%7.1f) [${r.lanes} lanes]") } end if } end printStationsByType
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Test the Eaton corridor GPS → animation coordinate pipeline. * Loads station_map.csv, computes screen coordinates for all stations in one * shared frame, and prints the GPS → Screen mapping by corridor and lane type. * * > runMain scalation.simulation.process.config.testEatonCorridorCoords */ @main def testEatonCorridorCoords (): Unit =
import EatonCorridorConfig.*
banner ("Eaton Corridor: Station Map → Animation Coordinates")
// 1. Load all 194 stations from master station_map.csv val stations = loadStationMap () println (s"Total stations loaded: ${stations.length}")
// 2. Compute aniCoords — ALL stations in one Coordinates call // so I-210 W, I-210 E, and SR-134 W share one animation frame val all = computeAllCoordinates (stations) println (s"Coordinates computed: ${all.length} stations")
// 3. Report: for each corridor (I-210 WB, I-210 EB, SR-134 WB), // print stations grouped by lane type (ML, HV, OR, FR, FF) val corridors = Array ((210, "W"), (134, "W")) // WB only — evacuation direction val laneTypes = Array ("ML", "HV", "OR", "FR", "FF") // ML=mainline, HV=HOV, OR=on-ramp, FR=off-ramp, FF=freeway-freeway
cfor (0, corridors.length) { c => val (fwy, dir) = corridors(c) val label = if fwy == 134 then s"SR-$fwy" else s"I-$fwy" banner (s"$label ${dir}B") val corridor = filterByFreewayDir (all, fwy, dir) // filter to this corridor, sorted by PM println (s"Total stations in corridor: ${corridor.length}") printStationsByType (corridor, laneTypes) // print each lane type group }
// 4. Single combined GPS spatial map — WB corridors only (evacuation direction) val wbOnly = filterByFreewayDir (all, 210, "W") ++ filterByFreewayDir (all, 134, "W") plotGPSMap (wbOnly, "Eaton Corridor — I-210 WB + SR-134 WB")
end testEatonCorridorCoords
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Test the CSV-to-Model corridor layout builder. * Builds a `CorridorLayout` for I-210 Westbound and prints the full summary * including junction positions, ramp→segment mappings, and segment lengths. * * > runMain scalation.simulation.process.config.testBuildCorridorLayout */ @main def testBuildCorridorLayout (): Unit =
banner ("CorridorLayout Builder: I-210 Westbound")
// Build the layout — this runs the full CSV-to-Model pipeline val layout = EatonCorridorConfig.I210_WB layout.summary ()
// Verify segment lengths banner ("Segment Lengths") cfor (0, layout.segmentLengths.dim) { i => val name0 = layout.junctionNames(i) val name1 = layout.junctionNames(i + 1) println (f" seg $i%3d: $name0%-28s → $name1%-28s ${layout.segmentLengths(i)}%8.1f m (${layout.segmentLengths(i) / 1609.34}%.3f mi)") }
// Verify VSource center and offsets banner ("VSource Positions") val (center, offsets) = layout.getVSourceCenterAndOffsets println (s" Center: $center") cfor (0, offsets.length) { i => val label = if i == 0 then "mainline" else s"onRamp$i" println (f" $label%-12s offset = ${offsets(i)}") }
// Verify NetworkConfig compatibility banner ("NetworkConfig") val nc = layout.config println (s" mainline.id = ${nc.mainline.id}") println (s" mainline.segments = ${nc.mainline.segments}") println (s" mainline.lanes = ${nc.mainline.lanesPerSegment}") println (s" ramps (total) = ${nc.ramps.length}") println (s" ramps (On) = ${nc.ramps.count (_.mode == RampMode.On)}") println (s" ramps (Off) = ${nc.ramps.count (_.mode == RampMode.Off)}") println (s" sensors = ${nc.sensors.length}") println (s" numJunctions = ${nc.numJunctions}") println (s" pemsSensorIndices = ${nc.pemsSensorIndices.mkString (", ")}")
banner ("SR-134 Westbound (quick check)") val sr134 = EatonCorridorConfig.SR134_WB sr134.summary ()
end testBuildCorridorLayout

//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** @author Bishi * @version 2.0 * @date Sat Mar 22 2026 * @see LICENSE (MIT style license file). * * @note Eaton Corridor Configuration — Station Map & GPS → Animation Coordinates * * Reads PeMS station_map.csv for the Eaton fire corridor (I-210 + SR-134), * categorizes stations by lane type (ML, HV, OR, FR, FF), and converts GPS * coordinates to animation screen positions using the Coordinates class. * * All stations are fed into a single Coordinates call so that I-210 and SR-134 * share one consistent animation coordinate frame. */
package scalation package simulation package process package config
import scala.io.Source import scala.collection.mutable.ArrayBuffer import scalation.banner // ScalaTion's formatted section header printer import scalation.mathstat.{VectorD, Plot}
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `StationRecord` case class represents one row from a PeMS station_map.csv. * @param stationId the PeMS station ID (e.g., 717615) * @param freeway the freeway number (e.g., 210, 134) * @param direction the direction ("W" or "E") * @param laneType the lane type ("ML", "HV", "OR", "FR", "FF") * @param latitude the GPS latitude * @param longitude the GPS longitude * @param absPM the absolute postmile (physical road ordering) * @param location the location name (e.g., "FAIR OAKS 1") * @param lanes the number of lanes at this station */ case class StationRecord (stationId: Int, freeway: Int, direction: String, laneType: String, latitude: Double, longitude: Double, absPM: Double, location: String, lanes: Int)
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `StationWithCoords` case class pairs a station record with its computed * animation screen coordinates. * @param record the station metadata from PeMS * @param screenXY the (x, y) animation screen position */ case class StationWithCoords (record: StationRecord, screenXY: (Double, Double))
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `CorridorLayout` case class bundles everything a traffic model needs * to instantiate Junction, Route, VSource, Sink, and Ramp objects from a * PeMS station_map.csv file. * * This is the intermediate representation between the CSV and the model — * analogous to SUMO's *.nod.xml + *.edg.xml + *.con.xml but derived from * a single flat file keyed on the `Lane Type` column. * * @param config the NetworkConfig topology (segments, ramps, sensors) * @param junctionNames human-readable names from the CSV Location field * @param mainlineScreenXY screen (x, y) positions for mainline Junction nodes * @param onRampScreenXY screen (x, y) positions for on-ramp Junction nodes (shifted) * @param offRampScreenXY screen (x, y) positions for off-ramp Junction nodes (shifted) * @param segmentLengths physical segment lengths in meters (from postmile differences) * @param ffStations freeway-to-freeway connector records (metadata, future use) */ case class CorridorLayout (config: NetworkConfig, junctionNames: Array [String], mainlineScreenXY: Array [(Double, Double)], onRampScreenXY: Array [(Double, Double)], offRampScreenXY: Array [(Double, Double)], segmentLengths: VectorD, ffStations: Array [StationRecord]):
/** All ramp screen positions (on-ramps first, then off-ramps). */ def allRampScreenXY: Array [(Double, Double)] = onRampScreenXY ++ offRampScreenXY
/** Number of mainline junctions. */ def numJunctions: Int = mainlineScreenXY.length
/** Number of on-ramps. */ def numOnRamps: Int = onRampScreenXY.length
/** Number of off-ramps. */ def numOffRamps: Int = offRampScreenXY.length
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Compute VSource center position and offsets for animation layout. * Center is near the first mainline junction. Each ramp VSource is offset * relative to this center using a large shift so it does not overlap the road. */ def getVSourceCenterAndOffsets: ((Int, Int), Array [(Int, Int)]) = val centerPos = ((mainlineScreenXY(0)._1 - 50.0).toInt, (mainlineScreenXY(0)._2 + 50.0).toInt) val (dx, dy) = (800.0, -350.0) val nOR = onRampScreenXY.length val offsets = new Array [(Int, Int)] (1 + nOR) offsets(0) = (0, 0) // mainline offset cfor (0, nOR) { r => offsets(r + 1) = ( (onRampScreenXY(r)._1 + dx).toInt - centerPos._1, (onRampScreenXY(r)._2 + dy).toInt - centerPos._2 ) } (centerPos, offsets) end getVSourceCenterAndOffsets
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Print a summary of this corridor layout. */ def summary (): Unit = println ("\n" + "=" * 70) println ("CORRIDOR LAYOUT SUMMARY") println ("=" * 70) println (s"Corridor: ${config.mainline.id}") println (s"Junctions: ${mainlineScreenXY.length}") println (s"Segments: ${config.mainline.segments}") println (s"Lanes: ${config.mainline.lanesPerSegment}") println (s"On-Ramps: ${onRampScreenXY.length}") println (s"Off-Ramps: ${offRampScreenXY.length}") println (s"FF Connectors: ${ffStations.length}") println (s"Sensors: ${config.sensors.length}") println (f"Total Length: ${segmentLengths.sum}%.0f m (${segmentLengths.sum / 1609.34}%.2f mi)") println ("=" * 70)
println ("\nJunctions (by postmile):") cfor (0, junctionNames.length) { i => val (sx, sy) = mainlineScreenXY(i) println (f" j$i%3d ${junctionNames(i)}%-28s Screen($sx%7.1f, $sy%7.1f)") }
println (s"\nOn-Ramps (${config.ramps.count (_.mode == RampMode.On)}):") for r <- config.ramps if r.mode == RampMode.On do println (f" ${r.id}%-35s joinSeg=${r.joinSegment}%3d [${r.lanes} lane(s)]")
println (s"\nOff-Ramps (${config.ramps.count (_.mode == RampMode.Off)}):") for r <- config.ramps if r.mode == RampMode.Off do println (f" ${r.id}%-35s joinSeg=${r.joinSegment}%3d [${r.lanes} lane(s)]")
if ffStations.nonEmpty then println (s"\nFF Connectors (${ffStations.length}):") cfor (0, ffStations.length) { i => val ff = ffStations(i) println (f" ${ff.stationId}%6d ${ff.location}%-28s PM=${ff.absPM}%7.3f") } println ("=" * 70) end summary
end CorridorLayout
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `EatonCorridorConfig` object loads the Eaton fire corridor station map * and computes animation coordinates for all stations. * * Pipeline: station_map.csv → StationRecord → GPS (lat, lon) * → Coordinates class → screen (x, y) * * Usage: * {{{ * val stations = EatonCorridorConfig.loadStationMap () * val all = EatonCorridorConfig.computeAllCoordinates (stations) * val i210wML = EatonCorridorConfig.filterByFreewayDir (all, 210, "W") * |> EatonCorridorConfig.filterByLaneType (_, "ML") * }}} */ object EatonCorridorConfig:
// Master station map — contains ALL stations for I-210 (W+E) and SR-134 (W) // 194 rows: 77 I-210 W + 73 I-210 E + 43 SR-134 W private val STATION_MAP_PATH = "data/WSC-Pems-Data-Eaton-Fire/data-eaton/pems/eaton-corridor/station_map.csv"
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Load all station records from a PeMS station_map.csv file. * @param path the path to station_map.csv (default: Eaton corridor master file) */ def loadStationMap (path: String = STATION_MAP_PATH): Array [StationRecord] = val source = Source.fromFile (path) val buf = ArrayBuffer [StationRecord] () try val lines = source.getLines ().drop (1) // skip header row for line <- lines if line.trim.nonEmpty do val c = line.split (",", -1).map (_.trim) // split CSV, keep empty trailing fields buf += StationRecord ( stationId = c(0).toInt, // PeMS VDS ID (e.g., 717615) freeway = c(1).toInt, // 210 or 134 direction = c(2), // "W" or "E" laneType = c(3), // "ML", "HV", "OR", "FR", "FF" latitude = c(4).toDouble, // GPS lat longitude = c(5).toDouble, // GPS lon absPM = c(6).toDouble, // absolute postmile — defines road order location = c(7), // human-readable name (e.g., "FAIR OAKS 1") lanes = if c.length > 8 && c(8).nonEmpty then c(8).toInt else 0 // lane count (0 if missing) ) end for finally source.close () buf.toArray end loadStationMap
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Compute animation coordinates for all stations in one shared coordinate frame. * All GPS points go into a single `Coordinates` call so that I-210 and SR-134 * are positioned correctly relative to each other on screen. * @param stations all station records to convert * @param dims animation window dimensions (width, height) in pixels */ def computeAllCoordinates (stations: Array [StationRecord], dims: (Double, Double) = (1500.0, 1500.0)): Array [StationWithCoords] = val n = stations.length val gps = Array.ofDim [(Double, Double)] (n) // collect all GPS pairs cfor (0, n) { i => gps(i) = (stations(i).latitude, stations(i).longitude) }
// ONE Coordinates call — all stations share the same animation frame // so I-210 and SR-134 appear in correct spatial relationship val coords = new scalation.Coordinates (dims._1, dims._2, gps) // GPS → CTM → screen (x, y) val result = Array.ofDim [StationWithCoords] (n) cfor (0, n) { i => result(i) = StationWithCoords (stations(i), coords.aniCoords(i)) } result end computeAllCoordinates
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Filter paired stations by freeway number and direction, sorted by postmile. * @param all all paired station-coordinate records * @param freeway the freeway number (210 or 134) * @param dir the direction ("W" or "E") */ def filterByFreewayDir (all: Array [StationWithCoords], freeway: Int, dir: String): Array [StationWithCoords] = val buf = ArrayBuffer [StationWithCoords] () cfor (0, all.length) { i => val s = all(i) if s.record.freeway == freeway && s.record.direction == dir then buf += s } buf.sortBy (_.record.absPM).toArray // sort by postmile = physical road order end filterByFreewayDir
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Filter paired stations by lane type, sorted by postmile. * @param corridor stations for a specific corridor * @param laneType the lane type ("ML", "HV", "OR", "FR", "FF") */ def filterByLaneType (corridor: Array [StationWithCoords], laneType: String): Array [StationWithCoords] = val buf = ArrayBuffer [StationWithCoords] () cfor (0, corridor.length) { i => if corridor(i).record.laneType == laneType then buf += corridor(i) } buf.sortBy (_.record.absPM).toArray // maintain road order within type end filterByLaneType
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Build a complete `CorridorLayout` from the station map for a single * freeway corridor. This is the main entry point for the CSV-to-Model * translation protocol. * * Algorithm: * 1. Load station_map.csv → StationRecord array * 2. Filter to the requested corridor (freeway + direction) * 3. Compute screen coordinates (one Coordinates call for the corridor) * 4. Classify by Lane Type → ML, OR, FR, FF * 5. ML stations sorted by absPM → junction positions and segments * 6. OR/FR stations matched to nearest ML segment by absPM → RampSpec * 7. Bundle into CorridorLayout * * @param freeway the freeway number (e.g., 210, 134) * @param direction the direction (e.g., "W", "E") * @param corridorId the identifier string (e.g., "I-210-W") * @param dims animation window dimensions (width, height) in pixels * @param rampShift lateral pixel shift for ramp junctions so they don't overlap mainline */ def buildCorridorLayout (freeway: Int, direction: String, corridorId: String, dims: (Double, Double) = (1500.0, 1500.0), rampShift: (Double, Double) = (65.0, -70.0)): CorridorLayout =
// 1. Load all stations and filter to corridor at the record level val allRecords = loadStationMap () val corridorRecords = allRecords.filter (s => s.freeway == freeway && s.direction == direction)
// 2. Compute screen coordinates for just this corridor (one shared frame) val corridorWithCoords = computeAllCoordinates (corridorRecords, dims)
// 3. Classify by lane type (each returns sorted by absPM) val mlStations = filterByLaneType (corridorWithCoords, "ML") val orStations = filterByLaneType (corridorWithCoords, "OR") val frStations = filterByLaneType (corridorWithCoords, "FR") val ffStations = filterByLaneType (corridorWithCoords, "FF")
val nML = mlStations.length assert (nML >= 2, s"buildCorridorLayout: need >= 2 ML stations, found $nML")
// 4. ML postmiles define junction positions (sorted ascending) val mlPMs = new Array [Double] (nML) cfor (0, nML) { i => mlPMs(i) = mlStations(i).record.absPM }
// 5. Lane count = statistical mode of ML station lane counts val laneCounts = new Array [Int] (nML) cfor (0, nML) { i => laneCounts(i) = mlStations(i).record.lanes } val lanesPerSegment = modeLanes (laneCounts)
// 6. Junction names from Location field val junctionNames = new Array [String] (nML) cfor (0, nML) { i => junctionNames(i) = mlStations(i).record.location }
// 7. Segment lengths from PM differences (miles → meters) val nSegments = nML - 1 val segLens = new VectorD (nSegments) cfor (0, nSegments) { i => segLens(i) = (mlPMs(i + 1) - mlPMs(i)) * 1609.34 }
// 8. Map OR stations → RampSpec (mode = On), joinSegment by absPM proximity val onRamps = ArrayBuffer [RampSpec] () cfor (0, orStations.length) { r => val pm = orStations(r).record.absPM val seg = findJoinSegment (pm, mlPMs) val loc = orStations(r).record.location.replace (" ", "_") onRamps += RampSpec ( id = s"onramp_${orStations(r).record.stationId}_$loc", joinSegment = seg, mode = RampMode.On, lanes = orStations(r).record.lanes ) }
// 9. Map FR stations → RampSpec (mode = Off), joinSegment by absPM proximity val offRamps = ArrayBuffer [RampSpec] () cfor (0, frStations.length) { r => val pm = frStations(r).record.absPM val seg = findJoinSegment (pm, mlPMs) val loc = frStations(r).record.location.replace (" ", "_") offRamps += RampSpec ( id = s"offramp_${frStations(r).record.stationId}_$loc", joinSegment = seg, mode = RampMode.Off, lanes = frStations(r).record.lanes ) }
// 10. Sensors: one per ML station, keyed by station ID val sensors = ArrayBuffer [SensorSpec] () cfor (0, nML) { i => sensors += SensorSpec ( id = s"sensor_${mlStations(i).record.stationId}", segment = i ) }
// 11. Assemble NetworkConfig val networkConfig = NetworkConfig ( mainline = MainlineSpec ( id = corridorId, segments = nSegments, lanesPerSegment = lanesPerSegment, segmentLengths = Some (segLens) ), ramps = onRamps.toList ++ offRamps.toList, sensors = sensors.toList )
// 12. Screen coordinates — mainline from ML stations val mainlineScreenXY = new Array [(Double, Double)] (nML) cfor (0, nML) { i => mainlineScreenXY(i) = mlStations(i).screenXY }
// 13. Screen coordinates — on-ramps with lateral shift val onRampScreenXY = new Array [(Double, Double)] (orStations.length) cfor (0, orStations.length) { i => val (sx, sy) = orStations(i).screenXY onRampScreenXY(i) = (sx + rampShift._1, sy + rampShift._2) }
// 14. Screen coordinates — off-ramps with lateral shift (opposite direction) val offRampScreenXY = new Array [(Double, Double)] (frStations.length) cfor (0, frStations.length) { i => val (sx, sy) = frStations(i).screenXY offRampScreenXY(i) = (sx - rampShift._1, sy + rampShift._2) }
// 15. FF station records (metadata for future use) val ffRecords = new Array [StationRecord] (ffStations.length) cfor (0, ffStations.length) { i => ffRecords(i) = ffStations(i).record }
// 16. Bundle CorridorLayout ( config = networkConfig, junctionNames = junctionNames, mainlineScreenXY = mainlineScreenXY, onRampScreenXY = onRampScreenXY, offRampScreenXY = offRampScreenXY, segmentLengths = segLens, ffStations = ffRecords ) end buildCorridorLayout
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Find the segment index where a ramp (OR/FR) merges or diverges. * Uses binary search: find the largest ML index whose postmile <= rampPM. * @param rampPM the ramp's absolute postmile * @param mlPMs the sorted array of ML station postmiles */ private def findJoinSegment (rampPM: Double, mlPMs: Array [Double]): Int = var i = mlPMs.length - 1 while i >= 0 && mlPMs(i) > rampPM do i -= 1 math.max (0, math.min (i, mlPMs.length - 2)) // clamp to valid segment range end findJoinSegment
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Compute the statistical mode (most frequent value) of an integer array. * Used to determine the representative lane count across ML stations. * @param arr the array of integer values */ private def modeLanes (arr: Array [Int]): Int = val counts = scala.collection.mutable.Map [Int, Int] () cfor (0, arr.length) { i => val v = arr(i) counts(v) = counts.getOrElse (v, 0) + 1 } counts.maxBy (_._2)._1 end modeLanes
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: // Pre-built corridor layouts (lazy — loaded on first access) //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** I-210 Westbound — Eaton fire evacuation direction (27 ML, 22 OR, 18 FR). */ lazy val I210_WB: CorridorLayout = buildCorridorLayout (210, "W", "I-210-W", dims = (3000.0, 3000.0))
/** I-210 Eastbound — contraflow direction (future). */ lazy val I210_EB: CorridorLayout = buildCorridorLayout (210, "E", "I-210-E", dims = (3000.0, 3000.0))
/** SR-134 Westbound — alternate evacuation route (13 ML). */ lazy val SR134_WB: CorridorLayout = buildCorridorLayout (134, "W", "SR-134-W", dims = (3000.0, 3000.0))
end EatonCorridorConfig
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Plot station GPS positions as a spatial scatter (longitude vs latitude). * Produces a bird's-eye view comparable to Google Maps. * @param stations the stations to plot * @param title the plot window title */ private def plotGPSMap (stations: Array [StationWithCoords], title: String): Unit = val n = stations.length val lon = new VectorD (n) // x-axis: longitude (east-west) val lat = new VectorD (n) // y-axis: latitude (north-south) cfor (0, n) { i => lon(i) = stations(i).record.longitude lat(i) = stations(i).record.latitude } new Plot (lon, lat, null, title, lines = false) end plotGPSMap
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Print stations grouped by lane type for a given corridor. * @param corridor the filtered corridor stations with screen coordinates * @param laneTypes the lane types to report */ private def printStationsByType (corridor: Array [StationWithCoords], laneTypes: Array [String]): Unit = cfor (0, laneTypes.length) { t => val typed = EatonCorridorConfig.filterByLaneType (corridor, laneTypes(t)) if typed.nonEmpty then println (s"\n ${laneTypes(t)} — ${typed.length} stations:") cfor (0, typed.length) { i => val r = typed(i).record val (sx, sy) = typed(i).screenXY // animation pixel position println (f" ${r.stationId}%6d ${r.location}%-25s PM=${r.absPM}%7.3f " + f"GPS(${r.latitude}%.6f, ${r.longitude}%.6f) → " + f"Screen($sx%7.1f, $sy%7.1f) [${r.lanes} lanes]") } end if } end printStationsByType
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Test the Eaton corridor GPS → animation coordinate pipeline. * Loads station_map.csv, computes screen coordinates for all stations in one * shared frame, and prints the GPS → Screen mapping by corridor and lane type. * * > runMain scalation.simulation.process.config.testEatonCorridorCoords */ @main def testEatonCorridorCoords (): Unit =
import EatonCorridorConfig.*
banner ("Eaton Corridor: Station Map → Animation Coordinates")
// 1. Load all 194 stations from master station_map.csv val stations = loadStationMap () println (s"Total stations loaded: ${stations.length}")
// 2. Compute aniCoords — ALL stations in one Coordinates call // so I-210 W, I-210 E, and SR-134 W share one animation frame val all = computeAllCoordinates (stations) println (s"Coordinates computed: ${all.length} stations")
// 3. Report: for each corridor (I-210 WB, I-210 EB, SR-134 WB), // print stations grouped by lane type (ML, HV, OR, FR, FF) val corridors = Array ((210, "W"), (134, "W")) // WB only — evacuation direction val laneTypes = Array ("ML", "HV", "OR", "FR", "FF") // ML=mainline, HV=HOV, OR=on-ramp, FR=off-ramp, FF=freeway-freeway
cfor (0, corridors.length) { c => val (fwy, dir) = corridors(c) val label = if fwy == 134 then s"SR-$fwy" else s"I-$fwy" banner (s"$label ${dir}B") val corridor = filterByFreewayDir (all, fwy, dir) // filter to this corridor, sorted by PM println (s"Total stations in corridor: ${corridor.length}") printStationsByType (corridor, laneTypes) // print each lane type group }
// 4. Single combined GPS spatial map — WB corridors only (evacuation direction) val wbOnly = filterByFreewayDir (all, 210, "W") ++ filterByFreewayDir (all, 134, "W") plotGPSMap (wbOnly, "Eaton Corridor — I-210 WB + SR-134 WB")
end testEatonCorridorCoords
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Test the CSV-to-Model corridor layout builder. * Builds a `CorridorLayout` for I-210 Westbound and prints the full summary * including junction positions, ramp→segment mappings, and segment lengths. * * > runMain scalation.simulation.process.config.testBuildCorridorLayout */ @main def testBuildCorridorLayout (): Unit =
banner ("CorridorLayout Builder: I-210 Westbound")
// Build the layout — this runs the full CSV-to-Model pipeline val layout = EatonCorridorConfig.I210_WB layout.summary ()
// Verify segment lengths banner ("Segment Lengths") cfor (0, layout.segmentLengths.dim) { i => val name0 = layout.junctionNames(i) val name1 = layout.junctionNames(i + 1) println (f" seg $i%3d: $name0%-28s → $name1%-28s ${layout.segmentLengths(i)}%8.1f m (${layout.segmentLengths(i) / 1609.34}%.3f mi)") }
// Verify VSource center and offsets banner ("VSource Positions") val (center, offsets) = layout.getVSourceCenterAndOffsets println (s" Center: $center") cfor (0, offsets.length) { i => val label = if i == 0 then "mainline" else s"onRamp$i" println (f" $label%-12s offset = ${offsets(i)}") }
// Verify NetworkConfig compatibility banner ("NetworkConfig") val nc = layout.config println (s" mainline.id = ${nc.mainline.id}") println (s" mainline.segments = ${nc.mainline.segments}") println (s" mainline.lanes = ${nc.mainline.lanesPerSegment}") println (s" ramps (total) = ${nc.ramps.length}") println (s" ramps (On) = ${nc.ramps.count (_.mode == RampMode.On)}") println (s" ramps (Off) = ${nc.ramps.count (_.mode == RampMode.Off)}") println (s" sensors = ${nc.sensors.length}") println (s" numJunctions = ${nc.numJunctions}") println (s" pemsSensorIndices = ${nc.pemsSensorIndices.mkString (", ")}")
banner ("SR-134 Westbound (quick check)") val sr134 = EatonCorridorConfig.SR134_WB sr134.summary ()
end testBuildCorridorLayout

//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** @author  Bishi
 *  @version 2.0
 *  @date    Sat Mar 22 2026
 *  @see     LICENSE (MIT style license file).
 *
 *  @note    EatonFireModel: I-210 WB + SR-134 WB Dual-Corridor Traffic Model
 *
 *  Uses CorridorBuilder to construct topology from MultiCorridorConfig.
 *  Both corridors share one coordinate frame so they appear in correct
 *  spatial relationship in the animation.
 *
 *  @see config-layer-standard.md Section 4c, 7
 */

package scalation
package simulation
package process
package model

import scalation.mathstat.{MatrixD, VectorD}
import scalation.random.{Exponential, Uniform}
import scalation.simulation.process.{IntegratorType, IDMDynamics}
import scalation.simulation.process.config.{AggregatedDemand, CorridorLayout, MultiCorridorConfig}
import scalation.simulation.process.builder.{CorridorBuilder, BuiltNetwork}
import scalation.simulation.process.arrival.{ArrivalSource, AggregatedArrivalSource}

//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** Run the EatonFireModel simulation.
 *  > runMain scalation.simulation.process.model.runEatonFireModel
 */
@main def runEatonFireModel (): Unit = new EatonFireModel ()


//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** The `EatonFireModel` class is a dual-corridor traffic simulation model
 *  for I-210 Westbound + SR-134 Westbound (Eaton fire evacuation).
 *
 *  Both corridors share one animation coordinate frame.
 *  When synthetic=true, uses fixed vehicle counts (100 mainline, 50 ramps).
 *  When synthetic=false, loads from AggregatedDemand (PeMS data).
 *
 *  Subtype encoding:
 *    0 .. numLanes210-1                           = I-210 mainline lanes
 *    numLanes210 .. numLanes210+nOnRamps210-1     = I-210 on-ramps
 *    SR134_BASE+numLanes134 .. ...                = SR-134 on-ramps
 *  Note: SR-134 has NO mainline VSources.  All SR-134 mainline traffic
 *        enters via the FF connector from I-210 at the Pasadena interchange.
 *
 *  @param synthetic  if true, use fixed counts (100/50); if false, load PeMS data
 */
class EatonFireModel (name: String = "EatonFireModel", reps: Int = 1,
                      animating: Boolean = true, aniRatio: Double = 500.0,
                      synthetic: Boolean = false)
      extends Model (name, reps, animating, aniRatio)
         with RowTimeLoader:

    private val debug = debugf ("EatonFireModel", true)

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Constants
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    private val SR134_BASE = 100                               // subtype offset for SR-134
    private val nt         = 72                                // 72 × 5-min = 6 hours (5 PM–11 PM)

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Step 1: Dynamics (must be configured BEFORE builder call)
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    private val motion = IDMDynamics
    IDMDynamics.integratorType = IntegratorType.Ballistic
    private val iArrivalRV = Exponential (MINUTE / 10.0)  // no need : We use getDistribution from ArrivalSource for synthetic vs. aggregated demand
    private val rand       = Uniform (0.0, 1.0)            // for FF split ratio decisions
    setTime (nt * rowTime)

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Step 2: Build topology from config using CorridorBuilder
    //         Replaces manual junction/route/sink/FF creation (old Steps 3-9a)
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    private val multiConfig = MultiCorridorConfig.EatonFire_WB ()
    private val net         = CorridorBuilder.buildMulti (multiConfig, motion, nt)
    private val b210        = net.corridors ("I-210-W")
    private val b134        = net.corridors ("SR-134-W")

    // Corridor summaries
    CorridorBuilder.summary ("I-210-W", b210)
    CorridorBuilder.summary ("SR-134-W", b134)

    // Convenience aliases for Car.act()
    private val numLanes210    = b210.numLanes
    private val numSegments210 = b210.numSegments
    private val numLanes134    = b134.numLanes
    private val route210       = b210.route
    private val route134       = b134.route
    private val junc210        = b210.junctions
    private val junc134        = b134.junctions
    private val sinks210       = b210.sinks
    private val sinks134       = b134.sinks
    private val hwLen210       = b210.hwLen
    private val hwLen134       = b134.hwLen
    private val rampJoinSeg210 = b210.rampJoinSegs
    private val rampJoinSeg134 = b134.rampJoinSegs
    private val nOnRamps210    = b210.rampSensors.length
    private val nOnRamps134    = b134.rampSensors.length

    // FF connector (built by CorridorBuilder from FFConnectorSpec)
    // May have multiple lanes (parallel connectors)
    private val ffConnectors210to134: List[FFConnector] = net.ffConnectors
    private val ff210to134: FFConnector =
        if ffConnectors210to134.nonEmpty then ffConnectors210to134.head else null

    // FF diverge/merge segment indices (for Car.act() routing)
    private val ffDivJuncIdx210 = junc210.indexWhere (_.name.contains ("WINONA"))
    private val ffMrgJuncIdx134 = junc134.indexWhere (_.name.contains ("ORANGE"))
    private val ffDivSeg210 = if ffDivJuncIdx210 > 0 then ffDivJuncIdx210 - 1 else -1
    private val ffMrgSeg134 = ffMrgJuncIdx134

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Time-varying FF split ratios from PeMS data
    // splitRatio(i) = flow_717603 / flow_717634 for each 5-min interval
    // Reuses existing AggregatedDemand CSV loading — no new file I/O in model
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    private val splitIntervalSec = 5.0 * MINUTE                // 300 s per PeMS interval
    private val splitRatios: Array[Double] =
        AggregatedArrivalSource.computeSplitRatios (
            AggregatedDemand.I210_WB_Baseline,  717634,        // upstream: LAKE 1 on I-210
            AggregatedDemand.SR134_WB_Baseline,  717603         // FF merge: ORANGE GROVE on SR-134
        )

    /** Look up the current split ratio from the time-varying array.
     *  Uses the simulation clock to index into the 5-min interval array.
     */
    private def currentSplitRatio: Double =
        val idx = (clock / splitIntervalSec).toInt
        if idx >= 0 && idx < splitRatios.length then splitRatios(idx)
        else if splitRatios.nonEmpty then splitRatios.last      // clamp to last interval
        else 0.30                                                // ultimate fallback

    debug ("init", s"I-210: lanes=$numLanes210, segs=$numSegments210, " +
                   s"onRamps=$nOnRamps210, hwLen=$hwLen210")
    debug ("init", s"SR-134: lanes=$numLanes134, " +
                   s"onRamps=$nOnRamps134, hwLen=$hwLen134")
    debug ("init", s"FF: divSeg=$ffDivSeg210, mrgSeg=$ffMrgSeg134, " +
                   f"splitRatios=${splitRatios.length} intervals, avg=${splitRatios.sum / splitRatios.length.max(1)}%.3f")

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Step 3: Arrival Sources (same pattern as TrafficModelBuilder)
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    // I-210 arrival sources
    private val (mlSources210, rampSrcArr210) =
        if synthetic then ArrivalSource.syntheticSources (100, 50, numLanes210, nOnRamps210, iArrivalRV)
        else ArrivalSource.fromAggregated (AggregatedDemand.I210_WB_Baseline, numLanes210, nOnRamps210)

    // SR-134 arrival sources (ramps only — no mainline sources)
    private val (_, rampSrcArr134) =
        if synthetic then ArrivalSource.syntheticSources (100, 50, numLanes134, nOnRamps134, iArrivalRV)
        else ArrivalSource.fromAggregated (AggregatedDemand.SR134_WB_Baseline, numLanes134, nOnRamps134)

    debug ("init", s"synthetic=$synthetic, mlSources210=${mlSources210.length}, rampSrcArr210=${rampSrcArr210.length}")

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Step 4: Sources (model owns demand — uses ArrivalSource.getTotalVehicles)
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    // Layouts for source positioning (screen coordinates)
    private val layout210 = multiConfig.corridor ("I-210-W").layout
    private val layout134 = multiConfig.corridor ("SR-134-W").layout
    private val (center210, offsets210) = layout210.getVSourceCenterAndOffsets (200.0, -100.0)
    private val (center134, offsets134) = layout134.getVSourceCenterAndOffsets (150.0, -80.0)  // smaller offset for SR-134 ramps

    // I-210 mainline sources at EASTERN end (high postmile = entry for WB)
    // Spaced perpendicular to road direction — matches Route lane GAP (50 px)
    private val mainlineSources210 = {
        import scala.collection.mutable.ListBuffer
        val buf = ListBuffer [VSource] ()
        val dx  = junc210(1).at(0) - junc210(0).at(0)
        val dy  = junc210(1).at(1) - junc210(0).at(1)
        val hyp = math.hypot (dx, dy).max (1e-9)
        val perpX =  dy / hyp                              // perpendicular unit vector (same as Route.calcShift2)
        val perpY = -dx / hyp
        val upX   = -dx / hyp                              // upstream unit vector (away from junc(1))
        val upY   = -dy / hyp
        val LANE_GAP  = 50.0                               // matches Route.GAP
        val UPSTREAM  = 80.0                                // distance upstream of junc(0)
        cfor (0, numLanes210) { l =>
            val physLane   = numLanes210 - 1 - l            // match Route's physical lane mapping
            val laneOffset = (physLane - (numLanes210 - 1) / 2.0) * LANE_GAP
            val loc = Array (junc210(0).at(0) + upX * UPSTREAM + perpX * laneOffset,
                             junc210(0).at(1) + upY * UPSTREAM + perpY * laneOffset,
                             20.0, 20.0)
            val nStop = mlSources210(l).getTotalVehicles (l)   // from ArrivalSource
            val iArrivalRV = mlSources210(l).getDistribution   // only use RV for synthetic demand
            buf += new VSource (s"I210_vsrcML_L$l", this, () => Car (), l, nStop, iArrivalRV, loc)
        }
        buf.toList
    }

    // I-210 ramp sources — subtypes numLanes210..numLanes210+nOnRamps210-1
    private val rampSources210 = {
        import scala.collection.mutable.ListBuffer
        val buf = ListBuffer [VSource] ()
        cfor (0, nOnRamps210) { r =>
            val offset = offsets210(r + 1)
            val loc = Array ((center210._1 + offset._1).toDouble,
                             (center210._2 + offset._2).toDouble, 20.0, 20.0)
            val nStop = rampSrcArr210(r).getTotalVehicles (0)   // from ArrivalSource
            val iArrivalRV = rampSrcArr210(r).getDistribution   // only use RV for synthetic demand
            buf += new VSource (s"I210_srcRamp${r + 1}", this, () => Car (), numLanes210 + r,
                                nStop, iArrivalRV, loc)
        }
        buf.toList
    }

    // SR-134 has NO mainline VSource — all mainline traffic enters via FF from I-210.
    // Only on-ramp VSources feed local traffic into SR-134 mid-corridor.

    // SR-134 ramp sources — subtypes SR134_BASE+numLanes134..
    private val rampSources134 = {
        import scala.collection.mutable.ListBuffer
        val buf = ListBuffer [VSource] ()
        cfor (0, nOnRamps134) { r =>
            val offset = offsets134(r + 1)
            val loc = Array ((center134._1 + offset._1).toDouble,
                             (center134._2 + offset._2).toDouble, 20.0, 20.0)
            val nStop = rampSrcArr134(r).getTotalVehicles (0)   // from ArrivalSource
            val iArrivalRV = rampSrcArr134(r).getDistribution   // only use RV for synthetic demand
            buf += new VSource (s"SR134_srcRamp${r + 1}", this, () => Car (),
                                SR134_BASE + numLanes134 + r, nStop, iArrivalRV, loc)
        }
        buf.toList
    }

    private val sources: List [VSource] =
        mainlineSources210 ++ rampSources210 ++ rampSources134

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Step 4: Ramps (model owns — need VSource as `from` component)
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    private val ramps210 = new Array [Ramp] (nOnRamps210)
    cfor (0, nOnRamps210) { r =>
        ramps210(r) = new Ramp (s"I210_onRamp${r + 1}", rampSources210(r), b210.rampSensors(r),
                                motion, scalation.simulation.process.RampMode.On, false, 0.1, 0.0)
    }

    private val ramps134 = new Array [Ramp] (nOnRamps134)
    cfor (0, nOnRamps134) { r =>
        ramps134(r) = new Ramp (s"SR134_onRamp${r + 1}", rampSources134(r), b134.rampSensors(r),
                                motion, scalation.simulation.process.RampMode.On, false, 0.1, 0.0)
    }

    // Off-ramps: from = mainline junction at diverge, to = off-ramp sink
    // Same pattern as CalRoute101: Ramp(name, junc, sink, motion, RampMode.Off)
    private val nOffRamps210   = b210.offRampJoinSegs.length
    private val offRamps210    = new Array [Ramp] (nOffRamps210)
    cfor (0, nOffRamps210) { r =>
        offRamps210(r) = new Ramp (s"I210_offRamp${r + 1}",
            junc210(b210.offRampJoinSegs(r)),          // from: mainline junction at diverge
            b210.offRampSinks(r),                       // to: off-ramp sink
            motion, scalation.simulation.process.RampMode.Off, false, -0.1, 0.0)
    }

    private val nOffRamps134   = b134.offRampJoinSegs.length
    private val offRamps134    = new Array [Ramp] (nOffRamps134)
    cfor (0, nOffRamps134) { r =>
        offRamps134(r) = new Ramp (s"SR134_offRamp${r + 1}",
            junc134(b134.offRampJoinSegs(r)),          // from: mainline junction at diverge
            b134.offRampSinks(r),                       // to: off-ramp sink
            motion, scalation.simulation.process.RampMode.Off, false, -0.1, 0.0)
    }

    debug ("init", s"Off-ramps: I-210=$nOffRamps210, SR-134=$nOffRamps134")

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Step 5: Register ALL components
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    private val allJunctions = junc210.toList ++ b210.rampSensors.toList ++
                               junc134.toList ++ b134.rampSensors.toList
    private val allSinks     = sinks210 ++ sinks134 ++
                               b210.offRampSinks.toList ++ b134.offRampSinks.toList
    private val allRamps     = ramps210.toList ++ ramps134.toList ++
                               offRamps210.toList ++ offRamps134.toList

    addComponents (sources, allJunctions, allSinks, allRamps)
    ffConnectors210to134.foreach (addComponent (_))              // register all FF lanes
    route210.pathway.foreach (addComponent (_))
    route134.pathway.foreach (addComponent (_))
    debug ("init", s"All components registered (I-210 + SR-134 + ${ffConnectors210to134.length} FF lanes)")

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Car entity — parameterized to drive either corridor
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    case class Car () extends Vehicle ("c", this):

        override def act (): Unit =
            if subtype < SR134_BASE then actOnCorridor (
                subtype, numLanes210, route210, junc210, sinks210, ramps210, rampJoinSeg210, hwLen210
            )
            else actOnCorridor (
                subtype - SR134_BASE, numLanes134, route134, junc134, sinks134, ramps134, rampJoinSeg134, hwLen134
            )
        end act

        /** Drive a car on any corridor — mainline or ramp entry. */
        private def actOnCorridor (localSub: Int, nLanes: Int,
                                   route: Route, junc: Array [Junction],
                                   sinks: List [Sink], ramps: Array [Ramp],
                                   joinSegs: Array [Int], hwLen: Int): Unit =
            if localSub < nLanes then
                // Mainline entry
                laneID = localSub
                val carAhead = route.pathway(laneID).getLast
                route.pathway(laneID).addToAlist (this, carAhead)
                junc(0).jump ()
                driveHighway (route, junc, sinks, hwLen, 0)
            else
                // Ramp entry
                laneID = nLanes - 1
                val rampIdx = localSub - nLanes
                val r = ramps(rampIdx)
                driveRamp (r)
                val joinSeg = joinSegs(rampIdx)
                val carAhead = route.pathway(laneID).seg(joinSeg).getLast
                route.pathway(laneID).addToAlist (this, carAhead)
                junc(joinSeg).jump ()
                driveHighway (route, junc, sinks, hwLen, joinSeg)
        end actOnCorridor

        /** Drive segment by segment from startSeg to the corridor sink.
         *  At the FF interchange segment, I-210 cars may divert to SR-134.
         */
        private def driveHighway (route: Route, junc: Array [Junction],
                                  sinks: List [Sink], hwLen: Int, startSeg: Int): Unit =
            var seg      = startSeg
            var diverted = false

            while seg < hwLen && !diverted do
                route.pathway(laneID).seg(seg).move ()
                junc(seg + 1).jump ()

                // ── FF diversion: I-210 WB → SR-134 WB at interchange ──────
                // Time-varying split ratio from PeMS (flow_717603 / flow_717634)
                if !diverted && ffConnectors210to134.nonEmpty
                   && subtype < SR134_BASE                    // car is on I-210
                   && seg == ffDivSeg210                      // at interchange segment
                   && ffMrgSeg134 >= 0                        // merge point valid
                   && rand.gen < currentSplitRatio then       // time-varying probabilistic split
                    diverted = true
                    // 1. Exit I-210 pathway
                    route.pathway(laneID).removeFromAlist (this)
                    // 2. Randomly select one of the FF connector lanes
                    val ffLaneIdx = (rand.gen * ffConnectors210to134.length).toInt.min(ffConnectors210to134.length - 1)
                    val ffLane = ffConnectors210to134(ffLaneIdx)
                    // 3. Drive the selected FF connector lane
                    val ahead = ffLane.getLast
                    ffLane.addToAlist (this, ahead)
                    ffLane.lane.move ()
                    ffLane.removeFromAlist (this)
                    // 4. Enter SR-134 at merge junction — spread across all lanes
                    laneID = (rand.gen * numLanes134).toInt.min (numLanes134 - 1)
                    val carAhead = route134.pathway(laneID).seg(ffMrgSeg134).getLast
                    route134.pathway(laneID).addToAlist (this, carAhead)
                    junc134(ffMrgSeg134).jump ()
                    // 5. Continue driving on SR-134 to its sink
                    driveHighway (route134, junc134, sinks134, hwLen134, ffMrgSeg134)
                end if

                if !diverted then seg += 1
            end while

            if !diverted then
                route.pathway(laneID).removeFromAlist (this)
                sinks.head.leave ()
        end driveHighway

        /** Traverse an on-ramp single segment. */
        private def driveRamp (r: Ramp): Unit =
            val carAhead = r.getLast
            r.addToAlist (this, carAhead)
            if r.mode == scalation.simulation.process.RampMode.On then
                r.lane.move ()
                r.to.asInstanceOf [Junction].jump ()
            end if
            r.removeFromAlist (this)
        end driveRamp

    end Car

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // RowTimeLoader (placeholder — no PeMS data yet)
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    def getDataDimension: Int = nt

    def getMuForSource (sourceIdx: Int): VectorD =
        VectorD.fill (nt)(MINUTE / 10.0)

    def getSpeedMatrix (): MatrixD =
        MatrixD.fill (nt, math.max (numLanes210, numLanes134), 30.0)

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Public accessors
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    def getJunctions210: Array [Junction] = junc210
    def getJunctions134: Array [Junction] = junc134
    def getLayout210: CorridorLayout = layout210
    def getLayout134: CorridorLayout = layout134
    def getBuiltNetwork: BuiltNetwork = net

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Finish
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    override def fini (rep: Int): Unit =
        println ("\n" + "=" * 70)
        println ("EatonFireModel SIMULATION COMPLETE (I-210 + SR-134)")
        println ("=" * 70)
        super.fini (rep)
    end fini

    simulate ()
    waitFinished ()
    Model.shutdown ()

end EatonFireModel

//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** @author  Bishi
 *  @version 2.0
 *  @date    Sat Mar 22 2026
 *  @see     LICENSE (MIT style license file).
 *
 *  @note    EatonFireModel: I-210 WB + SR-134 WB Dual-Corridor Traffic Model
 *
 *  Uses CorridorBuilder to construct topology from MultiCorridorConfig.
 *  Both corridors share one coordinate frame so they appear in correct
 *  spatial relationship in the animation.
 *
 *  @see config-layer-standard.md Section 4c, 7
 */

package scalation
package simulation
package process
package model

import scalation.mathstat.{MatrixD, VectorD}
import scalation.random.{Exponential, Uniform}
import scalation.simulation.process.{IntegratorType, IDMDynamics}
import scalation.simulation.process.config.{AggregatedDemand, CorridorLayout, MultiCorridorConfig}
import scalation.simulation.process.builder.{CorridorBuilder, BuiltNetwork}
import scalation.simulation.process.arrival.{ArrivalSource, AggregatedArrivalSource}

//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** Run the EatonFireModel simulation.
 *  > runMain scalation.simulation.process.model.runEatonFireModel
 */
@main def runEatonFireModel (): Unit = new EatonFireModel ()


//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** The `EatonFireModel` class is a dual-corridor traffic simulation model
 *  for I-210 Westbound + SR-134 Westbound (Eaton fire evacuation).
 *
 *  Both corridors share one animation coordinate frame.
 *  When synthetic=true, uses fixed vehicle counts (100 mainline, 50 ramps).
 *  When synthetic=false, loads from AggregatedDemand (PeMS data).
 *
 *  Subtype encoding:
 *    0 .. numLanes210-1                           = I-210 mainline lanes
 *    numLanes210 .. numLanes210+nOnRamps210-1     = I-210 on-ramps
 *    SR134_BASE+numLanes134 .. ...                = SR-134 on-ramps
 *  Note: SR-134 has NO mainline VSources.  All SR-134 mainline traffic
 *        enters via the FF connector from I-210 at the Pasadena interchange.
 *
 *  @param synthetic  if true, use fixed counts (100/50); if false, load PeMS data
 */
class EatonFireModel (name: String = "EatonFireModel", reps: Int = 1,
                      animating: Boolean = true, aniRatio: Double = 500.0,
                      synthetic: Boolean = false)
      extends Model (name, reps, animating, aniRatio)
         with RowTimeLoader:

    private val debug = debugf ("EatonFireModel", true)

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Constants
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    private val SR134_BASE = 100                               // subtype offset for SR-134
    private val nt         = 72                                // 72 × 5-min = 6 hours (5 PM–11 PM)

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Step 1: Dynamics (must be configured BEFORE builder call)
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    private val motion = IDMDynamics
    IDMDynamics.integratorType = IntegratorType.Ballistic
    private val iArrivalRV = Exponential (MINUTE / 10.0)  // no need : We use getDistribution from ArrivalSource for synthetic vs. aggregated demand
    private val rand       = Uniform (0.0, 1.0)            // for FF split ratio decisions
    setTime (nt * rowTime)

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Step 2: Build topology from config using CorridorBuilder
    //         Replaces manual junction/route/sink/FF creation (old Steps 3-9a)
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    private val multiConfig = MultiCorridorConfig.EatonFire_WB ()
    private val net         = CorridorBuilder.buildMulti (multiConfig, motion, nt)
    private val b210        = net.corridors ("I-210-W")
    private val b134        = net.corridors ("SR-134-W")

    // Corridor summaries
    CorridorBuilder.summary ("I-210-W", b210)
    CorridorBuilder.summary ("SR-134-W", b134)

    // Convenience aliases for Car.act()
    private val numLanes210    = b210.numLanes
    private val numSegments210 = b210.numSegments
    private val numLanes134    = b134.numLanes
    private val route210       = b210.route
    private val route134       = b134.route
    private val junc210        = b210.junctions
    private val junc134        = b134.junctions
    private val sinks210       = b210.sinks
    private val sinks134       = b134.sinks
    private val hwLen210       = b210.hwLen
    private val hwLen134       = b134.hwLen
    private val rampJoinSeg210 = b210.rampJoinSegs
    private val rampJoinSeg134 = b134.rampJoinSegs
    private val nOnRamps210    = b210.rampSensors.length
    private val nOnRamps134    = b134.rampSensors.length

    // FF connector (built by CorridorBuilder from FFConnectorSpec)
    // May have multiple lanes (parallel connectors)
    private val ffConnectors210to134: List[FFConnector] = net.ffConnectors
    private val ff210to134: FFConnector =
        if ffConnectors210to134.nonEmpty then ffConnectors210to134.head else null

    // FF diverge/merge segment indices (for Car.act() routing)
    private val ffDivJuncIdx210 = junc210.indexWhere (_.name.contains ("WINONA"))
    private val ffMrgJuncIdx134 = junc134.indexWhere (_.name.contains ("ORANGE"))
    private val ffDivSeg210 = if ffDivJuncIdx210 > 0 then ffDivJuncIdx210 - 1 else -1
    private val ffMrgSeg134 = ffMrgJuncIdx134

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Time-varying FF split ratios from PeMS data
    // splitRatio(i) = flow_717603 / flow_717634 for each 5-min interval
    // Reuses existing AggregatedDemand CSV loading — no new file I/O in model
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    private val splitIntervalSec = 5.0 * MINUTE                // 300 s per PeMS interval
    private val splitRatios: Array[Double] =
        AggregatedArrivalSource.computeSplitRatios (
            AggregatedDemand.I210_WB_Baseline,  717634,        // upstream: LAKE 1 on I-210
            AggregatedDemand.SR134_WB_Baseline,  717603         // FF merge: ORANGE GROVE on SR-134
        )

    /** Look up the current split ratio from the time-varying array.
     *  Uses the simulation clock to index into the 5-min interval array.
     */
    private def currentSplitRatio: Double =
        val idx = (clock / splitIntervalSec).toInt
        if idx >= 0 && idx < splitRatios.length then splitRatios(idx)
        else if splitRatios.nonEmpty then splitRatios.last      // clamp to last interval
        else 0.30                                                // ultimate fallback

    debug ("init", s"I-210: lanes=$numLanes210, segs=$numSegments210, " +
                   s"onRamps=$nOnRamps210, hwLen=$hwLen210")
    debug ("init", s"SR-134: lanes=$numLanes134, " +
                   s"onRamps=$nOnRamps134, hwLen=$hwLen134")
    debug ("init", s"FF: divSeg=$ffDivSeg210, mrgSeg=$ffMrgSeg134, " +
                   f"splitRatios=${splitRatios.length} intervals, avg=${splitRatios.sum / splitRatios.length.max(1)}%.3f")

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Step 3: Arrival Sources (same pattern as TrafficModelBuilder)
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    // I-210 arrival sources
    private val (mlSources210, rampSrcArr210) =
        if synthetic then ArrivalSource.syntheticSources (100, 50, numLanes210, nOnRamps210, iArrivalRV)
        else ArrivalSource.fromAggregated (AggregatedDemand.I210_WB_Baseline, numLanes210, nOnRamps210)

    // SR-134 arrival sources (ramps only — no mainline sources)
    private val (_, rampSrcArr134) =
        if synthetic then ArrivalSource.syntheticSources (100, 50, numLanes134, nOnRamps134, iArrivalRV)
        else ArrivalSource.fromAggregated (AggregatedDemand.SR134_WB_Baseline, numLanes134, nOnRamps134)

    debug ("init", s"synthetic=$synthetic, mlSources210=${mlSources210.length}, rampSrcArr210=${rampSrcArr210.length}")

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Step 4: Sources (model owns demand — uses ArrivalSource.getTotalVehicles)
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    // Layouts for source positioning (screen coordinates)
    private val layout210 = multiConfig.corridor ("I-210-W").layout
    private val layout134 = multiConfig.corridor ("SR-134-W").layout
    private val (center210, offsets210) = layout210.getVSourceCenterAndOffsets (200.0, -100.0)
    private val (center134, offsets134) = layout134.getVSourceCenterAndOffsets (150.0, -80.0)  // smaller offset for SR-134 ramps

    // I-210 mainline sources at EASTERN end (high postmile = entry for WB)
    // Spaced perpendicular to road direction — matches Route lane GAP (50 px)
    private val mainlineSources210 = {
        import scala.collection.mutable.ListBuffer
        val buf = ListBuffer [VSource] ()
        val dx  = junc210(1).at(0) - junc210(0).at(0)
        val dy  = junc210(1).at(1) - junc210(0).at(1)
        val hyp = math.hypot (dx, dy).max (1e-9)
        val perpX =  dy / hyp                              // perpendicular unit vector (same as Route.calcShift2)
        val perpY = -dx / hyp
        val upX   = -dx / hyp                              // upstream unit vector (away from junc(1))
        val upY   = -dy / hyp
        val LANE_GAP  = 50.0                               // matches Route.GAP
        val UPSTREAM  = 80.0                                // distance upstream of junc(0)
        cfor (0, numLanes210) { l =>
            val physLane   = numLanes210 - 1 - l            // match Route's physical lane mapping
            val laneOffset = (physLane - (numLanes210 - 1) / 2.0) * LANE_GAP
            val loc = Array (junc210(0).at(0) + upX * UPSTREAM + perpX * laneOffset,
                             junc210(0).at(1) + upY * UPSTREAM + perpY * laneOffset,
                             20.0, 20.0)
            val nStop = mlSources210(l).getTotalVehicles (l)   // from ArrivalSource
            val iArrivalRV = mlSources210(l).getDistribution   // only use RV for synthetic demand
            buf += new VSource (s"I210_vsrcML_L$l", this, () => Car (), l, nStop, iArrivalRV, loc)
        }
        buf.toList
    }

    // I-210 ramp sources — subtypes numLanes210..numLanes210+nOnRamps210-1
    private val rampSources210 = {
        import scala.collection.mutable.ListBuffer
        val buf = ListBuffer [VSource] ()
        cfor (0, nOnRamps210) { r =>
            val offset = offsets210(r + 1)
            val loc = Array ((center210._1 + offset._1).toDouble,
                             (center210._2 + offset._2).toDouble, 20.0, 20.0)
            val nStop = rampSrcArr210(r).getTotalVehicles (0)   // from ArrivalSource
            val iArrivalRV = rampSrcArr210(r).getDistribution   // only use RV for synthetic demand
            buf += new VSource (s"I210_srcRamp${r + 1}", this, () => Car (), numLanes210 + r,
                                nStop, iArrivalRV, loc)
        }
        buf.toList
    }

    // SR-134 has NO mainline VSource — all mainline traffic enters via FF from I-210.
    // Only on-ramp VSources feed local traffic into SR-134 mid-corridor.

    // SR-134 ramp sources — subtypes SR134_BASE+numLanes134..
    private val rampSources134 = {
        import scala.collection.mutable.ListBuffer
        val buf = ListBuffer [VSource] ()
        cfor (0, nOnRamps134) { r =>
            val offset = offsets134(r + 1)
            val loc = Array ((center134._1 + offset._1).toDouble,
                             (center134._2 + offset._2).toDouble, 20.0, 20.0)
            val nStop = rampSrcArr134(r).getTotalVehicles (0)   // from ArrivalSource
            val iArrivalRV = rampSrcArr134(r).getDistribution   // only use RV for synthetic demand
            buf += new VSource (s"SR134_srcRamp${r + 1}", this, () => Car (),
                                SR134_BASE + numLanes134 + r, nStop, iArrivalRV, loc)
        }
        buf.toList
    }

    private val sources: List [VSource] =
        mainlineSources210 ++ rampSources210 ++ rampSources134

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Step 4: Ramps (model owns — need VSource as `from` component)
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    private val ramps210 = new Array [Ramp] (nOnRamps210)
    cfor (0, nOnRamps210) { r =>
        ramps210(r) = new Ramp (s"I210_onRamp${r + 1}", rampSources210(r), b210.rampSensors(r),
                                motion, scalation.simulation.process.RampMode.On, false, 0.1, 0.0)
    }

    private val ramps134 = new Array [Ramp] (nOnRamps134)
    cfor (0, nOnRamps134) { r =>
        ramps134(r) = new Ramp (s"SR134_onRamp${r + 1}", rampSources134(r), b134.rampSensors(r),
                                motion, scalation.simulation.process.RampMode.On, false, 0.1, 0.0)
    }

    // Off-ramps: from = mainline junction at diverge, to = off-ramp sink
    // Same pattern as CalRoute101: Ramp(name, junc, sink, motion, RampMode.Off)
    private val nOffRamps210   = b210.offRampJoinSegs.length
    private val offRamps210    = new Array [Ramp] (nOffRamps210)
    cfor (0, nOffRamps210) { r =>
        offRamps210(r) = new Ramp (s"I210_offRamp${r + 1}",
            junc210(b210.offRampJoinSegs(r)),          // from: mainline junction at diverge
            b210.offRampSinks(r),                       // to: off-ramp sink
            motion, scalation.simulation.process.RampMode.Off, false, -0.1, 0.0)
    }

    private val nOffRamps134   = b134.offRampJoinSegs.length
    private val offRamps134    = new Array [Ramp] (nOffRamps134)
    cfor (0, nOffRamps134) { r =>
        offRamps134(r) = new Ramp (s"SR134_offRamp${r + 1}",
            junc134(b134.offRampJoinSegs(r)),          // from: mainline junction at diverge
            b134.offRampSinks(r),                       // to: off-ramp sink
            motion, scalation.simulation.process.RampMode.Off, false, -0.1, 0.0)
    }

    debug ("init", s"Off-ramps: I-210=$nOffRamps210, SR-134=$nOffRamps134")

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Step 5: Register ALL components
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    private val allJunctions = junc210.toList ++ b210.rampSensors.toList ++
                               junc134.toList ++ b134.rampSensors.toList
    private val allSinks     = sinks210 ++ sinks134 ++
                               b210.offRampSinks.toList ++ b134.offRampSinks.toList
    private val allRamps     = ramps210.toList ++ ramps134.toList ++
                               offRamps210.toList ++ offRamps134.toList

    addComponents (sources, allJunctions, allSinks, allRamps)
    ffConnectors210to134.foreach (addComponent (_))              // register all FF lanes
    route210.pathway.foreach (addComponent (_))
    route134.pathway.foreach (addComponent (_))
    debug ("init", s"All components registered (I-210 + SR-134 + ${ffConnectors210to134.length} FF lanes)")

    // ── Demand summary (PeMS vehicle counts) ────────────────────────────────
    println ("\n" + "=" * 70)
    println ("DEMAND SUMMARY (PeMS vehicle counts)")
    println ("=" * 70)
    println ("I-210 WB Mainline (entry station 717653 ROSEMEAD 1):")
    var totalML210 = 0
    cfor (0, mainlineSources210.length) { l =>
        val n = mlSources210(l).getTotalVehicles (l)
        totalML210 += n
        println (f"  Lane $l: $n%6d vehicles")
    }
    println (f"  TOTAL mainline:  $totalML210%6d vehicles")

    println ("I-210 WB On-Ramps:")
    var totalOR210 = 0
    cfor (0, rampSources210.length) { r =>
        val n = rampSrcArr210(r).getTotalVehicles (0)
        totalOR210 += n
        println (f"  Ramp ${r + 1}%2d: $n%6d vehicles")
    }
    println (f"  TOTAL on-ramps:  $totalOR210%6d vehicles")
    println (f"  I-210 GRAND TOTAL: ${totalML210 + totalOR210}%6d vehicles")

    println ("\nSR-134 WB On-Ramps (no mainline VSource — fed by FF):")
    var totalOR134 = 0
    cfor (0, rampSources134.length) { r =>
        val n = rampSrcArr134(r).getTotalVehicles (0)
        totalOR134 += n
        println (f"  Ramp ${r + 1}%2d: $n%6d vehicles")
    }
    println (f"  TOTAL on-ramps:  $totalOR134%6d vehicles")
    println (f"\nNETWORK TOTAL: ${totalML210 + totalOR210 + totalOR134}%6d vehicles (+ FF diversion from I-210)")
    println ("=" * 70)

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Car entity — parameterized to drive either corridor
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    case class Car () extends Vehicle ("c", this):

        override def act (): Unit =
            if subtype < SR134_BASE then actOnCorridor (
                subtype, numLanes210, route210, junc210, sinks210, ramps210, rampJoinSeg210, hwLen210
            )
            else actOnCorridor (
                subtype - SR134_BASE, numLanes134, route134, junc134, sinks134, ramps134, rampJoinSeg134, hwLen134
            )
        end act

        /** Drive a car on any corridor — mainline or ramp entry. */
        private def actOnCorridor (localSub: Int, nLanes: Int,
                                   route: Route, junc: Array [Junction],
                                   sinks: List [Sink], ramps: Array [Ramp],
                                   joinSegs: Array [Int], hwLen: Int): Unit =
            if localSub < nLanes then
                // Mainline entry
                laneID = localSub
                val carAhead = route.pathway(laneID).getLast
                route.pathway(laneID).addToAlist (this, carAhead)
                junc(0).jump ()
                driveHighway (route, junc, sinks, hwLen, 0)
            else
                // Ramp entry
                laneID = nLanes - 1
                val rampIdx = localSub - nLanes
                val r = ramps(rampIdx)
                driveRamp (r)
                val joinSeg = joinSegs(rampIdx)
                val carAhead = route.pathway(laneID).seg(joinSeg).getLast
                route.pathway(laneID).addToAlist (this, carAhead)
                junc(joinSeg).jump ()
                driveHighway (route, junc, sinks, hwLen, joinSeg)
        end actOnCorridor

        /** Drive segment by segment from startSeg to the corridor sink.
         *  At the FF interchange segment, I-210 cars may divert to SR-134.
         */
        private def driveHighway (route: Route, junc: Array [Junction],
                                  sinks: List [Sink], hwLen: Int, startSeg: Int): Unit =
            var seg      = startSeg
            var diverted = false

            while seg < hwLen && !diverted do
                route.pathway(laneID).seg(seg).move ()
                junc(seg + 1).jump ()

                // ── FF diversion: I-210 WB → SR-134 WB at interchange ──────
                // Time-varying split ratio from PeMS (flow_717603 / flow_717634)
                if !diverted && ffConnectors210to134.nonEmpty
                   && subtype < SR134_BASE                    // car is on I-210
                   && seg == ffDivSeg210                      // at interchange segment
                   && ffMrgSeg134 >= 0                        // merge point valid
                   && rand.gen < currentSplitRatio then       // time-varying probabilistic split
                    diverted = true
                    // 1. Exit I-210 pathway
                    route.pathway(laneID).removeFromAlist (this)
                    // 2. Randomly select one of the FF connector lanes
                    val ffLaneIdx = (rand.gen * ffConnectors210to134.length).toInt.min(ffConnectors210to134.length - 1)
                    val ffLane = ffConnectors210to134(ffLaneIdx)
                    // 3. Drive the selected FF connector lane
                    val ahead = ffLane.getLast
                    ffLane.addToAlist (this, ahead)
                    ffLane.lane.move ()
                    ffLane.removeFromAlist (this)
                    // 4. Enter SR-134 at merge junction — spread across all lanes
                    laneID = (rand.gen * numLanes134).toInt.min (numLanes134 - 1)
                    val carAhead = route134.pathway(laneID).seg(ffMrgSeg134).getLast
                    route134.pathway(laneID).addToAlist (this, carAhead)
                    junc134(ffMrgSeg134).jump ()
                    // 5. Continue driving on SR-134 to its sink
                    driveHighway (route134, junc134, sinks134, hwLen134, ffMrgSeg134)
                end if

                if !diverted then seg += 1
            end while

            if !diverted then
                route.pathway(laneID).removeFromAlist (this)
                sinks.head.leave ()
        end driveHighway

        /** Traverse an on-ramp single segment. */
        private def driveRamp (r: Ramp): Unit =
            val carAhead = r.getLast
            r.addToAlist (this, carAhead)
            if r.mode == scalation.simulation.process.RampMode.On then
                r.lane.move ()
                r.to.asInstanceOf [Junction].jump ()
            end if
            r.removeFromAlist (this)
        end driveRamp

    end Car

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // RowTimeLoader (placeholder — no PeMS data yet)
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    def getDataDimension: Int = nt

    def getMuForSource (sourceIdx: Int): VectorD =
        VectorD.fill (nt)(MINUTE / 10.0)

    def getSpeedMatrix (): MatrixD =
        MatrixD.fill (nt, math.max (numLanes210, numLanes134), 30.0)

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Public accessors
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    def getJunctions210: Array [Junction] = junc210
    def getJunctions134: Array [Junction] = junc134
    def getLayout210: CorridorLayout = layout210
    def getLayout134: CorridorLayout = layout134
    def getBuiltNetwork: BuiltNetwork = net

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    // Finish
    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    override def fini (rep: Int): Unit =
        println ("\n" + "=" * 70)
        println ("EatonFireModel SIMULATION COMPLETE (I-210 + SR-134)")
        println ("=" * 70)
        super.fini (rep)
    end fini

    simulate ()
    waitFinished ()
    Model.shutdown ()

end EatonFireModel

//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** @author  John Miller
 *  @version 2.0
 *  @date    Sat Jan 25 19:44:16 EST 2014
 *  @see     LICENSE (MIT style license file).
 *
 *  @note    Route for Modeling Multi-Stage, Multi-Lane Pathway
 */

package scalation
package simulation
package process


import scalation.mathstat.VectorD
import scala.math.{min,abs}
//import scalation.random.Variate

//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** The `Route` class defines a multi-lane route composed of multiple `Pathway`s
 *  running in parallel. Each `Pathway` is a single-lane road that shares the same
 *  `from` (entry), `to` (exit), and intermediate `junc` (junction) components.
 *
 *  @param name     the name of the route
 *  @param numLanes the number of parallel lanes (Pathways)
 *  @param junc     the shared junction components between segments
 *  @param from     the shared starting component (e.g., VSource)
 *  @param to       the shared ending component (e.g., Sink)
 *  @param motion   the dynamics model used for movement
 *  @param isSpeed  whether speed or trip-time is used
 *  @param bend     curvature of the lanes
 */
class Route (name: String, numLanes: Int, junc: Array[Junction], from: Component, to: Component,
             motion: Dynamics, isSpeed: Boolean = false, bend: Double = 0.0,
             val lanesPerSeg: Array[Int] = null)
    extends Component ():


    private val debug = debugf("Route", true)     // debug function

    /** Number of segments in this route. */
    private val nSegments: Int = junc.length + 1   // from + junc.length intermediates + to = junc.length+1 points → junc.length+1-1 segs ... actually segments = intermediateJunc.length + 1

    /** Per-segment lane counts. If lanesPerSeg is null (uniform), fill with numLanes. */
    private val _lanesPerSeg: Array[Int] =
        if lanesPerSeg != null then lanesPerSeg
        else Array.fill(junc.length + 1)(numLanes)   // junc = intermediate junctions → nSegments = junc.length + 1

    /** Maximum lane count across all segments. */
    val maxLanes: Int = if _lanesPerSeg.nonEmpty then _lanesPerSeg.max else numLanes

    /** Query: how many lanes exist at segment `seg`. */
    def lanesAt (seg: Int): Int = _lanesPerSeg(seg)

    /** Query: does lane `lane` exist at segment `seg`? */
    def laneExistsAt (lane: Int, seg: Int): Boolean = lane < _lanesPerSeg(seg)

    val pathway: Array[Pathway] = Array.ofDim[Pathway](numLanes)      // create array of parallel Pathways
    private val GAP = 50.0     // pixel between lanes

    for i <- pathway.indices do
        val physicalLane = numLanes - 1 - i  // Reverse: i=0 → lane 4 (rightmost), i=4 → lane 0 (leftmost)
        val shift = calcShift2 * ((physicalLane - (numLanes - 1) / 2.0) * GAP)
        pathway(i) = new Pathway(s"${name}L$i", junc, from, to, motion, isSpeed, bend,
                                 laneShift = shift, laneIndex = i, lanesPerSeg = _lanesPerSeg)
        subpart += pathway(i)
    end for


    initComponent(name, from.at)   // using from.at for the initComponent


    // Cumulative length up to (but not including) each segment
    // segmentOffsets(0) = 0
    // segmentOffsets(1) = seg(0).length
    // segmentOffsets(2) = seg(0).length + seg(1).length
    // etc.
    val segmentOffsets: Array[Double] =
        val n = pathway(0).seg.length  // number of segments (same for all Pathways)
        val offsets = new Array[Double](n + 1)  // array to hold offsets
        offsets(0) = 0.0  // starting offset is 0.0
        for i <- 0 until n do
            // Find a non-null VTransport at this segment index (any lane will do — same geometry)
            val vt = pathway.map(_.seg(i)).find(_ != null).orNull
            offsets(i + 1) = offsets(i) + (if vt != null then vt.length else 0.0)
        end for
        offsets
    end segmentOffsets

    // O(1) helper: convert (segId, disp) → cumulative position
    @inline def toCumulative(segId: Int, disp: Double): Double =
        segmentOffsets(segId) + disp
    end toCumulative

    // ----------------------------------------------------------------------------

    /** Attempt to change lanes for a vehicle that is on segment `seg` of lane `l1`
     * and wants to move to adjacent lane `l2`.
     *
     * @return true if the lane-change succeeds; false otherwise
     */
    def changeLane(l1: Int, l2: Int, actor: Vehicle, seg: Int): Boolean =

        var success = abs(l1 - l2) == 1
        if !success then return success

        // Check if target lane exists at this segment (variable lane support)
        if !laneExistsAt(l2, seg) then return false
        // Check if source lane exists at this segment (car can't be here if lane is null)
        if !laneExistsAt(l1, seg) then return false

        val fromPath = pathway(l1) // current Pathway  (lane l1)
        val toPath = pathway(l2) // target Pathway   (lane l2)

        // Check if either lane doesn't exist
        if fromPath == null || toPath == null then return false

        val safeDisp = fromPath.seg(seg).safetydist

        //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
        // vehicles to check in target lane
        val vBehind = toPath.seg(seg).getFirst // car behind in same seg
        val vAhead = if seg + 1 < toPath.seg.length && toPath.seg(seg + 1) != null
            then toPath.seg(seg + 1).getLast else null

        //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
        // compute bumper-to-bumper gaps
        val gapBehind = if vBehind != null then actor.disp - vBehind.disp else safeDisp

        val nextSeg = min(seg + 1, toPath.seg.length - 1)

        val gapAhead =
            if vAhead != null then toPath.seg(nextSeg).length - vAhead.disp - Vehicle.len
            else safeDisp

        val gap = min(gapBehind, gapAhead)
        //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
        // feasibility check
        success &&= gapBehind >= safeDisp && gapAhead >= safeDisp

        //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
        // --- perform the lane change --------------------------------------------
        if success then
            fromPath.removeFromAlist(actor, seg) // detach from old lane at this segment
            assert(actor.myPathNode == null, s"Vehicle $this not cleared before lane-change insertion!")

            actor.laneID = l2 // update laneID
            actor.pathInfo = toPath.seg(seg).name // update pathInfo
            toPath.addToAlist(actor, vAhead, seg) // insert before vAhead in target lane at this segment
        end if

        success
    end changeLane

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    /** Merge a ramp vehicle into the mainline at the given lane and segment.
     *  Checks lead and lag gaps before inserting.  If the gap is insufficient,
     *  the vehicle yields (waits one timestep) and re-checks — up to `maxWait`
     *  attempts.  After the timeout, force-merges.
     *
     *  This replaces the raw `getLast + addToAlist` pattern in model files,
     *  so merge logic lives here (Route) instead of scattered across models.
     *
     *  @param lane     the target mainline lane (usually outermost)
     *  @param seg      the segment index where the ramp connects
     *  @param car      the merging vehicle (just finished driving the ramp)
     *  @param maxWait  max re-check attempts before force-merge (default 20 = 10 s at rt=0.5)
     */
    def mergeFromRamp (lane: Int, seg: Int, car: Vehicle,
                       fromRamp: Ramp = null, maxWait: Int = 20): Unit =
        val targetVT = pathway(lane).seg(seg)
        val safeGap  = Vehicle.s + car.velocity * Vehicle.T      // IDM-consistent minimum gap

        var attempts = 0
        var merged   = false

        while !merged do
            val vAhead  = targetVT.getLast                       // tail of DLL = closest to junction
            val leadGap = if vAhead == null then Double.MaxValue
                          else vAhead.disp - 0.0 - Vehicle.len  // car enters at disp ≈ 0

            if leadGap >= safeGap || attempts >= maxWait then
                // Remove from ramp DLL just before mainline insertion.
                // This ensures followers on the ramp see the waiting car as their
                // leader for the entire wait, preventing overtaking (FIFO preserved).
                if fromRamp != null then fromRamp.removeFromAlist (car)
                // Accept gap (or force after timeout)
                pathway(lane).addToAlist (car, vAhead, seg)
                merged = true
            else
                // Gap insufficient — wait one timestep, re-check
                attempts += 1
                car.schedule (Vehicle.rt)
                car.yieldToDirector ()
            end if
        end while
    end mergeFromRamp

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    /**
     * A forcemerge that allows a vehicle to make mandatory lane changes,
     * as in the case of highway offramps where the vehicles that did not exit
     * must merge back into the mainline traffic.
     */
    def forceMerge(l1:Int, availLanes: Range, car: Vehicle, seg:Int): Int =

        //fllfflf
        val fromPath = pathway(l1) // current Pathway  (lane l1)
        var bestLane = -1     // initialize best lane to -1 (no best lane found for now)
        var minGap = -1.0      //fromPath.seg(seg).safetydist  // initialize minGap to a large value


        // look for the best lane to merge into using max space availability as the criteria
        cfor(availLanes){ i =>
            if pathway(i) != null then
                //val vAhead = pathway(i).seg(seg+1).getLast     // the vehicle ahead is the vehicle in the connecting segment and that vehcle is in seg+1
                val nextSeg = min(seg + 1, pathway(i).seg.length - 1)  // ensure we don't go out of bounds
                val segVT   = pathway(i).seg(nextSeg)
                if segVT != null then                              // guard: lane may not exist at nextSeg (variable lanes)
                    val vAhead = segVT.getLast   // vehicle ahead in next seg

                    // compute the gap ahead:
                    // if there is no vehicle ahead, then the gap is infinite
                    //else the gap is the distance from the start of the next segment to the vehicle ahead's rear bumper
                    val gapAhead = if vAhead == null then Double.PositiveInfinity
                    else segVT.length - (vAhead.disp - Vehicle.len)

                    if gapAhead > minGap then
                        minGap = gapAhead
                        bestLane = i
                    end if
                end if
            end if
        }

        if bestLane == -1 then bestLane = availLanes.start  // no available lane found, stay in the same lane

        // we can try standard adjacent lane change first
        val adjacent = abs(bestLane - l1) == 1    // adjacent lane
        val changed = adjacent && changeLane(l1, bestLane, car, seg)   // try standard lane change
        if changed then return bestLane    // successful standard lane change

        // force insert even if safety fails (lane ends)
        val toPath = pathway(bestLane)
        val nextSeg = min(seg + 1, toPath.seg.length - 1)
        val segVT   = toPath.seg(nextSeg)
        val vAhead  = if segVT != null then segVT.getLast else null

        // Only remove if the car is still in a DLL (caller may have already detached)
        if car.myPathNode != null && fromPath.seg(seg) != null then
            fromPath.removeFromAlist(car, seg)
        end if
        car.laneID = bestLane
        if toPath.seg(seg) != null then car.pathInfo = toPath.seg(seg).name
        toPath.addToAlist(car, vAhead, seg)

        bestLane
    end forceMerge


    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    /** Get the first vehicle in the specified lane.
     *  @param i  the index of the pathway/lane
     */
    def getFirst(i: Int): Vehicle = if pathway(i) != null then pathway(i).getFirst else null

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    /** Get the last vehicle in the specified lane.
     *  @param i  the index of the lane
     */
    def getLast(i: Int): Vehicle = if pathway(i) != null then pathway(i).getLast else null

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    /** Get the Pathway at index i.
     *  @param i  the lane index
     */
    def path(i: Int): Pathway = pathway(i)

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    /** Return the shared junctions.
     */
    def junctions: Array[Junction] = junc


    /** Return the number of segments (same for all Pathways).
     */
    def segments: Int = pathway(0).seg.length

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    /** All junction points in order: from +: junc :+ to.
     *  points(seg) is the upstream junction of segment `seg`.
     */
    private val _points: Array [Component] = (from +: junc.toIndexedSeq :+ to).toArray

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    /** Perpendicular unit vector pointing outward from road centerline
     *  toward the ramp side (opposite from lane 0 / rightmost lane).
     */
    val perpVec: (Double, Double) =
        val v = calcShift2
        (-v(0), -v(1))                                          // negate: away from lane 0

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    /** Return the screen (x, y) at the outermost lane edge of segment `seg`.
     *  Adapts to variable lane counts: more lanes → further from centerline.
     *  Points toward the ramp side (away from lane 0).
     *  @param seg  segment index (0 .. nSegments-1)
     */
    def rampAttachPoint (seg: Int): (Double, Double) =
        val pt      = _points(seg)                              // junction at segment boundary
        val nHere   = lanesAt(seg)
        val offset  = (nHere - numLanes / 2.0 - 0.4) * GAP       // slightly inside lane edge for visual snugness
        (pt.at(0) + perpVec._1 * offset,
         pt.at(1) + perpVec._2 * offset)
    end rampAttachPoint

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    /** Calculate the amount of shift in the x and y directions.
     */
    private def calcShift2: VectorD =
        val dx = to.at(0) - from.at(0)
        val dy = to.at(1) - from.at(1)
        val hyp = math.hypot(dx, dy)
        VectorD(dy / hyp, -dx / hyp)
    end calcShift2

    /** Calculate the amount of shift in the x and y directions.
     */
    private def calcShift: VectorD =
        val xdist = from.at(0) - to.at(0)
        val ydist = from.at(1) - to.at(1)
        val hyp = math.hypot(xdist, ydist)
        VectorD((ydist / hyp) * GAP, -(xdist / hyp) * GAP)
    end calcShift

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    /** Display the Route by displaying each Pathway.
     */
    override def display(): Unit =
        for l <- pathway if l != null do l.display()
    end display

end Route

//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** @author  John Miller
 *  @version 2.0
 *  @date    Sat Jan 25 19:44:16 EST 2014
 *  @see     LICENSE (MIT style license file).
 *
 *  @note    Route for Modeling Multi-Stage, Multi-Lane Pathway
 */

package scalation
package simulation
package process


import scalation.mathstat.VectorD
import scala.math.{min,abs}
//import scalation.random.Variate

//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** The `Route` class defines a multi-lane route composed of multiple `Pathway`s
 *  running in parallel. Each `Pathway` is a single-lane road that shares the same
 *  `from` (entry), `to` (exit), and intermediate `junc` (junction) components.
 *
 *  @param name     the name of the route
 *  @param numLanes the number of parallel lanes (Pathways)
 *  @param junc     the shared junction components between segments
 *  @param from     the shared starting component (e.g., VSource)
 *  @param to       the shared ending component (e.g., Sink)
 *  @param motion   the dynamics model used for movement
 *  @param isSpeed  whether speed or trip-time is used
 *  @param bend     curvature of the lanes
 */
class Route (name: String, numLanes: Int, junc: Array[Junction], from: Component, to: Component,
             motion: Dynamics, isSpeed: Boolean = false, bend: Double = 0.0,
             val lanesPerSeg: Array[Int] = null)
    extends Component ():


    private val debug = debugf("Route", true)     // debug function

    /** Number of segments in this route. */
    private val nSegments: Int = junc.length + 1   // from + junc.length intermediates + to = junc.length+1 points → junc.length+1-1 segs ... actually segments = intermediateJunc.length + 1

    /** Per-segment lane counts. If lanesPerSeg is null (uniform), fill with numLanes. */
    private val _lanesPerSeg: Array[Int] =
        if lanesPerSeg != null then lanesPerSeg
        else Array.fill(junc.length + 1)(numLanes)   // junc = intermediate junctions → nSegments = junc.length + 1

    /** Maximum lane count across all segments. */
    val maxLanes: Int = if _lanesPerSeg.nonEmpty then _lanesPerSeg.max else numLanes

    /** Query: how many lanes exist at segment `seg`. */
    def lanesAt (seg: Int): Int = _lanesPerSeg(seg)

    /** Query: does lane `lane` exist at segment `seg`? */
    def laneExistsAt (lane: Int, seg: Int): Boolean = lane < _lanesPerSeg(seg)

    val pathway: Array[Pathway] = Array.ofDim[Pathway](numLanes)      // create array of parallel Pathways
    private val GAP = 50.0     // pixel between lanes

    for i <- pathway.indices do
        val physicalLane = numLanes - 1 - i  // Reverse: i=0 → lane 4 (rightmost), i=4 → lane 0 (leftmost)
        val shift = calcShift2 * ((physicalLane - (numLanes - 1) / 2.0) * GAP)
        pathway(i) = new Pathway(s"${name}L$i", junc, from, to, motion, isSpeed, bend,
                                 laneShift = shift, laneIndex = i, lanesPerSeg = _lanesPerSeg)
        subpart += pathway(i)
    end for


    initComponent(name, from.at)   // using from.at for the initComponent


    // Cumulative length up to (but not including) each segment
    // segmentOffsets(0) = 0
    // segmentOffsets(1) = seg(0).length
    // segmentOffsets(2) = seg(0).length + seg(1).length
    // etc.
    val segmentOffsets: Array[Double] =
        val n = pathway(0).seg.length  // number of segments (same for all Pathways)
        val offsets = new Array[Double](n + 1)  // array to hold offsets
        offsets(0) = 0.0  // starting offset is 0.0
        for i <- 0 until n do
            // Find a non-null VTransport at this segment index (any lane will do — same geometry)
            val vt = pathway.map(_.seg(i)).find(_ != null).orNull
            offsets(i + 1) = offsets(i) + (if vt != null then vt.length else 0.0)
        end for
        offsets
    end segmentOffsets

    // O(1) helper: convert (segId, disp) → cumulative position
    @inline def toCumulative(segId: Int, disp: Double): Double =
        segmentOffsets(segId) + disp
    end toCumulative

    // ----------------------------------------------------------------------------

    /** Attempt to change lanes for a vehicle that is on segment `seg` of lane `l1`
     * and wants to move to adjacent lane `l2`.
     *
     * @return true if the lane-change succeeds; false otherwise
     */
    def changeLane(l1: Int, l2: Int, actor: Vehicle, seg: Int): Boolean =

        var success = abs(l1 - l2) == 1
        if !success then return success

        // Check if target lane exists at this segment (variable lane support)
        if !laneExistsAt(l2, seg) then return false
        // Check if source lane exists at this segment (car can't be here if lane is null)
        if !laneExistsAt(l1, seg) then return false

        val fromPath = pathway(l1) // current Pathway  (lane l1)
        val toPath = pathway(l2) // target Pathway   (lane l2)

        // Check if either lane doesn't exist
        if fromPath == null || toPath == null then return false

        val safeDisp = fromPath.seg(seg).safetydist

        //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
        // vehicles to check in target lane
        val vBehind = toPath.seg(seg).getFirst // car behind in same seg
        val vAhead = if seg + 1 < toPath.seg.length && toPath.seg(seg + 1) != null
            then toPath.seg(seg + 1).getLast else null

        //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
        // compute bumper-to-bumper gaps
        val gapBehind = if vBehind != null then actor.disp - vBehind.disp else safeDisp

        val nextSeg = min(seg + 1, toPath.seg.length - 1)

        val gapAhead =
            if vAhead != null then toPath.seg(nextSeg).length - vAhead.disp - Vehicle.len
            else safeDisp

        val gap = min(gapBehind, gapAhead)
        //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
        // feasibility check
        success &&= gapBehind >= safeDisp && gapAhead >= safeDisp

        //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
        // --- perform the lane change --------------------------------------------
        if success then
            fromPath.removeFromAlist(actor, seg) // detach from old lane at this segment
            assert(actor.myPathNode == null, s"Vehicle $this not cleared before lane-change insertion!")

            actor.laneID = l2 // update laneID
            actor.pathInfo = toPath.seg(seg).name // update pathInfo
            toPath.addToAlist(actor, vAhead, seg) // insert before vAhead in target lane at this segment
        end if

        success
    end changeLane

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    /** Merge a ramp vehicle into the mainline at the given lane and segment.
     *  Checks lead and lag gaps before inserting.  If the gap is insufficient,
     *  the vehicle yields (waits one timestep) and re-checks — up to `maxWait`
     *  attempts.  After the timeout, force-merges.
     *
     *  This replaces the raw `getLast + addToAlist` pattern in model files,
     *  so merge logic lives here (Route) instead of scattered across models.
     *
     *  @param lane     the target mainline lane (usually outermost)
     *  @param seg      the segment index where the ramp connects
     *  @param car      the merging vehicle (just finished driving the ramp)
     *  @param maxWait  max re-check attempts before force-merge (default 20 = 10 s at rt=0.5)
     */
    def mergeFromRamp (lane: Int, seg: Int, car: Vehicle,
                       fromRamp: Ramp = null, maxWait: Int = 20): Unit =
        val targetVT = pathway(lane).seg(seg)
        val safeGap  = Vehicle.s + car.velocity * Vehicle.T      // compute BEFORE zeroing velocity

        // Fix 1: car is physically stopped at the merge point — zero its velocity
        // so followers' IDM sees Δv > 0 and brakes proactively (not just reactively).
        car.velocity = 0.0

        var attempts = 0
        var merged   = false

        while !merged do
            // Fix 3 (FIFO): only the ramp DLL head may attempt to merge.
            // If there's a car ahead in the ramp DLL, our leader hasn't merged yet — yield.
            val mustWaitForRampLeader = fromRamp != null && car.myPathNode != null
                                       && car.myPathNode.ahead != null

            if mustWaitForRampLeader then
                car.schedule (Vehicle.rt)
                car.yieldToDirector ()
            else
                val vAhead  = targetVT.getLast                       // tail of DLL = closest to junction
                val leadGap = if vAhead == null then Double.MaxValue
                              else vAhead.disp - 0.0 - Vehicle.len  // car enters at disp ≈ 0

                if leadGap >= safeGap || attempts >= maxWait then
                    // Remove from ramp DLL just before mainline insertion (atomic transition).
                    if fromRamp != null then fromRamp.removeFromAlist (car)
                    // Accept gap (or force after timeout)
                    pathway(lane).addToAlist (car, vAhead, seg)
                    merged = true
                else
                    // Gap insufficient — wait one timestep, re-check
                    attempts += 1
                    car.schedule (Vehicle.rt)
                    car.yieldToDirector ()
                end if
            end if
        end while
    end mergeFromRamp

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    /**
     * A forcemerge that allows a vehicle to make mandatory lane changes,
     * as in the case of highway offramps where the vehicles that did not exit
     * must merge back into the mainline traffic.
     */
    def forceMerge(l1:Int, availLanes: Range, car: Vehicle, seg:Int): Int =

        //fllfflf
        val fromPath = pathway(l1) // current Pathway  (lane l1)
        var bestLane = -1     // initialize best lane to -1 (no best lane found for now)
        var minGap = -1.0      //fromPath.seg(seg).safetydist  // initialize minGap to a large value


        // look for the best lane to merge into using max space availability as the criteria
        cfor(availLanes){ i =>
            if pathway(i) != null then
                //val vAhead = pathway(i).seg(seg+1).getLast     // the vehicle ahead is the vehicle in the connecting segment and that vehcle is in seg+1
                val nextSeg = min(seg + 1, pathway(i).seg.length - 1)  // ensure we don't go out of bounds
                val segVT   = pathway(i).seg(nextSeg)
                if segVT != null then                              // guard: lane may not exist at nextSeg (variable lanes)
                    val vAhead = segVT.getLast   // vehicle ahead in next seg

                    // compute the gap ahead:
                    // if there is no vehicle ahead, then the gap is infinite
                    //else the gap is the distance from the start of the next segment to the vehicle ahead's rear bumper
                    val gapAhead = if vAhead == null then Double.PositiveInfinity
                    else segVT.length - (vAhead.disp - Vehicle.len)

                    if gapAhead > minGap then
                        minGap = gapAhead
                        bestLane = i
                    end if
                end if
            end if
        }

        if bestLane == -1 then bestLane = availLanes.start  // no available lane found, stay in the same lane

        // we can try standard adjacent lane change first
        val adjacent = abs(bestLane - l1) == 1    // adjacent lane
        val changed = adjacent && changeLane(l1, bestLane, car, seg)   // try standard lane change
        if changed then return bestLane    // successful standard lane change

        // force insert even if safety fails (lane ends)
        val toPath = pathway(bestLane)
        val nextSeg = min(seg + 1, toPath.seg.length - 1)
        val segVT   = toPath.seg(nextSeg)
        val vAhead  = if segVT != null then segVT.getLast else null

        // Only remove if the car is still in a DLL (caller may have already detached)
        if car.myPathNode != null && fromPath.seg(seg) != null then
            fromPath.removeFromAlist(car, seg)
        end if
        car.laneID = bestLane
        if toPath.seg(seg) != null then car.pathInfo = toPath.seg(seg).name
        toPath.addToAlist(car, vAhead, seg)

        bestLane
    end forceMerge


    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    /** Get the first vehicle in the specified lane.
     *  @param i  the index of the pathway/lane
     */
    def getFirst(i: Int): Vehicle = if pathway(i) != null then pathway(i).getFirst else null

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    /** Get the last vehicle in the specified lane.
     *  @param i  the index of the lane
     */
    def getLast(i: Int): Vehicle = if pathway(i) != null then pathway(i).getLast else null

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    /** Get the Pathway at index i.
     *  @param i  the lane index
     */
    def path(i: Int): Pathway = pathway(i)

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    /** Return the shared junctions.
     */
    def junctions: Array[Junction] = junc


    /** Return the number of segments (same for all Pathways).
     */
    def segments: Int = pathway(0).seg.length

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    /** All junction points in order: from +: junc :+ to.
     *  points(seg) is the upstream junction of segment `seg`.
     */
    private val _points: Array [Component] = (from +: junc.toIndexedSeq :+ to).toArray

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    /** Perpendicular unit vector pointing outward from road centerline
     *  toward the ramp side (opposite from lane 0 / rightmost lane).
     */
    val perpVec: (Double, Double) =
        val v = calcShift2
        (-v(0), -v(1))                                          // negate: away from lane 0

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
    /** Return the screen (x, y) at the outermost lane edge of segment `seg`.
     *  Adapts to variable lane counts: more lanes → further from centerline.
     *  Points toward the ramp side (away from lane 0).
     *  @param seg  segment index (0 .. nSegments-1)
     */
    def rampAttachPoint (seg: Int): (Double, Double) =
        val pt      = _points(seg)                              // junction at segment boundary
        val nHere   = lanesAt(seg)
        val offset  = (nHere - numLanes / 2.0 - 0.4) * GAP       // slightly inside lane edge for visual snugness
        (pt.at(0) + perpVec._1 * offset,
         pt.at(1) + perpVec._2 * offset)
    end rampAttachPoint

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    /** Calculate the amount of shift in the x and y directions.
     */
    private def calcShift2: VectorD =
        val dx = to.at(0) - from.at(0)
        val dy = to.at(1) - from.at(1)
        val hyp = math.hypot(dx, dy)
        VectorD(dy / hyp, -dx / hyp)
    end calcShift2

    /** Calculate the amount of shift in the x and y directions.
     */
    private def calcShift: VectorD =
        val xdist = from.at(0) - to.at(0)
        val ydist = from.at(1) - to.at(1)
        val hyp = math.hypot(xdist, ydist)
        VectorD((ydist / hyp) * GAP, -(xdist / hyp) * GAP)
    end calcShift

    //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::

    /** Display the Route by displaying each Pathway.
     */
    override def display(): Unit =
        for l <- pathway if l != null do l.display()
    end display

end Route

//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** @author John Miller, Casey Bowman * @version 2.0 * @date Tue Feb 4 14:56:34 EST 2020 * @see LICENSE (MIT style license file). * * @note Variable Speed Transport is a Pathway between Components */
package scalation package simulation package process //import scalation.animation.DgAnimator.VehicleState
//import scala.collection.mutable.ArrayDeque //import scala.runtime.ScalaRunTime.stringOf
import scalation.animation.CommandType._ //import scalation.database.BpTreeMap import scalation.mathstat._ import scala.collection.mutable.ArrayDeque
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `VTransport` class provides a variable-speed pathway between two other components. * The components in a `Model` conceptually form a 'graph' in which the edges * are `VTransport`s and the nodes are other `Component`s. * @see `animation.Dgraph.move2Boundary` that aligns edge with node boundaries. * @param name the name of the variable-speed transport * @param from the starting component * @param to the ending component * @param motion the dynamics model for the speed/trip-time for motion down the `VTransport` * @param isSpeed whether speed or trip-time is used for motion * @param bend the bend or curvature of the `VTransport` (0 => line) * @param shift1 the x-y shift for the transport's first end-point (from-side) * @param shift2 the x-y shift for the transport's second end-point (to-side) */ class VTransport (name: String, from_ : Component, to_ : Component, motion: Dynamics, isSpeed: Boolean = false, bend: Double = 0.0, shift1: VectorD = VectorD (0, 0), shift2: VectorD = VectorD (0, 0), segIndex: Int = -1) extends Transport (name, from_, to_, null, isSpeed, bend, shift1, shift2):
private val debug = debugf ("VTransport", false) // debug function //debug ("init", s"name = $name, p1 = $p1, pc = $pc, p2 = $p2, located at ${stringOf (at)}")
var length = 0.0 // The actual length of the road segment. if length <= 0.0 then length = curve.length val safetydist = 20.0
private [process] val vdeque = ArrayDeque [Vehicle] () // Array Deque for density tracking (entry order)
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Per-segment doubly linked list for car-following. * Each VTransport owns its own DLL — the car-following backbone. * Replaces the lane-spanning Pathway.vList for leader lookup. */ private [process] val vList = DoublyLinkedList [Vehicle]
/** Debug label for this segment's DLL. */ val dllId = s"DLL_${name}"
private[process] val easyW = new EasyWriter("simulation", "OnewayVehicle2LModel.txt") easyW.off()
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Add a vehicle to this segment's doubly linked list. * @param actor the vehicle to add * @param other the vehicle ahead (null if none) */ def addToAlist (actor: Vehicle, other: Vehicle): Unit = val otherNode = if other != null then other.myPathNode.asInstanceOf [vList.Node] else null actor.myPathNode = vList.add (actor, otherNode) actor.pathInfo = dllId end addToAlist
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Remove a vehicle from this segment's doubly linked list. * @param actor the vehicle to remove */ def removeFromAlist (actor: Vehicle): Unit = vList.remove (actor.myPathNode.asInstanceOf [vList.Node]) actor.myPathNode = null end removeFromAlist
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Get the first vehicle in this segment (lead car, head of DLL). */ def getFirst: Vehicle = val first: Vehicle = if vList.isEmpty then null else vList.head debug ("getFirst", s"the first vehicle = $first") first end getFirst
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Get the last vehicle in this segment (most recently entered, tail of DLL). */ def getLast: Vehicle = val last: Vehicle = if vList.isEmpty then null else vList.last debug ("getLast", s"the last vehicle = $last") last end getLast
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the instantaneous traffic density on this segment. * density k = number of vehicles on segment / segment length (veh/m) * Called from driveHighway after each move() to snapshot the segment state. */ def snapshotDensity (): Double = if length > 0.0 then vdeque.size.toDouble / length else 0.0 end snapshotDensity
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Move the entity (SimActor) smoothly down this VTransport (e.g., road). * Repeatedely move it along the VTransport/Edge/QCurve. * Caveat: tokens coordinates are computed using a shadow QCurve (same coordinates * as the one that will be created by the animation engine). */
override def move(): Unit =
val actor = director.theActor.asInstanceOf[Vehicle] val lastSeg = actor.segId // segment before entering this one val lastEnterTime = actor.segmentEnterTime // time entered previous segment val now = director.clock actor.segmentEnterTime = now // update the current actor's segmentEnterTime with now
//actor.prevSegId = lastSeg actor.segId = segIndex // update the current actor's segment_ID with actor.disp = 0.0 actor.pathInfo = name //update the current actor's lane_ID with the Vtransport_ID it is moving in
//val segTT = if lastSeg >= 0 then f"${now - actor.segmentEnterTime}%.2f" else "N/A" easyW.println(s"[t=$now] Vehicle ${actor.displayLabel} enters seg=${actor.segId} (from seg=$lastSeg), enterT=$now")
//debug("move", s"actor = $actor, disp=${actor.disp} along the VTransport") vdeque += actor
tally(Vehicle.rt)
var done = false while actor.disp < length && !done do //director.log.trace(this, "moves for " + Vehicle.rt, actor, director.clock)
motion.updateV(actor, length) // update actor/vehicle's motion/position
val cp = calcPoint2(actor.disp) //debug ("move", s"${actor.displayLabel}, check if actor.disp = ${actor.disp} >= curve.length = ${curve.length}") if actor.disp >= length then done = true vdeque -= actor end if
if !done then val vColor = Vehicle.velocityColor (actor.velocity) director.animate(actor, MoveToken, vColor, null, cp) actor.schedule(Vehicle.rt) actor.yieldToDirector() end while
//debug("moveFinal", s" $actor: Final actor displacement: t_disp = ${actor.t_disp}") end move
def calcPoint2(s: Double): Array[Double] = curve.traj = s / curve.length // percentage of the curve the car has traveled thus far. val xy = curve.eval() Array(xy.x, xy.y) end calcPoint2
//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** Calculate the (x, y) point in the simulation space for the vehicle. * * @param s the current displacement along the road of the vehicle. */ def calcPoint(s: Double): Array[Double] = val prop = s / curve.length val x = p1(0) + (p2(0) - p1(0)) * prop val y = p1(1) + (p2(1) - p1(1)) * prop Array(x - RAD, y - RAD) end calcPoint
end VTransport

//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** @author John Miller, Casey Bowman * @version 2.0 * @date Tue Feb 4 14:56:34 EST 2020 * @see LICENSE (MIT style license file). * * @note Variable Speed Transport is a Pathway between Components */
package scalation package simulation package process //import scalation.animation.DgAnimator.VehicleState
//import scala.collection.mutable.ArrayDeque //import scala.runtime.ScalaRunTime.stringOf
import scalation.animation.CommandType._ //import scalation.database.BpTreeMap import scalation.mathstat._ import scala.collection.mutable.ArrayDeque
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `VTransport` class provides a variable-speed pathway between two other components. * The components in a `Model` conceptually form a 'graph' in which the edges * are `VTransport`s and the nodes are other `Component`s. * @see `animation.Dgraph.move2Boundary` that aligns edge with node boundaries. * @param name the name of the variable-speed transport * @param from the starting component * @param to the ending component * @param motion the dynamics model for the speed/trip-time for motion down the `VTransport` * @param isSpeed whether speed or trip-time is used for motion * @param bend the bend or curvature of the `VTransport` (0 => line) * @param shift1 the x-y shift for the transport's first end-point (from-side) * @param shift2 the x-y shift for the transport's second end-point (to-side) */ class VTransport (name: String, from_ : Component, to_ : Component, motion: Dynamics, isSpeed: Boolean = false, bend: Double = 0.0, shift1: VectorD = VectorD (0, 0), shift2: VectorD = VectorD (0, 0), segIndex: Int = -1) extends Transport (name, from_, to_, null, isSpeed, bend, shift1, shift2):
private val debug = debugf ("VTransport", false) // debug function //debug ("init", s"name = $name, p1 = $p1, pc = $pc, p2 = $p2, located at ${stringOf (at)}")
var length = 0.0 // The actual length of the road segment. if length <= 0.0 then length = curve.length val safetydist = 20.0
private [process] val vdeque = ArrayDeque [Vehicle] () // Array Deque for density tracking (entry order)
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Per-segment doubly linked list for car-following. * Each VTransport owns its own DLL — the car-following backbone. * Replaces the lane-spanning Pathway.vList for leader lookup. */ private [process] val vList = DoublyLinkedList [Vehicle]
/** Debug label for this segment's DLL. */ val dllId = s"DLL_${name}"
private[process] val easyW = new EasyWriter("simulation", "OnewayVehicle2LModel.txt") easyW.off()
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Add a vehicle to this segment's doubly linked list. * @param actor the vehicle to add * @param other the vehicle ahead (null if none) */ def addToAlist (actor: Vehicle, other: Vehicle): Unit = val otherNode = if other != null then other.myPathNode.asInstanceOf [vList.Node] else null actor.myPathNode = vList.add (actor, otherNode) actor.pathInfo = dllId end addToAlist
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Remove a vehicle from this segment's doubly linked list. * @param actor the vehicle to remove */ def removeFromAlist (actor: Vehicle): Unit = vList.remove (actor.myPathNode.asInstanceOf [vList.Node]) actor.myPathNode = null end removeFromAlist
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Get the first vehicle in this segment (lead car, head of DLL). */ def getFirst: Vehicle = val first: Vehicle = if vList.isEmpty then null else vList.head debug ("getFirst", s"the first vehicle = $first") first end getFirst
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Get the last vehicle in this segment (most recently entered, tail of DLL). */ def getLast: Vehicle = val last: Vehicle = if vList.isEmpty then null else vList.last debug ("getLast", s"the last vehicle = $last") last end getLast
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the instantaneous traffic density on this segment. * density k = number of vehicles on segment / segment length (veh/m) * Called from driveHighway after each move() to snapshot the segment state. */ def snapshotDensity (): Double = if length > 0.0 then vdeque.size.toDouble / length else 0.0 end snapshotDensity
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Move the entity (SimActor) smoothly down this VTransport (e.g., road). * Repeatedely move it along the VTransport/Edge/QCurve. * Caveat: tokens coordinates are computed using a shadow QCurve (same coordinates * as the one that will be created by the animation engine). */
override def move(): Unit =
val actor = director.theActor.asInstanceOf[Vehicle] val lastSeg = actor.segId // segment before entering this one val lastEnterTime = actor.segmentEnterTime // time entered previous segment val now = director.clock actor.segmentEnterTime = now // update the current actor's segmentEnterTime with now
//actor.prevSegId = lastSeg actor.segId = segIndex // update the current actor's segment_ID with actor.disp = 0.0 actor.pathInfo = name //update the current actor's lane_ID with the Vtransport_ID it is moving in
//val segTT = if lastSeg >= 0 then f"${now - actor.segmentEnterTime}%.2f" else "N/A" easyW.println(s"[t=$now] Vehicle ${actor.displayLabel} enters seg=${actor.segId} (from seg=$lastSeg), enterT=$now")
//debug("move", s"actor = $actor, disp=${actor.disp} along the VTransport") vdeque += actor
tally(Vehicle.rt)
var done = false while actor.disp < length && !done do //director.log.trace(this, "moves for " + Vehicle.rt, actor, director.clock)
motion.updateV(actor, length) // update actor/vehicle's motion/position
val cp = calcPoint2(actor.disp) //debug ("move", s"${actor.displayLabel}, check if actor.disp = ${actor.disp} >= curve.length = ${curve.length}") if actor.disp >= length then done = true vdeque -= actor end if
if !done then val vColor = Vehicle.velocityColor (actor.velocity) director.animate(actor, MoveToken, vColor, null, cp) actor.schedule(Vehicle.rt) actor.yieldToDirector() end while
println(f"[move EXIT] ${actor.displayLabel}%-12s seg=${actor.segId} disp=${actor.disp}%.2f v=${actor.velocity}%.2f length=${length}%.2f vt=$name") end move
def calcPoint2(s: Double): Array[Double] = curve.traj = s / curve.length // percentage of the curve the car has traveled thus far. val xy = curve.eval() Array(xy.x, xy.y) end calcPoint2
//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** Calculate the (x, y) point in the simulation space for the vehicle. * * @param s the current displacement along the road of the vehicle. */ def calcPoint(s: Double): Array[Double] = val prop = s / curve.length val x = p1(0) + (p2(0) - p1(0)) * prop val y = p1(1) + (p2(1) - p1(1)) * prop Array(x - RAD, y - RAD) end calcPoint
end VTransport

//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** @author John Miller, Casey Bowman * @version 2.0 * @date Tue Feb 4 14:56:34 EST 2020 * @see LICENSE (MIT style license file). * * @note Supports Physics Models for Motion of Vehicles */
package scalation package simulation package process
import scala.math.{abs, max, min, sqrt} import scalation.mathstat.* import scalation.dynamics.* import Vehicle.*
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Enumeration for selecting the ODE integrator type for IDM dynamics. * Used for experimental comparison of numerical integration methods. */ enum IntegratorType: case DOPRI5 // Dormand-Prince (4,5) adaptive - O(Δt⁵) - current default case RK4 // Classic Runge-Kutta 4th order - O(Δt⁴) case RK3 // SSPRK3 - O(Δt³) case RK2 // Modified Euler (Explicit Midpoint) - O(Δt²) case Heun // Heun's method (Explicit Trapezoidal) - O(Δt²) - Treiber recommended case Euler // Forward Euler - O(Δt¹) - what SUMO uses case butcher // Butcher 5th order - O(Δt⁵) case Ballistic // Kinematic equations - O(Δt²) end IntegratorType
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `Dynamics` trait supports physics models for the motion of vehicles, e.g., * car-following models. */ trait Dynamics:
private [process] var disp = 0.0 // set initial current displacement to 0 private [process] var t_disp = 0.0 // set initial total displacement to 0 private [process] var velocity = v0 // set initial velocity to v0 private [process] var o_t_disp = t_disp // set initial old total displacement t_disp private [process] var o_velocity = velocity // set initial old velocity to velocity private [process] var acc = 0.0 // set initial acceleration to 0 private [process] var o_acc = acc // set initial old acceleration acc
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Find the leader of the given vehicle using per-VTransport DLLs. * Step 1: within-segment leader (myPathNode.ahead). * Step 2: cross-boundary — next segment's DLL tail (mainline vehicles). * Step 3: ramp dual-leader — peek at mainline merge target (Treiber §11.3). * @param car the vehicle whose leader we need * @return the leader vehicle, or null if free-flow */ protected def findLeader (car: Vehicle): Vehicle = val onRamp = car.myRamp != null // DIAG
if car.myPathNode == null then return null // between DLLs → free-flow
// Step 1: within-segment leader (O(1) DLL lookup) val ref = car.myPathNode.ahead if ref != null then if onRamp then val ldr = ref.elem val mePath = if car.myPathway != null then car.myPathway.name else "null" val meRamp = if car.myRamp != null then car.myRamp.name else "null" val ldrPath = if ldr.myPathway != null then ldr.myPathway.name else "null" val ldrRamp = if ldr.myRamp != null then ldr.myRamp.name else "null" println(f"[findLeader] ${car.displayLabel}%-12s STEP1 seg=${car.segId} path=$mePath ramp=$meRamp | ldr=${ldr.displayLabel} ldr.seg=${ldr.segId} ldr.path=$ldrPath ldr.ramp=$ldrRamp | me.disp=${car.disp}%.2f me.v=${car.velocity}%.2f ldr.disp=${ldr.disp}%.2f ldr.v=${ldr.velocity}%.2f") end if // DIAG return ref.elem
// Step 2: cross-boundary — look at next segment's DLL tail val pw = car.myPathway if pw != null then val segs = pw.seg val nextIdx = car.segId + 1 if nextIdx < segs.length && segs(nextIdx) != null then return segs(nextIdx).getLast end if
// Step 3: ramp → peek at mainline merge segment (dual-leader) val ramp = car.myRamp if ramp != null && ramp.targetPathway != null && ramp.targetSegId >= 0 then val targetVT = ramp.targetPathway.seg(ramp.targetSegId) if targetVT != null then val ml = targetVT.getLast if ml != null then return ml end if end if
null end findLeader
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Update the values of the vehicle: velocity, displacement, lane according * to the car-following model being used. * @param motion the dynamics/physics determining the motion (e.g., car-following model) * @param car the vehivle to move
*/ def updateV (car: Vehicle, maxDisp: Double): Unit = // println (s"Dynamics.updateV: called $car") this match case GippsDynamics => { GippsDynamics.updateM (car, maxDisp) } case KraussDynamics => { KraussDynamics.updateM (car, maxDisp) } case _ => { IDMDynamics.updateM (car, maxDisp) } end updateV
end Dynamics
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `GippsDynamics` object provides equations for the Gipps car-following model. * @see https://en.wikipedia.org/wiki/Gipps%27_model */ object GippsDynamics extends Dynamics:
private val debug = debugf ("GippsDynamics", false) // debug function private[process] val easyW = new EasyWriter("simulation", "CalRoute101Model.txt")
/** Integrator type for position update (configurable, default Ballistic) */ var integratorType: IntegratorType = IntegratorType.Ballistic
/** Update the vehicle's velocity and position using Gipps' Model. * Position update method is configurable via integratorType. * * @param car the car/vehicle whose velocity and position is being updated */ /** Update the vehicle's velocity and position using Gipps' Model. * All gap and position computations use segment-local `disp` — consistent with * per-segment DLLs where the leader is always in the same or adjacent segment. * `t_disp` is updated as a derived statistic only. */ def updateM(car: Vehicle, length: Double): Unit = val car_ahead = findLeader (car) val dt = prop("rt")
// Step 1: compute next velocity using Gipps (discrete rule) val v = gipps(car, car_ahead, length) + EPSILON
// Step 2: update position in segment-local coordinates val x = integratorType match case IntegratorType.Ballistic => car.disp + car.velocity * dt case IntegratorType.butcher => butcher(car.disp, car.velocity, car.o_velocity, dt) case _ => car.disp + car.velocity * dt
// Step 3: commit velocity state AFTER position integration car.o_velocity = car.velocity car.velocity = v
// Step 4: segment-bounded + collision-free displacement update car.o_t_disp = car.t_disp
// --- Collision-free position clamp (SUMO/VISSIM/Aimsun standard practice) --- // Even if the velocity model overshoots, clamp position to maintain gap ≥ s0 // behind leader. Uses segment-local leader position (cross-seg already handled). var x_safe = x if car_ahead != null then val xl = if car_ahead.segId == car.segId then car_ahead.disp else length + car_ahead.disp if xl - x_safe - len < s then x_safe = xl - len - s // park at min gap behind leader end if // val new_disp = max(0.0, if x <= length then x else length) // OLD: no collision-free clamp val new_disp = max(0.0, if x_safe <= length then x_safe else length)
car.t_disp += new_disp - car.disp // derive t_disp from clamped delta car.disp = new_disp end updateM
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the velocity of the vehicle based on Gipps' model for a vehicle and its predecessor. * With per-segment DLLs, leader is always same-seg or next-seg. All positions are segment-local. * @param cn the current vehicle * @param cp the predecessor of the current vehicle (from findLeader — always same or next segment) */ def gipps (cn: Vehicle, cp: Vehicle, length: Double): Double = if cp == null then gipps (amax, bmax, len, cn.vmax, cn.disp, cn.velocity, cn.disp + 1000, cn.vmax, prop("rt")) else // Leader is in same segment or adjacent next segment val cp_r_disp = if cp.segId == cn.segId then cp.disp else length + cp.disp gipps (amax, bmax, len, cn.vmax, cn.disp, cn.velocity, cp_r_disp, cp.velocity, prop("rt")) end gipps //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** Return the velocity of the vehicle based on Gipps' model. * * @param an the max acceleration of drivers * @param bn the max deceleration of drivers (may be negative) * @param sp the size of vehicles * @param Vn the desired velocity of driver n * @param xn the current position of driver n * @param vn the current velocity of driver n * @param xp the current position of the predecessor (ahead) * @param vp the current velocity of the predecessor * @param rt the reaction time of drivers */ private def gipps(an: Double, bn: Double, sp: Double, Vn: Double, xn: Double, vn: Double, xp: Double, vp: Double, rt: Double): Double = // --------------- Parameters --------------------- val b = abs(bn) // use positive magnitude of deceleration val b_hat = b * 1.8 // expected braking ability of leader (default 0.8×b) b_hat >= b
// --------------- Free-flow branch --------------- // v_free = v_n + 2.5 * a_n * τ * (1 - v_n/V_n) * sqrt(0.025 + v_n/V_n) val free = vn + (2.5 * an * rt * (1.0 - vn / Vn)) * sqrt(0.025 + vn / Vn)
// --------------- Congested (safety) branch ------- // v_cong = b * τ + sqrt(b^2 * τ^2 - b[2(gap) - v_nτ - v_p^2/b̂]) val gap = xp - sp - xn // effective front-to-front gap val phi = 2.0 * gap - (vn * rt) - (vp * vp / b_hat) // safety term inside brackets
// When phi >= 0, spacing is large enough that braking constraint is inactive. // In that case, use free-flow velocity directly (skip sqrt computation). if phi >= 0.0 then return free
// Otherwise, apply the congested/safety branch. val inner_exp = (b * b * rt * rt) - b * phi // value inside sqrt val cong = (b * rt) + sqrt(max(0.0, inner_exp)) // braking (congested) velocity min(free, cong) end gipps
end GippsDynamics
object KraussDynamics extends Dynamics:
private val debug = debugf("KraussDynamics", false)
/** Krauss stochastic imperfection magnitude (m/s) * Must be small relative to amax*tau to allow net acceleration */ private val sigma = 0.2
/** Uniform random variate for stochastic noise */ private val noiseRV = scalation.random.Uniform(0.0, sigma)
/** Integrator type for position update (configurable, default Ballistic) */ var integratorType: IntegratorType = IntegratorType.Ballistic
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Update the vehicle's velocity and position using Krauss Model. * All gap and position computations use segment-local `disp` — consistent with * per-segment DLLs where the leader is always in the same or adjacent segment. * `t_disp` is updated as a derived statistic only. * @param car the vehicle to update * @param length the segment length */ def updateM(car: Vehicle, length: Double): Unit = val car_ahead = findLeader (car) val dt = prop("rt")
// Compute leader position and velocity (segment-local) val (xp, vp): (Double, Double) = if car_ahead == null then (car.disp + 1000.0, car.vmax) // phantom leader (free flow) else if car_ahead.segId == car.segId then (car_ahead.disp, car_ahead.velocity) else (length + car_ahead.disp, car_ahead.velocity)
// Step 1: Compute next velocity using Krauss val v_new = krauss( amax, bmax, len, car.vmax, car.disp, car.velocity, xp, vp, dt, s )
// Step 2: Position update in segment-local coordinates val x_new = integratorType match case IntegratorType.Ballistic => car.disp + car.velocity * dt case IntegratorType.butcher => butcher(car.disp, car.velocity, car.o_velocity, dt) case _ => car.disp + car.velocity * dt
// Step 3: Commit velocity state AFTER position update car.o_velocity = car.velocity car.velocity = v_new
// Step 4: Segment-bounded + collision-free displacement update car.o_t_disp = car.t_disp
// --- Collision-free position clamp (SUMO/VISSIM/Aimsun standard practice) --- var x_safe = x_new if car_ahead != null && xp - x_safe - len < s then x_safe = xp - len - s // park at min gap behind leader end if // val new_disp = max(0.0, if x_new <= length then x_new else length) // OLD: no collision-free clamp val new_disp = max(0.0, if x_safe <= length then x_safe else length)
car.t_disp += new_disp - car.disp // derive t_disp from clamped delta car.disp = new_disp end updateM
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Compute next velocity using Krauss car-following model. * Safety is enforced BEFORE stochastic noise is applied. * * @param an max acceleration * @param bn max deceleration (negative) * @param sp vehicle length * @param Vn desired speed * @param xn follower position * @param vn follower velocity * @param xp leader position * @param vp leader velocity * @param rt reaction time (timestep) * @param s0 minimum spacing */ private def krauss(an: Double, bn: Double, sp: Double, Vn: Double, xn: Double, vn: Double, xp: Double, vp: Double, rt: Double, s0: Double): Double = val b = abs(bn)
// Netto gap (front-to-rear) val gap = xp - xn - sp if gap <= 0.0 then return 0.0 // collision avoidance
// Krauss safe speed: v_safe = sqrt(v_leader^2 + 2*b*(gap - s0)) val inner = vp * vp + 2.0 * b * (gap - s0) val v_safe = sqrt(max(0.0, inner))
// Acceleration constraint: v_cap = v + a_max * tau val v_cap = vn + an * rt
// Desired speed constraint val v_des = Vn
// Deterministic candidate (minimum of all constraints) val v_star = min(v_des, min(v_safe, v_cap))
// Stochastic imperfection applied AFTER safety val eps = noiseRV.gen max(0.0, v_star - eps) end krauss
end KraussDynamics
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `IDMDynamics` object provides equations for the Intelligent Driver Model (IDM) * car-following model. * @see https://en.wikipedia.org/wiki/Intelligent_driver_model */
object IDMDynamics extends Dynamics:
private val debug = debugf ("IDMDynamics", true) // debug function
private val FREERANGE = 150.0
/** Configurable integrator type for ODE solving - default Ballistic */ var integratorType: IntegratorType = IntegratorType.Ballistic
/** Flag to print integrator type only once per simulation run */ private var integratorPrinted: Boolean = false
/** Reset the print flag - call this before each new simulation */ def resetIntegratorPrintFlag(): Unit = integratorPrinted = false
/** * Update the vehicle's velocity and position using the Intelligent Driver Model. * All gap and position computations use segment-local `disp` — consistent with * per-segment DLLs where the leader is always in the same or adjacent segment. * `t_disp` is updated as a derived statistic only. * @param car the vehicle to update * @param length the segment length */ def updateM(car: Vehicle, length: Double): Unit = val car_ahead = findLeader (car) val dt = rt
// ───────────────────────────────────────────────────────────────────────── // STEP 1: Snapshot leader state in SEGMENT-LOCAL coordinates. // With per-segment DLLs, findLeader returns same-seg or next-seg only. // ───────────────────────────────────────────────────────────────────────── val (x_leader, v_leader): (Double, Double) = if car_ahead == null then (car.disp + 1000.0, car.velocity) // no leader: free-flow else val xl = if car_ahead.segId == car.segId then car_ahead.disp else length + car_ahead.disp // next segment // Fix 2: skip FREERANGE for ramp cars — ramp must always track the // mainline dual-leader to decelerate before merge (Treiber §11.3). if xl - car.disp > FREERANGE && car.myRamp == null then (car.disp + 1000.0, car.velocity) // leader far ahead: free-flow else (xl, car_ahead.velocity) // real leader
// ───────────────────────────────────────────────────────────────────────── // STEP 2: Save old state for history tracking // ───────────────────────────────────────────────────────────────────────── val v_old = car.velocity val x_old = car.disp // segment-local
/** * @param x_n Current position of driver n (segment-local, from ODE solver trial values) * @param v_n Current velocity of driver n (from ODE solver trial values) * @return IDM acceleration clamped to physical bounds [-b_emergency, amax] */ def idmAccel(x_n: Double, v_n: Double): Double = val b = abs(bmax) // comfortable decel for IDM s* formula
var a = iDM(amax, b, len, car.vmax, x_n, v_n, x_leader, v_leader, T, s, del)
val a_raw = a // save before clamp if a.isNaN || a.isInfinity then a = 0.0 // if a < -b then a = -b // OLD: comfortable clamp (bmax = 2.0) val a_floor = max(b_emergency, -v_n / dt) // SUMO-style: can't decel past stopping if a < a_floor then a = a_floor // allows b_emergency at high v, gentler at low v if a > amax then a = amax a end idmAccel
// Array of derivative functions: [dx/dt, dv/dt] val odes: Array[DerivativeV] = Array( (t: Double, y: VectorD) => y(1), // dx/dt = v (velocity) (t: Double, y: VectorD) => idmAccel(y(0), y(1)) // dv/dt = a (IDM acceleration) )
// ───────────────────────────────────────────────────────────────────────── // STEP 4: Solve the coupled system in segment-local coordinates // ───────────────────────────────────────────────────────────────────────── val y0 = VectorD(car.disp, car.velocity) // segment-local initial state
// Print integrator type ONCE per simulation (from inside updateM, not from caller) if !integratorPrinted then println(s"[IDMDynamics.updateM] INTEGRATOR IN USE: $integratorType") integratorPrinted = true
// Select integrator based on integratorType setting val y1: VectorD = integratorType match case IntegratorType.DOPRI5 => DormandPrince.integrateVV(odes, y0, dt) case IntegratorType.RK4 => RungeKutta2.rk4.integrateVV(odes, y0, dt) case IntegratorType.RK3 => RungeKutta2.rk3.integrateVV(odes, y0, dt) case IntegratorType.RK2 => RungeKutta2.rk2.integrateVV(odes, y0, dt) case IntegratorType.Heun => RungeKutta2.heun.integrateVV(odes, y0, dt) case IntegratorType.Euler => RungeKutta2.euler.integrateVV(odes, y0, dt) case IntegratorType.butcher => val a_idm = idmAccel(car.disp, car.velocity) val v_new_b = Vehicle.butcher( car.velocity, // v(t) a_idm, // a(t) car.o_acc, // a(t−τ) dt ) val x_new_b = Vehicle.butcher( car.disp, // x(t) — segment-local car.velocity, // v(t) car.o_velocity, // v(t−τ) dt ) VectorD(x_new_b, v_new_b) case IntegratorType.Ballistic => val a_idm = idmAccel(car.disp, car.velocity) val v_ball = car.velocity + a_idm * dt val x_ball = car.disp + car.velocity * dt + 0.5 * a_idm * dt * dt VectorD(x_ball, v_ball)
// ───────────────────────────────────────────────────────────────────────── // STEP 5: Extract and clamp results // ───────────────────────────────────────────────────────────────────────── val x_new = y1(0) // new segment-local position var v_new = y1(1) // new velocity
// Physical constraints: velocity must be non-negative and bounded if v_new < 0.0 then v_new = 0.0 // no backward motion if v_new > car.vmax then v_new = car.vmax // respect max speed
// Back-calculate acceleration for state storage val a = (v_new - v_old) / dt
// ───────────────────────────────────────────────────────────────────────── // STEP 6: Update vehicle state // ───────────────────────────────────────────────────────────────────────── car.o_acc = car.acc car.acc = a car.o_velocity = v_old car.velocity = v_new car.o_t_disp = car.t_disp // track old t_disp for stats
// ───────────────────────────────────────────────────────────────────────── // STEP 7: Segment-bounded + collision-free displacement update // ───────────────────────────────────────────────────────────────────────── // --- Collision-free position clamp (SUMO/VISSIM/Aimsun standard practice) --- // Even if IDM + integrator overshoots, clamp position to maintain gap ≥ s0 // behind leader. Uses x_leader from STEP 1 (cross-seg already resolved). // Breaks deadlock: overshoot → clamp to safe gap → IDM gives positive accel // next timestep when leader moves. No backward motion possible. var x_safe = x_new if car_ahead != null && x_leader - x_safe - len < s then // would violate min gap? x_safe = x_leader - len - s // park at min gap behind leader end if // val new_disp = max(0.0, if x_new <= length then x_new else length) // OLD: no collision-free clamp val new_disp = max(0.0, if x_safe <= length then x_safe else length)
car.t_disp += new_disp - car.disp // derive t_disp from clamped delta car.disp = new_disp
// DIAG: final state for ramp vehicles — detect overtaking if car.myRamp != null then val ldrD = if car_ahead != null then car_ahead.disp else -1.0 val gapF = if car_ahead != null then ldrD - new_disp - len else 999.0 val flag = if car_ahead != null && car_ahead.segId == car.segId && new_disp > ldrD then " *** OVERTOOK ***" else "" val mePath = if car.myPathway != null then car.myPathway.name else "null" val meRamp = if car.myRamp != null then car.myRamp.name else "null" val ldrPath = if car_ahead != null && car_ahead.myPathway != null then car_ahead.myPathway.name else "null" val ldrRamp = if car_ahead != null && car_ahead.myRamp != null then car_ahead.myRamp.name else "null" val ldrName = if car_ahead != null then car_ahead.displayLabel else "null" println(f"[STEP7] ${car.displayLabel}%-12s seg=${car.segId} path=$mePath ramp=$meRamp | ldr=$ldrName ldr.seg=${if car_ahead != null then car_ahead.segId else -1} ldr.path=$ldrPath ldr.ramp=$ldrRamp | disp=${new_disp}%.2f v=${car.velocity}%.2f ldrD=${ldrD}%.2f gap=${gapF}%.2f$flag") end if // DIAG end updateM
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the acceleration of the vehicle based on the Intelligent Driver Model * for a vehicle and its predecessor. Uses segment-local `disp` for gap computation. * NOTE: updateM uses the raw iDM directly; this is a convenience for external callers. * @param cn the current vehicle * @param cp the predecessor of the current vehicle * @param del the acceleration exponenent (defualts to 4) */ def iDM (cn: Vehicle, cp: Vehicle, del: Double = 4.0): Double = if cp == null then iDMFree (amax, cn.velocity, cn.vmax, del) else iDM (amax, abs(bmax), len, cn.vmax, cn.disp, cn.velocity, cp.disp, cp.velocity, T, s, del) end iDM
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the acceleration of the vehicle based on the Intelligent Driver Model. * @param an the max acceleration of drivers * @param bn the max deceleration of drivers (negative #) * @param sp the size of vehicles * @param Vn the desired velocity of driver n * @param xn the current position of driver n * @param vn the current velocity of driver n * @param xp the current position of the predecessor * @param vp the current velocity of the predecessor * @param T the safe min time headway * @param s0 the safe min distance headway * @param del the acceleration exponenent (defualts to 4) */ private def iDM (an: Double, bn: Double, sp: Double, Vn: Double, xn: Double, vn: Double, xp: Double, vp: Double, T: Double, s0: Double, del: Double): Double = val b = abs(bn) // use positive magnitude of deceleration val Δx = xp - xn - sp // front to rear gap val Δv = vn - vp // approach rate val ss = s0 + vn * T + (vn * Δv) / (2.0 * sqrt (an * b)) // desired gap an * (1.0 - (vn / Vn) ~^ del - (ss / Δx) ~^ 2.0) // acceleration end iDM
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the acceleration of the vehicle based on the Intelligent Driver Model * when there is no predecessor. * @param an the max acceleration of drivers * @param vn the current velocity of driver n * @param Vn the desired velocity of driver n * @param del the acceleration exponenent (defualts to 4) */ private def iDMFree (an: Double, vn: Double, Vn: Double, del: Double = 4.0): Double = an * (1.0 - (vn / Vn) ~^ del) end iDMFree
end IDMDynamics
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `MOBIL` object implements the MOBIL (Minimize Overall Braking Induced by * Lane changes) lane-change decision model (Treiber & Kesting, 2007). * * MOBIL uses IDM accelerations to evaluate whether a lane change is both * safe and beneficial. Two criteria must be satisfied: * * '''Safety criterion''' (hard constraint): * {{{ * ã_f ≥ -b_safe * }}} * where `ã_f` is the IDM acceleration of the new follower in the target lane * after the subject vehicle cuts in, and `b_safe` is the maximum acceptable * braking imposed on that follower. * * '''Incentive criterion''' (soft): * {{{ * ã_s − a_s + p · (ã_f − a_f) > Δa_th * }}} * where: * - `a_s` = subject's IDM acceleration in current lane (with current leader) * - `ã_s` = subject's IDM acceleration in target lane (with target leader) * - `a_f` = target follower's current IDM acceleration (before cut-in) * - `ã_f` = target follower's IDM acceleration after cut-in (subject becomes leader) * - `p` = politeness factor ∈ [0,1]. p=0 selfish, p=1 fully altruistic * - `Δa_th` = acceleration threshold to prevent frivolous lane changes * * @see Treiber, M. & Kesting, A. (2007). "Modeling lane-changing decisions with MOBIL." * Traffic and Granular Flow '07, pp. 211–221, Springer. * @see Treiber, M. & Kesting, A. (2013). Traffic Flow Dynamics. Springer, Ch. 11. */ object MOBIL:
import Vehicle.{amax, bmax, len, T, s, del, p_mobil, da_th, b_safe}
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Compute IDM acceleration for a hypothetical leader-follower pair. * Uses the raw IDM equation: a = amax * [1 - (v/v0)^δ - (s*(v,Δv)/Δx)^2] * @param follower the vehicle whose acceleration we compute * @param leader the vehicle ahead (null → free-flow) * @param segLen segment length (for cross-segment gap adjustment) * @return IDM acceleration (m/s²) */ private def idmAccelFor (follower: Vehicle, leader: Vehicle, segLen: Double): Double = if follower == null then return 0.0 val an = amax val bn = abs (bmax) if leader == null then // free-flow: a = amax * [1 - (v/v0)^δ] return an * (1.0 - (follower.velocity / follower.vmax) ~^ del) end if // bumper-to-bumper gap (segment-local) val xl = if leader.segId == follower.segId then leader.disp else segLen + leader.disp val gap = xl - follower.disp - len if gap <= 0.0 then return -bn // touching → full comfortable braking val dv = follower.velocity - leader.velocity // approach rate val ss = s + follower.velocity * T + (follower.velocity * dv) / (2.0 * sqrt (an * bn)) an * (1.0 - (follower.velocity / follower.vmax) ~^ del - (ss / gap) ~^ 2.0) end idmAccelFor
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Evaluate MOBIL for a single candidate target lane. * @param car the subject vehicle considering a lane change * @param route the Route containing all Pathways * @param seg the segment index the vehicle is currently in * @param curLane the vehicle's current lane index * @param tgtLane the candidate target lane index * @param segLen the segment length * @return the MOBIL incentive value (positive = beneficial), or -∞ if unsafe */ private def mobilIncentive (car: Vehicle, route: Route, seg: Int, curLane: Int, tgtLane: Int, segLen: Double): Double = // --- Target lane neighbors --- val tgtVT = route.pathway(tgtLane).seg(seg) if tgtVT == null then return Double.MinValue
// Leader in target lane: last vehicle in this segment's DLL (ahead of insertion point) val tgtLeader = tgtVT.getLast // Follower in target lane: first vehicle in this segment's DLL (behind insertion point) val tgtFollower = tgtVT.getFirst
// --- Current lane leader (same as findLeader would give) --- val curVT = route.pathway(curLane).seg(seg) val curLeader = if curVT != null then val ref = car.myPathNode if ref != null && ref.ahead != null then ref.ahead.elem else null else null
// --- 4 IDM acceleration computations --- // a_s: subject's acceleration in CURRENT lane (with current leader) val a_s = idmAccelFor (car, curLeader, segLen)
// ã_s: subject's acceleration in TARGET lane (with target leader) val a_s_tilde = idmAccelFor (car, tgtLeader, segLen)
// a_f: target follower's CURRENT acceleration (before cut-in) val a_f = idmAccelFor (tgtFollower, tgtLeader, segLen)
// ã_f: target follower's acceleration AFTER cut-in (subject becomes their new leader) val a_f_tilde = idmAccelFor (tgtFollower, car, segLen)
// --- Safety criterion: ã_f ≥ -b_safe --- if a_f_tilde < -b_safe then return Double.MinValue
// --- Incentive criterion: ã_s - a_s + p·(ã_f - a_f) > Δa_th --- val incentive = (a_s_tilde - a_s) + p_mobil * (a_f_tilde - a_f) incentive end mobilIncentive
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Check both adjacent lanes and return the best lane-change direction. * Called every timestep from VTransport.move() after updateV(). * @param car the vehicle evaluating lane change * @param route the parent Route * @param seg the current segment index * @param lane the current lane index * @return -1 (move to lane-1), 0 (stay), +1 (move to lane+1) */ def checkLaneChange (car: Vehicle, route: Route, seg: Int, lane: Int): Int = if car.myRamp != null then return 0 // ramp vehicles don't lane-change val segLen = route.pathway(lane).seg(seg).length
var bestDir = 0 var bestValue = da_th // must exceed threshold to trigger
// Check left (lane - 1) if lane - 1 >= 0 && route.laneExistsAt (lane - 1, seg) then val inc = mobilIncentive (car, route, seg, lane, lane - 1, segLen) if inc > bestValue then bestDir = -1 bestValue = inc end if end if
// Check right (lane + 1) if lane + 1 < route.maxLanes && route.laneExistsAt (lane + 1, seg) then val inc = mobilIncentive (car, route, seg, lane, lane + 1, segLen) if inc > bestValue then bestDir = +1 bestValue = inc end if end if
bestDir end checkLaneChange
end MOBIL

//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** @author John Miller, Casey Bowman * @version 2.0 * @date Tue Feb 4 14:56:34 EST 2020 * @see LICENSE (MIT style license file). * * @note Supports Physics Models for Motion of Vehicles */
package scalation package simulation package process
import scala.math.{abs, max, min, sqrt} import scalation.mathstat.* import scalation.dynamics.* import Vehicle.*
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Enumeration for selecting the ODE integrator type for IDM dynamics. * Used for experimental comparison of numerical integration methods. */ enum IntegratorType: case DOPRI5 // Dormand-Prince (4,5) adaptive - O(Δt⁵) - current default case RK4 // Classic Runge-Kutta 4th order - O(Δt⁴) case RK3 // SSPRK3 - O(Δt³) case RK2 // Modified Euler (Explicit Midpoint) - O(Δt²) case Heun // Heun's method (Explicit Trapezoidal) - O(Δt²) - Treiber recommended case Euler // Forward Euler - O(Δt¹) - what SUMO uses case butcher // Butcher 5th order - O(Δt⁵) case Ballistic // Kinematic equations - O(Δt²) end IntegratorType
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `Dynamics` trait supports physics models for the motion of vehicles, e.g., * car-following models. */ trait Dynamics:
private [process] var disp = 0.0 // set initial current displacement to 0 private [process] var t_disp = 0.0 // set initial total displacement to 0 private [process] var velocity = v0 // set initial velocity to v0 private [process] var o_t_disp = t_disp // set initial old total displacement t_disp private [process] var o_velocity = velocity // set initial old velocity to velocity private [process] var acc = 0.0 // set initial acceleration to 0 private [process] var o_acc = acc // set initial old acceleration acc
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Find the leader of the given vehicle using per-VTransport DLLs. * Step 1: within-segment leader (myPathNode.ahead). * Step 2: cross-boundary — next segment's DLL tail (mainline vehicles). * Step 3: ramp dual-leader — peek at mainline merge target (Treiber §11.3). * @param car the vehicle whose leader we need * @return the leader vehicle, or null if free-flow */ protected def findLeader (car: Vehicle): Vehicle = val onRamp = car.myRamp != null // DIAG
if car.myPathNode == null then return null // between DLLs → free-flow
// Step 1: within-segment leader (O(1) DLL lookup) val ref = car.myPathNode.ahead if ref != null then // if onRamp then // val ldr = ref.elem // val mePath = if car.myPathway != null then car.myPathway.name else "null" // val meRamp = if car.myRamp != null then car.myRamp.name else "null" // val ldrPath = if ldr.myPathway != null then ldr.myPathway.name else "null" // val ldrRamp = if ldr.myRamp != null then ldr.myRamp.name else "null" // println(f"[findLeader] ${car.displayLabel}%-12s STEP1 seg=${car.segId} path=$mePath ramp=$meRamp | ldr=${ldr.displayLabel} ldr.seg=${ldr.segId} ldr.path=$ldrPath ldr.ramp=$ldrRamp | me.disp=${car.disp}%.2f me.v=${car.velocity}%.2f ldr.disp=${ldr.disp}%.2f ldr.v=${ldr.velocity}%.2f") // end if // DIAG return ref.elem
// Step 2: cross-boundary — look at next segment's DLL tail val pw = car.myPathway if pw != null then val segs = pw.seg val nextIdx = car.segId + 1 if nextIdx < segs.length && segs(nextIdx) != null then return segs(nextIdx).getLast end if
// Step 3: ramp → peek at mainline merge segment (dual-leader) val ramp = car.myRamp if ramp != null && ramp.targetPathway != null && ramp.targetSegId >= 0 then val targetVT = ramp.targetPathway.seg(ramp.targetSegId) if targetVT != null then val ml = targetVT.getLast if ml != null then return ml end if end if
null end findLeader
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Update the values of the vehicle: velocity, displacement, lane according * to the car-following model being used. * @param motion the dynamics/physics determining the motion (e.g., car-following model) * @param car the vehivle to move
*/ def updateV (car: Vehicle, maxDisp: Double): Unit = // println (s"Dynamics.updateV: called $car") this match case GippsDynamics => { GippsDynamics.updateM (car, maxDisp) } case KraussDynamics => { KraussDynamics.updateM (car, maxDisp) } case _ => { IDMDynamics.updateM (car, maxDisp) } end updateV
end Dynamics
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `GippsDynamics` object provides equations for the Gipps car-following model. * @see https://en.wikipedia.org/wiki/Gipps%27_model */ object GippsDynamics extends Dynamics:
private val debug = debugf ("GippsDynamics", false) // debug function private[process] val easyW = new EasyWriter("simulation", "CalRoute101Model.txt")
/** Integrator type for position update (configurable, default Ballistic) */ var integratorType: IntegratorType = IntegratorType.Ballistic
/** Update the vehicle's velocity and position using Gipps' Model. * Position update method is configurable via integratorType. * * @param car the car/vehicle whose velocity and position is being updated */ /** Update the vehicle's velocity and position using Gipps' Model. * All gap and position computations use segment-local `disp` — consistent with * per-segment DLLs where the leader is always in the same or adjacent segment. * `t_disp` is updated as a derived statistic only. */ def updateM(car: Vehicle, length: Double): Unit = val car_ahead = findLeader (car) val dt = prop("rt")
// Step 1: compute next velocity using Gipps (discrete rule) val v = gipps(car, car_ahead, length) + EPSILON
// Step 2: update position in segment-local coordinates val x = integratorType match case IntegratorType.Ballistic => car.disp + car.velocity * dt case IntegratorType.butcher => butcher(car.disp, car.velocity, car.o_velocity, dt) case _ => car.disp + car.velocity * dt
// Step 3: commit velocity state AFTER position integration car.o_velocity = car.velocity car.velocity = v
// Step 4: segment-bounded + collision-free displacement update car.o_t_disp = car.t_disp
// --- Collision-free position clamp (SUMO/VISSIM/Aimsun standard practice) --- // Even if the velocity model overshoots, clamp position to maintain gap ≥ s0 // behind leader. Uses segment-local leader position (cross-seg already handled). var x_safe = x if car_ahead != null then val xl = if car_ahead.segId == car.segId then car_ahead.disp else length + car_ahead.disp if xl - x_safe - len < s then x_safe = xl - len - s // park at min gap behind leader end if // val new_disp = max(0.0, if x <= length then x else length) // OLD: no collision-free clamp val new_disp = max(0.0, if x_safe <= length then x_safe else length)
car.t_disp += new_disp - car.disp // derive t_disp from clamped delta car.disp = new_disp end updateM
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the velocity of the vehicle based on Gipps' model for a vehicle and its predecessor. * With per-segment DLLs, leader is always same-seg or next-seg. All positions are segment-local. * @param cn the current vehicle * @param cp the predecessor of the current vehicle (from findLeader — always same or next segment) */ def gipps (cn: Vehicle, cp: Vehicle, length: Double): Double = if cp == null then gipps (amax, bmax, len, cn.vmax, cn.disp, cn.velocity, cn.disp + 1000, cn.vmax, prop("rt")) else // Leader is in same segment or adjacent next segment val cp_r_disp = if cp.segId == cn.segId then cp.disp else length + cp.disp gipps (amax, bmax, len, cn.vmax, cn.disp, cn.velocity, cp_r_disp, cp.velocity, prop("rt")) end gipps //::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** Return the velocity of the vehicle based on Gipps' model. * * @param an the max acceleration of drivers * @param bn the max deceleration of drivers (may be negative) * @param sp the size of vehicles * @param Vn the desired velocity of driver n * @param xn the current position of driver n * @param vn the current velocity of driver n * @param xp the current position of the predecessor (ahead) * @param vp the current velocity of the predecessor * @param rt the reaction time of drivers */ private def gipps(an: Double, bn: Double, sp: Double, Vn: Double, xn: Double, vn: Double, xp: Double, vp: Double, rt: Double): Double = // --------------- Parameters --------------------- val b = abs(bn) // use positive magnitude of deceleration val b_hat = b * 1.8 // expected braking ability of leader (default 0.8×b) b_hat >= b
// --------------- Free-flow branch --------------- // v_free = v_n + 2.5 * a_n * τ * (1 - v_n/V_n) * sqrt(0.025 + v_n/V_n) val free = vn + (2.5 * an * rt * (1.0 - vn / Vn)) * sqrt(0.025 + vn / Vn)
// --------------- Congested (safety) branch ------- // v_cong = b * τ + sqrt(b^2 * τ^2 - b[2(gap) - v_nτ - v_p^2/b̂]) val gap = xp - sp - xn // effective front-to-front gap val phi = 2.0 * gap - (vn * rt) - (vp * vp / b_hat) // safety term inside brackets
// When phi >= 0, spacing is large enough that braking constraint is inactive. // In that case, use free-flow velocity directly (skip sqrt computation). if phi >= 0.0 then return free
// Otherwise, apply the congested/safety branch. val inner_exp = (b * b * rt * rt) - b * phi // value inside sqrt val cong = (b * rt) + sqrt(max(0.0, inner_exp)) // braking (congested) velocity min(free, cong) end gipps
end GippsDynamics
object KraussDynamics extends Dynamics:
private val debug = debugf("KraussDynamics", false)
/** Krauss stochastic imperfection magnitude (m/s) * Must be small relative to amax*tau to allow net acceleration */ private val sigma = 0.2
/** Uniform random variate for stochastic noise */ private val noiseRV = scalation.random.Uniform(0.0, sigma)
/** Integrator type for position update (configurable, default Ballistic) */ var integratorType: IntegratorType = IntegratorType.Ballistic
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Update the vehicle's velocity and position using Krauss Model. * All gap and position computations use segment-local `disp` — consistent with * per-segment DLLs where the leader is always in the same or adjacent segment. * `t_disp` is updated as a derived statistic only. * @param car the vehicle to update * @param length the segment length */ def updateM(car: Vehicle, length: Double): Unit = val car_ahead = findLeader (car) val dt = prop("rt")
// Compute leader position and velocity (segment-local) val (xp, vp): (Double, Double) = if car_ahead == null then (car.disp + 1000.0, car.vmax) // phantom leader (free flow) else if car_ahead.segId == car.segId then (car_ahead.disp, car_ahead.velocity) else (length + car_ahead.disp, car_ahead.velocity)
// Step 1: Compute next velocity using Krauss val v_new = krauss( amax, bmax, len, car.vmax, car.disp, car.velocity, xp, vp, dt, s )
// Step 2: Position update in segment-local coordinates val x_new = integratorType match case IntegratorType.Ballistic => car.disp + car.velocity * dt case IntegratorType.butcher => butcher(car.disp, car.velocity, car.o_velocity, dt) case _ => car.disp + car.velocity * dt
// Step 3: Commit velocity state AFTER position update car.o_velocity = car.velocity car.velocity = v_new
// Step 4: Segment-bounded + collision-free displacement update car.o_t_disp = car.t_disp
// --- Collision-free position clamp (SUMO/VISSIM/Aimsun standard practice) --- var x_safe = x_new if car_ahead != null && xp - x_safe - len < s then x_safe = xp - len - s // park at min gap behind leader end if // val new_disp = max(0.0, if x_new <= length then x_new else length) // OLD: no collision-free clamp val new_disp = max(0.0, if x_safe <= length then x_safe else length)
car.t_disp += new_disp - car.disp // derive t_disp from clamped delta car.disp = new_disp end updateM
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Compute next velocity using Krauss car-following model. * Safety is enforced BEFORE stochastic noise is applied. * * @param an max acceleration * @param bn max deceleration (negative) * @param sp vehicle length * @param Vn desired speed * @param xn follower position * @param vn follower velocity * @param xp leader position * @param vp leader velocity * @param rt reaction time (timestep) * @param s0 minimum spacing */ private def krauss(an: Double, bn: Double, sp: Double, Vn: Double, xn: Double, vn: Double, xp: Double, vp: Double, rt: Double, s0: Double): Double = val b = abs(bn)
// Netto gap (front-to-rear) val gap = xp - xn - sp if gap <= 0.0 then return 0.0 // collision avoidance
// Krauss safe speed: v_safe = sqrt(v_leader^2 + 2*b*(gap - s0)) val inner = vp * vp + 2.0 * b * (gap - s0) val v_safe = sqrt(max(0.0, inner))
// Acceleration constraint: v_cap = v + a_max * tau val v_cap = vn + an * rt
// Desired speed constraint val v_des = Vn
// Deterministic candidate (minimum of all constraints) val v_star = min(v_des, min(v_safe, v_cap))
// Stochastic imperfection applied AFTER safety val eps = noiseRV.gen max(0.0, v_star - eps) end krauss
end KraussDynamics
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `IDMDynamics` object provides equations for the Intelligent Driver Model (IDM) * car-following model. * @see https://en.wikipedia.org/wiki/Intelligent_driver_model */
object IDMDynamics extends Dynamics:
private val debug = debugf ("IDMDynamics", true) // debug function
private val FREERANGE = 150.0
/** Configurable integrator type for ODE solving - default Ballistic */ var integratorType: IntegratorType = IntegratorType.Ballistic
/** Flag to print integrator type only once per simulation run */ private var integratorPrinted: Boolean = false
/** Reset the print flag - call this before each new simulation */ def resetIntegratorPrintFlag(): Unit = integratorPrinted = false
/** * Update the vehicle's velocity and position using the Intelligent Driver Model. * All gap and position computations use segment-local `disp` — consistent with * per-segment DLLs where the leader is always in the same or adjacent segment. * `t_disp` is updated as a derived statistic only. * @param car the vehicle to update * @param length the segment length */ def updateM(car: Vehicle, length: Double): Unit = val car_ahead = findLeader (car) val dt = rt
// ───────────────────────────────────────────────────────────────────────── // STEP 1: Snapshot leader state in SEGMENT-LOCAL coordinates. // With per-segment DLLs, findLeader returns same-seg or next-seg only. // ───────────────────────────────────────────────────────────────────────── val (x_leader, v_leader): (Double, Double) = if car_ahead == null then (car.disp + 1000.0, car.velocity) // no leader: free-flow else val xl = if car_ahead.segId == car.segId then car_ahead.disp else length + car_ahead.disp // next segment // Fix 2: skip FREERANGE for ramp cars — ramp must always track the // mainline dual-leader to decelerate before merge (Treiber §11.3). if xl - car.disp > FREERANGE && car.myRamp == null then (car.disp + 1000.0, car.velocity) // leader far ahead: free-flow else (xl, car_ahead.velocity) // real leader
// ───────────────────────────────────────────────────────────────────────── // STEP 2: Save old state for history tracking // ───────────────────────────────────────────────────────────────────────── val v_old = car.velocity val x_old = car.disp // segment-local
/** * @param x_n Current position of driver n (segment-local, from ODE solver trial values) * @param v_n Current velocity of driver n (from ODE solver trial values) * @return IDM acceleration clamped to physical bounds [-b_emergency, amax] */ def idmAccel(x_n: Double, v_n: Double): Double = val b = abs(bmax) // comfortable decel for IDM s* formula
var a = iDM(amax, b, len, car.vmax, x_n, v_n, x_leader, v_leader, T, s, del)
val a_raw = a // save before clamp if a.isNaN || a.isInfinity then a = 0.0 // if a < -b then a = -b // OLD: comfortable clamp (bmax = 2.0) val a_floor = max(b_emergency, -v_n / dt) // SUMO-style: can't decel past stopping if a < a_floor then a = a_floor // allows b_emergency at high v, gentler at low v if a > amax then a = amax a end idmAccel
// Array of derivative functions: [dx/dt, dv/dt] val odes: Array[DerivativeV] = Array( (t: Double, y: VectorD) => y(1), // dx/dt = v (velocity) (t: Double, y: VectorD) => idmAccel(y(0), y(1)) // dv/dt = a (IDM acceleration) )
// ───────────────────────────────────────────────────────────────────────── // STEP 4: Solve the coupled system in segment-local coordinates // ───────────────────────────────────────────────────────────────────────── val y0 = VectorD(car.disp, car.velocity) // segment-local initial state
// Print integrator type ONCE per simulation (from inside updateM, not from caller) if !integratorPrinted then println(s"[IDMDynamics.updateM] INTEGRATOR IN USE: $integratorType") integratorPrinted = true
// Select integrator based on integratorType setting val y1: VectorD = integratorType match case IntegratorType.DOPRI5 => DormandPrince.integrateVV(odes, y0, dt) case IntegratorType.RK4 => RungeKutta2.rk4.integrateVV(odes, y0, dt) case IntegratorType.RK3 => RungeKutta2.rk3.integrateVV(odes, y0, dt) case IntegratorType.RK2 => RungeKutta2.rk2.integrateVV(odes, y0, dt) case IntegratorType.Heun => RungeKutta2.heun.integrateVV(odes, y0, dt) case IntegratorType.Euler => RungeKutta2.euler.integrateVV(odes, y0, dt) case IntegratorType.butcher => val a_idm = idmAccel(car.disp, car.velocity) val v_new_b = Vehicle.butcher( car.velocity, // v(t) a_idm, // a(t) car.o_acc, // a(t−τ) dt ) val x_new_b = Vehicle.butcher( car.disp, // x(t) — segment-local car.velocity, // v(t) car.o_velocity, // v(t−τ) dt ) VectorD(x_new_b, v_new_b) case IntegratorType.Ballistic => val a_idm = idmAccel(car.disp, car.velocity) val v_ball = car.velocity + a_idm * dt val x_ball = car.disp + car.velocity * dt + 0.5 * a_idm * dt * dt VectorD(x_ball, v_ball)
// ───────────────────────────────────────────────────────────────────────── // STEP 5: Extract and clamp results // ───────────────────────────────────────────────────────────────────────── val x_new = y1(0) // new segment-local position var v_new = y1(1) // new velocity
// Physical constraints: velocity must be non-negative and bounded if v_new < 0.0 then v_new = 0.0 // no backward motion if v_new > car.vmax then v_new = car.vmax // respect max speed
// Back-calculate acceleration for state storage val a = (v_new - v_old) / dt
// ───────────────────────────────────────────────────────────────────────── // STEP 6: Update vehicle state // ───────────────────────────────────────────────────────────────────────── car.o_acc = car.acc car.acc = a car.o_velocity = v_old car.velocity = v_new car.o_t_disp = car.t_disp // track old t_disp for stats
// ───────────────────────────────────────────────────────────────────────── // STEP 7: Segment-bounded + collision-free displacement update // ───────────────────────────────────────────────────────────────────────── // --- Collision-free position clamp (SUMO/VISSIM/Aimsun standard practice) --- // Even if IDM + integrator overshoots, clamp position to maintain gap ≥ s0 // behind leader. Uses x_leader from STEP 1 (cross-seg already resolved). // Breaks deadlock: overshoot → clamp to safe gap → IDM gives positive accel // next timestep when leader moves. No backward motion possible. var x_safe = x_new if car_ahead != null && x_leader - x_safe - len < s then // would violate min gap? x_safe = x_leader - len - s // park at min gap behind leader end if // val new_disp = max(0.0, if x_new <= length then x_new else length) // OLD: no collision-free clamp val new_disp = max(0.0, if x_safe <= length then x_safe else length)
car.t_disp += new_disp - car.disp // derive t_disp from clamped delta car.disp = new_disp
// DIAG: final state for ramp vehicles — detect overtaking // (disabled — high-volume console output starves the animator's EDT) // if car.myRamp != null then // val ldrD = if car_ahead != null then car_ahead.disp else -1.0 // val gapF = if car_ahead != null then ldrD - new_disp - len else 999.0 // val flag = if car_ahead != null && car_ahead.segId == car.segId && new_disp > ldrD then " *** OVERTOOK ***" else "" // val mePath = if car.myPathway != null then car.myPathway.name else "null" // val meRamp = if car.myRamp != null then car.myRamp.name else "null" // val ldrPath = if car_ahead != null && car_ahead.myPathway != null then car_ahead.myPathway.name else "null" // val ldrRamp = if car_ahead != null && car_ahead.myRamp != null then car_ahead.myRamp.name else "null" // val ldrName = if car_ahead != null then car_ahead.displayLabel else "null" // println(f"[STEP7] ${car.displayLabel}%-12s seg=${car.segId} path=$mePath ramp=$meRamp | ldr=$ldrName ldr.seg=${if car_ahead != null then car_ahead.segId else -1} ldr.path=$ldrPath ldr.ramp=$ldrRamp | disp=${new_disp}%.2f v=${car.velocity}%.2f ldrD=${ldrD}%.2f gap=${gapF}%.2f$flag") // end if // DIAG end updateM
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the acceleration of the vehicle based on the Intelligent Driver Model * for a vehicle and its predecessor. Uses segment-local `disp` for gap computation. * NOTE: updateM uses the raw iDM directly; this is a convenience for external callers. * @param cn the current vehicle * @param cp the predecessor of the current vehicle * @param del the acceleration exponenent (defualts to 4) */ def iDM (cn: Vehicle, cp: Vehicle, del: Double = 4.0): Double = if cp == null then iDMFree (amax, cn.velocity, cn.vmax, del) else iDM (amax, abs(bmax), len, cn.vmax, cn.disp, cn.velocity, cp.disp, cp.velocity, T, s, del) end iDM
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the acceleration of the vehicle based on the Intelligent Driver Model. * @param an the max acceleration of drivers * @param bn the max deceleration of drivers (negative #) * @param sp the size of vehicles * @param Vn the desired velocity of driver n * @param xn the current position of driver n * @param vn the current velocity of driver n * @param xp the current position of the predecessor * @param vp the current velocity of the predecessor * @param T the safe min time headway * @param s0 the safe min distance headway * @param del the acceleration exponenent (defualts to 4) */ private def iDM (an: Double, bn: Double, sp: Double, Vn: Double, xn: Double, vn: Double, xp: Double, vp: Double, T: Double, s0: Double, del: Double): Double = val b = abs(bn) // use positive magnitude of deceleration val Δx = xp - xn - sp // front to rear gap val Δv = vn - vp // approach rate val ss = s0 + vn * T + (vn * Δv) / (2.0 * sqrt (an * b)) // desired gap an * (1.0 - (vn / Vn) ~^ del - (ss / Δx) ~^ 2.0) // acceleration end iDM
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the acceleration of the vehicle based on the Intelligent Driver Model * when there is no predecessor. * @param an the max acceleration of drivers * @param vn the current velocity of driver n * @param Vn the desired velocity of driver n * @param del the acceleration exponenent (defualts to 4) */ private def iDMFree (an: Double, vn: Double, Vn: Double, del: Double = 4.0): Double = an * (1.0 - (vn / Vn) ~^ del) end iDMFree
end IDMDynamics
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `MOBIL` object implements the MOBIL (Minimize Overall Braking Induced by * Lane changes) lane-change decision model (Treiber & Kesting, 2007). * * MOBIL uses IDM accelerations to evaluate whether a lane change is both * safe and beneficial. Two criteria must be satisfied: * * '''Safety criterion''' (hard constraint): * {{{ * ã_f ≥ -b_safe * }}} * where `ã_f` is the IDM acceleration of the new follower in the target lane * after the subject vehicle cuts in, and `b_safe` is the maximum acceptable * braking imposed on that follower. * * '''Incentive criterion''' (soft): * {{{ * ã_s − a_s + p · (ã_f − a_f) > Δa_th * }}} * where: * - `a_s` = subject's IDM acceleration in current lane (with current leader) * - `ã_s` = subject's IDM acceleration in target lane (with target leader) * - `a_f` = target follower's current IDM acceleration (before cut-in) * - `ã_f` = target follower's IDM acceleration after cut-in (subject becomes leader) * - `p` = politeness factor ∈ [0,1]. p=0 selfish, p=1 fully altruistic * - `Δa_th` = acceleration threshold to prevent frivolous lane changes * * @see Treiber, M. & Kesting, A. (2007). "Modeling lane-changing decisions with MOBIL." * Traffic and Granular Flow '07, pp. 211–221, Springer. * @see Treiber, M. & Kesting, A. (2013). Traffic Flow Dynamics. Springer, Ch. 11. */ object MOBIL:
import Vehicle.{amax, bmax, len, T, s, del, p_mobil, da_th, b_safe}
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Compute IDM acceleration for a hypothetical leader-follower pair. * Uses the raw IDM equation: a = amax * [1 - (v/v0)^δ - (s*(v,Δv)/Δx)^2] * @param follower the vehicle whose acceleration we compute * @param leader the vehicle ahead (null → free-flow) * @param segLen segment length (for cross-segment gap adjustment) * @return IDM acceleration (m/s²) */ private def idmAccelFor (follower: Vehicle, leader: Vehicle, segLen: Double): Double = if follower == null then return 0.0 val an = amax val bn = abs (bmax) if leader == null then // free-flow: a = amax * [1 - (v/v0)^δ] return an * (1.0 - (follower.velocity / follower.vmax) ~^ del) end if // bumper-to-bumper gap (segment-local) val xl = if leader.segId == follower.segId then leader.disp else segLen + leader.disp val gap = xl - follower.disp - len if gap <= 0.0 then return -bn // touching → full comfortable braking val dv = follower.velocity - leader.velocity // approach rate val ss = s + follower.velocity * T + (follower.velocity * dv) / (2.0 * sqrt (an * bn)) an * (1.0 - (follower.velocity / follower.vmax) ~^ del - (ss / gap) ~^ 2.0) end idmAccelFor
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Evaluate MOBIL for a single candidate target lane. * @param car the subject vehicle considering a lane change * @param route the Route containing all Pathways * @param seg the segment index the vehicle is currently in * @param curLane the vehicle's current lane index * @param tgtLane the candidate target lane index * @param segLen the segment length * @return the MOBIL incentive value (positive = beneficial), or -∞ if unsafe */ private def mobilIncentive (car: Vehicle, route: Route, seg: Int, curLane: Int, tgtLane: Int, segLen: Double): Double = // --- Target lane neighbors --- val tgtVT = route.pathway(tgtLane).seg(seg) if tgtVT == null then return Double.MinValue
// Leader in target lane: last vehicle in this segment's DLL (ahead of insertion point) val tgtLeader = tgtVT.getLast // Follower in target lane: first vehicle in this segment's DLL (behind insertion point) val tgtFollower = tgtVT.getFirst
// --- Current lane leader (same as findLeader would give) --- val curVT = route.pathway(curLane).seg(seg) val curLeader = if curVT != null then val ref = car.myPathNode if ref != null && ref.ahead != null then ref.ahead.elem else null else null
// --- 4 IDM acceleration computations --- // a_s: subject's acceleration in CURRENT lane (with current leader) val a_s = idmAccelFor (car, curLeader, segLen)
// ã_s: subject's acceleration in TARGET lane (with target leader) val a_s_tilde = idmAccelFor (car, tgtLeader, segLen)
// a_f: target follower's CURRENT acceleration (before cut-in) val a_f = idmAccelFor (tgtFollower, tgtLeader, segLen)
// ã_f: target follower's acceleration AFTER cut-in (subject becomes their new leader) val a_f_tilde = idmAccelFor (tgtFollower, car, segLen)
// --- Safety criterion: ã_f ≥ -b_safe --- if a_f_tilde < -b_safe then return Double.MinValue
// --- Incentive criterion: ã_s - a_s + p·(ã_f - a_f) > Δa_th --- val incentive = (a_s_tilde - a_s) + p_mobil * (a_f_tilde - a_f) incentive end mobilIncentive
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Check both adjacent lanes and return the best lane-change direction. * Called every timestep from VTransport.move() after updateV(). * @param car the vehicle evaluating lane change * @param route the parent Route * @param seg the current segment index * @param lane the current lane index * @return -1 (move to lane-1), 0 (stay), +1 (move to lane+1) */ def checkLaneChange (car: Vehicle, route: Route, seg: Int, lane: Int): Int = if car.myRamp != null then return 0 // ramp vehicles don't lane-change val segLen = route.pathway(lane).seg(seg).length
var bestDir = 0 var bestValue = da_th // must exceed threshold to trigger
// Check left (lane - 1) if lane - 1 >= 0 && route.laneExistsAt (lane - 1, seg) then val inc = mobilIncentive (car, route, seg, lane, lane - 1, segLen) if inc > bestValue then bestDir = -1 bestValue = inc end if end if
// Check right (lane + 1) if lane + 1 < route.maxLanes && route.laneExistsAt (lane + 1, seg) then val inc = mobilIncentive (car, route, seg, lane, lane + 1, segLen) if inc > bestValue then bestDir = +1 bestValue = inc end if end if
bestDir end checkLaneChange
end MOBIL

//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** @author John Miller * @version 2.0 * @date Sat Jan 25 19:44:16 EST 2014 * @see LICENSE (MIT style license file). * * @note Route for Modeling Multi-Stage, Multi-Lane Pathway */
package scalation package simulation package process
import scalation.mathstat.VectorD import scala.math.{min, abs} import scalation.random.Discrete //import scalation.random.Variate
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Off-ramp specification — declares where an off-ramp diverges and what * fraction of mainline vehicles should exit there. * * @param rampId identifier matching the off-ramp Ramp/Sink name (e.g. "I210_FR1") * @param divergeSeg segment index where the off-ramp branches from the mainline * @param exitLane lane the vehicle must reach to take the ramp (usually 0 or nLanes-1) * @param turnoffPct fraction of mainline vehicles that exit here (0.0–1.0) */ case class OffRampSpec (rampId: String, divergeSeg: Int, exitLane: Int, turnoffPct: Double)
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Companion for `OffRampSpec` — dice-roll assignment at spawn time. */ object OffRampSpec:
/** Build a ScalaTion Discrete variate from off-ramp specs. * Outcomes: 0 .. specs.length-1 = exit at that ramp, specs.length = through traffic. * * Example: 2 off-ramps at 15% and 10% turnoff → * dist = VectorD(0.15, 0.10, 0.75) // index 0 = ramp 1, index 1 = ramp 2, index 2 = through traffic * Discrete.gen rolls → 0 (15%), 1 (10%), or 2 (75%) * * @param specs the off-ramp specs for this route (ordered by position along corridor) * @return a Discrete variate (call .gen to roll) */ def buildExitDist (specs: List [OffRampSpec]): Discrete = val n = specs.length val dist = new VectorD (n + 1) var s = 0.0 // explicit running sum — no dependency on dist(n) being 0 cfor (0, n) { i => dist(i) = specs(i).turnoffPct s += dist(i) } dist(n) = (1.0 - s).max (0.0) // through traffic = remainder Discrete (dist) end buildExitDist
/** Roll the Discrete variate and return the rampId (or null = through traffic). * * Example: specs = List(OffRampSpec("I210_FR1", ...), OffRampSpec("I210_FR2", ...)) * exitRV.gen → 0.0 → return "I210_FR1" (exit at first off-ramp) * exitRV.gen → 1.0 → return "I210_FR2" (exit at second off-ramp) * exitRV.gen → 2.0 → return null (through traffic — drives to Sink) * * @param specs the off-ramp specs (same list used to build the variate) * @param exitRV the Discrete variate from buildExitDist * @return rampId to exit at, or null if through traffic */ def assignExit (specs: List [OffRampSpec], exitRV: Discrete): String = if specs.isEmpty then null else val idx = exitRV.gen.toInt if idx < specs.length then specs(idx).rampId else null // through traffic end assignExit
end OffRampSpec
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `Route` class defines a multi-lane route composed of multiple `Pathway`s * running in parallel. Each `Pathway` is a single-lane road that shares the same * `from` (entry), `to` (exit), and intermediate `junc` (junction) components. * * @param name the name of the route * @param numLanes the number of parallel lanes (Pathways) * @param junc the shared junction components between segments * @param from the shared starting component (e.g., VSource) * @param to the shared ending component (e.g., Sink) * @param motion the dynamics model used for movement * @param isSpeed whether speed or trip-time is used * @param bend curvature of the lanes */ class Route (name: String, numLanes: Int, junc: Array[Junction], from: Component, to: Component, motion: Dynamics, isSpeed: Boolean = false, bend: Double = 0.0, val lanesPerSeg: Array[Int] = null, var offRampSpecs: List[OffRampSpec] = Nil) extends Component ():
private val debug = debugf("Route", true) // debug function
/** Number of segments in this route. */ private val nSegments: Int = junc.length + 1 // from + junc.length intermediates + to = junc.length+1 points → junc.length+1-1 segs ... actually segments = intermediateJunc.length + 1
/** Per-segment lane counts. If lanesPerSeg is null (uniform), fill with numLanes. */ private val _lanesPerSeg: Array[Int] = if lanesPerSeg != null then lanesPerSeg else Array.fill(junc.length + 1)(numLanes) // junc = intermediate junctions → nSegments = junc.length + 1
/** Maximum lane count across all segments. */ val maxLanes: Int = if _lanesPerSeg.nonEmpty then _lanesPerSeg.max else numLanes
/** Query: how many lanes exist at segment `seg`. */ def lanesAt (seg: Int): Int = _lanesPerSeg(seg)
/** Query: does lane `lane` exist at segment `seg`? */ def laneExistsAt (lane: Int, seg: Int): Boolean = lane < _lanesPerSeg(seg)
val pathway: Array[Pathway] = Array.ofDim[Pathway](numLanes) // create array of parallel Pathways private val GAP = 50.0 // pixel between lanes
for i <- pathway.indices do val physicalLane = numLanes - 1 - i // Reverse: i=0 → lane 4 (rightmost), i=4 → lane 0 (leftmost) val shift = calcShift2 * ((physicalLane - (numLanes - 1) / 2.0) * GAP) pathway(i) = new Pathway(s"${name}L$i", junc, from, to, motion, isSpeed, bend, laneShift = shift, laneIndex = i, lanesPerSeg = _lanesPerSeg) pathway(i).parentRoute = this // back-reference for MOBIL lane-change subpart += pathway(i) end for
initComponent(name, from.at) // using from.at for the initComponent
// Cumulative length up to (but not including) each segment // segmentOffsets(0) = 0 // segmentOffsets(1) = seg(0).length // segmentOffsets(2) = seg(0).length + seg(1).length // etc. val segmentOffsets: Array[Double] = val n = pathway(0).seg.length // number of segments (same for all Pathways) val offsets = new Array[Double](n + 1) // array to hold offsets offsets(0) = 0.0 // starting offset is 0.0 for i <- 0 until n do // Find a non-null VTransport at this segment index (any lane will do — same geometry) val vt = pathway.map(_.seg(i)).find(_ != null).orNull offsets(i + 1) = offsets(i) + (if vt != null then vt.length else 0.0) end for offsets end segmentOffsets
// O(1) helper: convert (segId, disp) → cumulative position @inline def toCumulative(segId: Int, disp: Double): Double = segmentOffsets(segId) + disp end toCumulative
// ----------------------------------------------------------------------------
/** Attempt to change lanes for a vehicle that is on segment `seg` of lane `l1` * and wants to move to adjacent lane `l2`. * * @return true if the lane-change succeeds; false otherwise */ def changeLane(l1: Int, l2: Int, actor: Vehicle, seg: Int): Boolean =
var success = abs(l1 - l2) == 1 if !success then return success
// Check if target lane exists at this segment (variable lane support) if !laneExistsAt(l2, seg) then return false // Check if source lane exists at this segment (car can't be here if lane is null) if !laneExistsAt(l1, seg) then return false
val fromPath = pathway(l1) // current Pathway (lane l1) val toPath = pathway(l2) // target Pathway (lane l2)
// Check if either lane doesn't exist if fromPath == null || toPath == null then return false
val safeDisp = fromPath.seg(seg).safetydist
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: // vehicles to check in target lane val vBehind = toPath.seg(seg).getFirst // car behind in same seg val vAhead = if seg + 1 < toPath.seg.length && toPath.seg(seg + 1) != null then toPath.seg(seg + 1).getLast else null
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: // compute bumper-to-bumper gaps val gapBehind = if vBehind != null then actor.disp - vBehind.disp else safeDisp
val nextSeg = min(seg + 1, toPath.seg.length - 1)
val gapAhead = if vAhead != null then toPath.seg(nextSeg).length - vAhead.disp - Vehicle.len else safeDisp
val gap = min(gapBehind, gapAhead) //:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: // feasibility check success &&= gapBehind >= safeDisp && gapAhead >= safeDisp
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: // --- perform the lane change -------------------------------------------- if success then fromPath.removeFromAlist(actor, seg) // detach from old lane at this segment assert(actor.myPathNode == null, s"Vehicle $this not cleared before lane-change insertion!")
actor.laneID = l2 // update laneID actor.pathInfo = toPath.seg(seg).name // update pathInfo toPath.addToAlist(actor, vAhead, seg) // insert before vAhead in target lane at this segment end if
success end changeLane
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Merge a ramp vehicle into the mainline at the given lane and segment. * Remove from ramp, look who's ahead in the merge segment, insert behind them. * IDM in Dynamics handles car-following after insertion. * * @param lane the target mainline lane * @param seg the merge segment index * @param car the merging vehicle (just finished driving the ramp) * @param fromRamp the ramp the vehicle came from (null if direct) */ def mergeFromRamp (lane: Int, seg: Int, car: Vehicle, fromRamp: Ramp = null): Unit = val effectiveLane = if laneExistsAt (lane, seg) then lane else lanesAt (seg) - 1 if fromRamp != null then fromRamp.removeFromAlist (car) val vAhead = pathway(effectiveLane).seg(seg).getLast pathway(effectiveLane).addToAlist (car, vAhead, seg) end mergeFromRamp
//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** * Lane-drop forced merge. A lane dies (e.g. 5 lanes → 4 lanes). * Every vehicle in the dying lane moves into the adjacent surviving lane. * If there's a car ahead in that lane, slot behind it. That's it. * * This method does the FULL job: remove from dead lane, insert into * surviving lane. Caller just uses the returned laneID and moves on. * * @param l1 the vehicle's current lane (dead at this segment) * @param availLanes the lanes that exist at this segment (e.g. 0 until 4) * @param car the vehicle being merged * @param seg the segment index where the lane drop occurs * @return the new lane index */ def forceMerge(l1: Int, availLanes: Range, car: Vehicle, seg: Int): Int = val target = availLanes.last // adjacent surviving lane
// 1. Remove from dead lane (if still attached) if car.myPathNode != null && pathway(l1) != null && pathway(l1).seg(seg) != null then pathway(l1).removeFromAlist(car, seg) end if
// 2. Insert into surviving lane — slot behind whoever is ahead val ahead = pathway(target).seg(seg).getLast car.laneID = target pathway(target).addToAlist(car, ahead, seg)
println(f"[forceMerge] ${car.displayLabel}%-12s lane $l1 → $target at seg $seg (lane drop)") target end forceMerge
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Check whether a vehicle needs to steer toward its assigned off-ramp. * If the vehicle is within the mandatory lane-change zone, override MOBIL * and force one lane change toward the exit lane per call. * * Called every timestep from VTransport.move() — only when car.exitRampId != null. * * @param car the vehicle with a non-null exitRampId * @param seg the vehicle's current segment index * @param clock current simulation time (for cooldown) */ def exitCheckAndSteer (car: Vehicle, seg: Int, clock: Double): Unit = // Find the matching off-ramp spec val spec = offRampSpecs.find (_.rampId == car.exitRampId).orNull if spec == null then return // no matching spec (shouldn't happen)
// Distance to diverge point (in segments, converted to meters) val segsRemaining = spec.divergeSeg - seg if segsRemaining <= 0 then return // already past it — missed exit handled in act()
val distToExit = { var d = 0.0 val lane0 = pathway.find (_ != null).get // any lane for geometry for s <- seg until min (spec.divergeSeg, lane0.seg.length) do if lane0.seg(s) != null then d += lane0.seg(s).length d }
// Already in exit lane? if car.laneID == spec.exitLane then return // nothing to do — stay put
// Determine urgency zone val cooldown = if distToExit < 200.0 then 1.0 // aggressive: 1s cooldown else if distToExit < 500.0 then 2.0 // mandatory: 2s cooldown else return // > 500m: let MOBIL handle it
if (clock - car.lastLaneChangeTime) < cooldown then return // respect cooldown
// One step toward exit lane val dir = if spec.exitLane > car.laneID then 1 else -1 val ok = changeLane (car.laneID, car.laneID + dir, car, seg) if ok then car.lastLaneChangeTime = clock end exitCheckAndSteer
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Get the first vehicle in the specified lane. * @param i the index of the pathway/lane */ def getFirst(i: Int): Vehicle = if pathway(i) != null then pathway(i).getFirst else null
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Get the last vehicle in the specified lane. * @param i the index of the lane */ def getLast(i: Int): Vehicle = if pathway(i) != null then pathway(i).getLast else null
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Get the Pathway at index i. * @param i the lane index */ def path(i: Int): Pathway = pathway(i)
//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** Return the shared junctions. */ def junctions: Array[Junction] = junc
/** Return the number of segments (same for all Pathways). */ def segments: Int = pathway(0).seg.length
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** All junction points in order: from +: junc :+ to. * points(seg) is the upstream junction of segment `seg`. */ private val _points: Array [Component] = (from +: junc.toIndexedSeq :+ to).toArray
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Perpendicular unit vector pointing outward from road centerline * toward the ramp side (opposite from lane 0 / rightmost lane). */ val perpVec: (Double, Double) = val v = calcShift2 (-v(0), -v(1)) // negate: away from lane 0
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the screen (x, y) at the outermost lane edge of segment `seg`. * Adapts to variable lane counts: more lanes → further from centerline. * Points toward the ramp side (away from lane 0). * @param seg segment index (0 .. nSegments-1) */ def rampAttachPoint (seg: Int): (Double, Double) = val pt = _points(seg) // junction at segment boundary val nHere = lanesAt(seg) val offset = (nHere - numLanes / 2.0 - 0.5) * GAP // slightly inside lane edge for visual snugness (pt.at(0) + perpVec._1 * offset, pt.at(1) + perpVec._2 * offset) end rampAttachPoint
//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** Calculate the amount of shift in the x and y directions. */ private def calcShift2: VectorD = val dx = to.at(0) - from.at(0) val dy = to.at(1) - from.at(1) val hyp = math.hypot(dx, dy) VectorD(dy / hyp, -dx / hyp) end calcShift2
/** Calculate the amount of shift in the x and y directions. */ private def calcShift: VectorD = val xdist = from.at(0) - to.at(0) val ydist = from.at(1) - to.at(1) val hyp = math.hypot(xdist, ydist) VectorD((ydist / hyp) * GAP, -(xdist / hyp) * GAP) end calcShift
//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** Display the Route by displaying each Pathway. */ override def display(): Unit = for l <- pathway if l != null do l.display() end display
end Route

//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** @author John Miller * @version 2.0 * @date Sat Jan 25 19:44:16 EST 2014 * @see LICENSE (MIT style license file). * * @note Route for Modeling Multi-Stage, Multi-Lane Pathway */
package scalation package simulation package process
import scalation.mathstat.VectorD import scala.math.{min, abs} import scalation.random.Discrete //import scalation.random.Variate
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Off-ramp specification — declares where an off-ramp diverges and what * fraction of mainline vehicles should exit there. * * @param rampId identifier matching the off-ramp Ramp/Sink name (e.g. "I210_FR1") * @param divergeSeg segment index where the off-ramp branches from the mainline * @param exitLane lane the vehicle must reach to take the ramp (usually 0 or nLanes-1) * @param turnoffPct fraction of mainline vehicles that exit here (0.0–1.0) */ case class OffRampSpec (rampId: String, divergeSeg: Int, exitLane: Int, turnoffPct: Double)
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Companion for `OffRampSpec` — dice-roll assignment at spawn time. */ object OffRampSpec:
/** Build a ScalaTion Discrete variate from off-ramp specs. * Outcomes: 0 .. specs.length-1 = exit at that ramp, specs.length = through traffic. * * Example: 2 off-ramps at 15% and 10% turnoff → * dist = VectorD(0.15, 0.10, 0.75) // index 0 = ramp 1, index 1 = ramp 2, index 2 = through traffic * Discrete.gen rolls → 0 (15%), 1 (10%), or 2 (75%) * * @param specs the off-ramp specs for this route (ordered by position along corridor) * @return a Discrete variate (call .gen to roll) */ def buildExitDist (specs: List [OffRampSpec]): Discrete = val n = specs.length val dist = new VectorD (n + 1) var s = 0.0 // explicit running sum — no dependency on dist(n) being 0 cfor (0, n) { i => dist(i) = specs(i).turnoffPct s += dist(i) } dist(n) = (1.0 - s).max (0.0) // through traffic = remainder Discrete (dist) end buildExitDist
/** Roll the Discrete variate and return the rampId (or null = through traffic). * * Example: specs = List(OffRampSpec("I210_FR1", ...), OffRampSpec("I210_FR2", ...)) * exitRV.gen → 0.0 → return "I210_FR1" (exit at first off-ramp) * exitRV.gen → 1.0 → return "I210_FR2" (exit at second off-ramp) * exitRV.gen → 2.0 → return null (through traffic — drives to Sink) * * @param specs the off-ramp specs (same list used to build the variate) * @param exitRV the Discrete variate from buildExitDist * @return rampId to exit at, or null if through traffic */ def assignExit (specs: List [OffRampSpec], exitRV: Discrete): String = if specs.isEmpty then null else val idx = exitRV.gen.toInt if idx < specs.length then specs(idx).rampId else null // through traffic end assignExit
end OffRampSpec
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `Route` class defines a multi-lane route composed of multiple `Pathway`s * running in parallel. Each `Pathway` is a single-lane road that shares the same * `from` (entry), `to` (exit), and intermediate `junc` (junction) components. * * @param name the name of the route * @param numLanes the number of parallel lanes (Pathways) * @param junc the shared junction components between segments * @param from the shared starting component (e.g., VSource) * @param to the shared ending component (e.g., Sink) * @param motion the dynamics model used for movement * @param isSpeed whether speed or trip-time is used * @param bend curvature of the lanes */ class Route (name: String, numLanes: Int, junc: Array[Junction], from: Component, to: Component, motion: Dynamics, isSpeed: Boolean = false, bend: Double = 0.0, val lanesPerSeg: Array[Int] = null, var offRampSpecs: List[OffRampSpec] = Nil) extends Component ():
// ── Off-ramp infrastructure (set once by wireOffRamps, used by tryExitRamp) ── private var _offRamps: Array[Ramp] = null // off-ramp Ramp objects (indexed same as offRampSpecs) private var _offRampSinks: Array[Sink] = null // off-ramp Sink objects private var _exitRV: Discrete = null // Discrete variate for full-route spawn private var _downstreamRVs: Array[Discrete] = null // per-on-ramp Discrete (downstream-only specs)
private val debug = debugf("Route", true) // debug function
/** Number of segments in this route. */ private val nSegments: Int = junc.length + 1 // from + junc.length intermediates + to = junc.length+1 points → junc.length+1-1 segs ... actually segments = intermediateJunc.length + 1
/** Per-segment lane counts. If lanesPerSeg is null (uniform), fill with numLanes. */ private val _lanesPerSeg: Array[Int] = if lanesPerSeg != null then lanesPerSeg else Array.fill(junc.length + 1)(numLanes) // junc = intermediate junctions → nSegments = junc.length + 1
/** Maximum lane count across all segments. */ val maxLanes: Int = if _lanesPerSeg.nonEmpty then _lanesPerSeg.max else numLanes
/** Query: how many lanes exist at segment `seg`. */ def lanesAt (seg: Int): Int = _lanesPerSeg(seg)
/** Query: does lane `lane` exist at segment `seg`? */ def laneExistsAt (lane: Int, seg: Int): Boolean = lane < _lanesPerSeg(seg)
val pathway: Array[Pathway] = Array.ofDim[Pathway](numLanes) // create array of parallel Pathways private val GAP = 50.0 // pixel between lanes
for i <- pathway.indices do val physicalLane = numLanes - 1 - i // Reverse: i=0 → lane 4 (rightmost), i=4 → lane 0 (leftmost) val shift = calcShift2 * ((physicalLane - (numLanes - 1) / 2.0) * GAP) pathway(i) = new Pathway(s"${name}L$i", junc, from, to, motion, isSpeed, bend, laneShift = shift, laneIndex = i, lanesPerSeg = _lanesPerSeg) pathway(i).parentRoute = this // back-reference for MOBIL lane-change subpart += pathway(i) end for
initComponent(name, from.at) // using from.at for the initComponent
// Cumulative length up to (but not including) each segment // segmentOffsets(0) = 0 // segmentOffsets(1) = seg(0).length // segmentOffsets(2) = seg(0).length + seg(1).length // etc. val segmentOffsets: Array[Double] = val n = pathway(0).seg.length // number of segments (same for all Pathways) val offsets = new Array[Double](n + 1) // array to hold offsets offsets(0) = 0.0 // starting offset is 0.0 for i <- 0 until n do // Find a non-null VTransport at this segment index (any lane will do — same geometry) val vt = pathway.map(_.seg(i)).find(_ != null).orNull offsets(i + 1) = offsets(i) + (if vt != null then vt.length else 0.0) end for offsets end segmentOffsets
// O(1) helper: convert (segId, disp) → cumulative position @inline def toCumulative(segId: Int, disp: Double): Double = segmentOffsets(segId) + disp end toCumulative
// ----------------------------------------------------------------------------
/** Attempt to change lanes for a vehicle that is on segment `seg` of lane `l1` * and wants to move to adjacent lane `l2`. * * @return true if the lane-change succeeds; false otherwise */ def changeLane(l1: Int, l2: Int, actor: Vehicle, seg: Int): Boolean =
var success = abs(l1 - l2) == 1 if !success then return success
// Check if target lane exists at this segment (variable lane support) if !laneExistsAt(l2, seg) then return false // Check if source lane exists at this segment (car can't be here if lane is null) if !laneExistsAt(l1, seg) then return false
val fromPath = pathway(l1) // current Pathway (lane l1) val toPath = pathway(l2) // target Pathway (lane l2)
// Check if either lane doesn't exist if fromPath == null || toPath == null then return false
val safeDisp = fromPath.seg(seg).safetydist
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: // vehicles to check in target lane val vBehind = toPath.seg(seg).getFirst // car behind in same seg val vAhead = if seg + 1 < toPath.seg.length && toPath.seg(seg + 1) != null then toPath.seg(seg + 1).getLast else null
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: // compute bumper-to-bumper gaps val gapBehind = if vBehind != null then actor.disp - vBehind.disp else safeDisp
val nextSeg = min(seg + 1, toPath.seg.length - 1)
val gapAhead = if vAhead != null then toPath.seg(nextSeg).length - vAhead.disp - Vehicle.len else safeDisp
val gap = min(gapBehind, gapAhead) //:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: // feasibility check success &&= gapBehind >= safeDisp && gapAhead >= safeDisp
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: // --- perform the lane change -------------------------------------------- if success then fromPath.removeFromAlist(actor, seg) // detach from old lane at this segment assert(actor.myPathNode == null, s"Vehicle $this not cleared before lane-change insertion!")
actor.laneID = l2 // update laneID actor.pathInfo = toPath.seg(seg).name // update pathInfo toPath.addToAlist(actor, vAhead, seg) // insert before vAhead in target lane at this segment end if
success end changeLane
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Merge a ramp vehicle into the mainline at the given lane and segment. * Remove from ramp, look who's ahead in the merge segment, insert behind them. * IDM in Dynamics handles car-following after insertion. * * @param lane the target mainline lane * @param seg the merge segment index * @param car the merging vehicle (just finished driving the ramp) * @param fromRamp the ramp the vehicle came from (null if direct) */ def mergeFromRamp (lane: Int, seg: Int, car: Vehicle, fromRamp: Ramp = null): Unit = val effectiveLane = if laneExistsAt (lane, seg) then lane else lanesAt (seg) - 1 if fromRamp != null then fromRamp.removeFromAlist (car) val vAhead = pathway(effectiveLane).seg(seg).getLast pathway(effectiveLane).addToAlist (car, vAhead, seg) end mergeFromRamp
//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** * Lane-drop forced merge. A lane dies (e.g. 5 lanes → 4 lanes). * Every vehicle in the dying lane moves into the adjacent surviving lane. * If there's a car ahead in that lane, slot behind it. That's it. * * This method does the FULL job: remove from dead lane, insert into * surviving lane. Caller just uses the returned laneID and moves on. * * @param l1 the vehicle's current lane (dead at this segment) * @param availLanes the lanes that exist at this segment (e.g. 0 until 4) * @param car the vehicle being merged * @param seg the segment index where the lane drop occurs * @return the new lane index */ def forceMerge(l1: Int, availLanes: Range, car: Vehicle, seg: Int): Int = val target = availLanes.last // adjacent surviving lane
// 1. Remove from dead lane (if still attached) if car.myPathNode != null && pathway(l1) != null && pathway(l1).seg(seg) != null then pathway(l1).removeFromAlist(car, seg) end if
// 2. Insert into surviving lane — slot behind whoever is ahead val ahead = pathway(target).seg(seg).getLast car.laneID = target pathway(target).addToAlist(car, ahead, seg)
target end forceMerge
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Check whether a vehicle needs to steer toward its assigned off-ramp. * If the vehicle is within the mandatory lane-change zone, override MOBIL * and force one lane change toward the exit lane per call. * * Called every timestep from VTransport.move() — only when car.exitRampIdx >= 0. * * @param car the vehicle with exitRampIdx >= 0 * @param seg the vehicle's current segment index * @param clock current simulation time (for cooldown) */ def exitCheckAndSteer (car: Vehicle, seg: Int, clock: Double): Unit = if car.exitRampIdx < 0 || car.exitRampIdx >= offRampSpecs.length then return val spec = offRampSpecs(car.exitRampIdx) // O(1) — index, not .find
val segsRemaining = spec.divergeSeg - seg if segsRemaining <= 0 then return // already past it
val distToExit = { var d = 0.0 val lane0 = pathway.find (_ != null).get for s <- seg until min (spec.divergeSeg, lane0.seg.length) do if lane0.seg(s) != null then d += lane0.seg(s).length d }
if car.laneID == spec.exitLane then return // already in exit lane
val cooldown = if distToExit < 200.0 then 1.0 else if distToExit < 500.0 then 2.0 else return // > 500m: let MOBIL handle it
if (clock - car.lastLaneChangeTime) < cooldown then return
val dir = if spec.exitLane > car.laneID then 1 else -1 val ok = changeLane (car.laneID, car.laneID + dir, car, seg) if ok then car.lastLaneChangeTime = clock end exitCheckAndSteer
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** One-call off-ramp setup. Builds specs, Discrete variates, and stores * the Ramp/Sink arrays so that tryExitRamp can do the full job. * * Example: wireOffRamps(offRamps, sinks, joinSegs, 4, 0.15, onRampJoinSegs) * → builds 1 OffRampSpec per off-ramp, all exiting from lane 4 at 15% * → builds Discrete variate for mainline spawn * → pre-builds per-on-ramp downstream Discrete variates * * @param ramps the off-ramp Ramp objects (same order as joinSegs) * @param sinks the off-ramp Sink objects (same order) * @param joinSegs segment indices where each off-ramp diverges * @param exitLane which lane vehicles must reach (usually nLanes-1) * @param turnoffPct fraction of mainline vehicles exiting at each ramp * @param onRampJoinSegs on-ramp join segments (for downstream filtering at ramp spawn) */ def wireOffRamps (ramps: Array[Ramp], sinks: Array[Sink], joinSegs: Array[Int], exitLane: Int, turnoffPct: Double, onRampJoinSegs: Array[Int] = Array.empty): Unit = _offRamps = ramps _offRampSinks = sinks val n = ramps.length val specs = new Array[OffRampSpec](n) cfor (0, n) { r => specs(r) = OffRampSpec (ramps(r).name, joinSegs(r), exitLane, turnoffPct) } offRampSpecs = specs.toList _exitRV = OffRampSpec.buildExitDist (offRampSpecs)
// Pre-build per-on-ramp downstream Discrete variates + index maps _downstreamRVs = new Array[Discrete](onRampJoinSegs.length) _downstreamIdxMaps = new Array[Array[Int]](onRampJoinSegs.length) cfor (0, onRampJoinSegs.length) { r => val buf = scala.collection.mutable.ArrayBuffer[Int]() cfor (0, n) { i => if specs(i).divergeSeg > onRampJoinSegs(r) then buf += i } _downstreamIdxMaps(r) = buf.toArray val downSpecs = _downstreamIdxMaps(r).map(i => offRampSpecs(i)).toList _downstreamRVs(r) = OffRampSpec.buildExitDist (downSpecs) } end wireOffRamps
// Per-on-ramp maps: downstream Discrete index → global offRampSpecs index private var _downstreamIdxMaps: Array[Array[Int]] = null
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Assign an off-ramp exit destination to a vehicle at spawn time. * Sets car.exitRampIdx (or leaves it -1 for through traffic). * * Example (mainline): assignExitAtSpawn(car) → rolls full Discrete * Example (ramp #2): assignExitAtSpawn(car, 2) → rolls downstream-only Discrete * * @param car the vehicle being spawned * @param onRampIdx on-ramp index for downstream filtering (-1 = mainline entry) */ def assignExitAtSpawn (car: Vehicle, onRampIdx: Int = -1): Unit = if offRampSpecs.isEmpty || _exitRV == null then return if onRampIdx < 0 then // Mainline entry — full route eligible val idx = _exitRV.gen.toInt car.exitRampIdx = if idx < offRampSpecs.length then idx else -1 else if _downstreamRVs != null && onRampIdx < _downstreamRVs.length then // Ramp entry — only downstream off-ramps eligible val rv = _downstreamRVs(onRampIdx) val idxMap = _downstreamIdxMaps(onRampIdx) val localIdx = rv.gen.toInt car.exitRampIdx = if localIdx < idxMap.length then idxMap(localIdx) else -1 end if end assignExitAtSpawn
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Check if the vehicle should exit at its assigned off-ramp at this segment. * If yes: drives the off-ramp, leaves at the off-ramp sink, returns true. * If past the diverge: resets exitRampIdx to -1 (missed exit), returns false. * Otherwise: returns false (not at diverge yet). * * Example: if route.tryExitRamp(this, seg) then exited = true * * @param car the vehicle (must have exitRampIdx set) * @param seg the current segment index (after incrementing past previous seg) * @return true if the vehicle exited via off-ramp */ def tryExitRamp (car: Vehicle, seg: Int): Boolean = if car.exitRampIdx < 0 then return false if _offRamps == null || car.exitRampIdx >= offRampSpecs.length then return false
val spec = offRampSpecs(car.exitRampIdx) // O(1)
if seg == spec.divergeSeg && car.laneID == spec.exitLane then val ramp = _offRamps(car.exitRampIdx) val sink = _offRampSinks(car.exitRampIdx) car.myPathway = null // Off-ramp: add then immediately remove (pass-through for DLL bookkeeping) val ahead = ramp.getLast ramp.addToAlist (car, ahead) ramp.removeFromAlist (car) sink.leave () true else if seg > spec.divergeSeg then car.exitRampIdx = -1 // missed exit → through traffic false else false end tryExitRamp
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Get the first vehicle in the specified lane. * @param i the index of the pathway/lane */ def getFirst(i: Int): Vehicle = if pathway(i) != null then pathway(i).getFirst else null
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Get the last vehicle in the specified lane. * @param i the index of the lane */ def getLast(i: Int): Vehicle = if pathway(i) != null then pathway(i).getLast else null
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Get the Pathway at index i. * @param i the lane index */ def path(i: Int): Pathway = pathway(i)
//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** Return the shared junctions. */ def junctions: Array[Junction] = junc
/** Return the number of segments (same for all Pathways). */ def segments: Int = pathway(0).seg.length
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** All junction points in order: from +: junc :+ to. * points(seg) is the upstream junction of segment `seg`. */ private val _points: Array [Component] = (from +: junc.toIndexedSeq :+ to).toArray
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Perpendicular unit vector pointing outward from road centerline * toward the ramp side (opposite from lane 0 / rightmost lane). */ val perpVec: (Double, Double) = val v = calcShift2 (-v(0), -v(1)) // negate: away from lane 0
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the screen (x, y) at the outermost lane edge of segment `seg`. * Adapts to variable lane counts: more lanes → further from centerline. * Points toward the ramp side (away from lane 0). * @param seg segment index (0 .. nSegments-1) */ def rampAttachPoint (seg: Int): (Double, Double) = val pt = _points(seg) // junction at segment boundary val nHere = lanesAt(seg) val offset = (nHere - numLanes / 2.0 - 0.5) * GAP // slightly inside lane edge for visual snugness (pt.at(0) + perpVec._1 * offset, pt.at(1) + perpVec._2 * offset) end rampAttachPoint
//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** Calculate the amount of shift in the x and y directions. */ private def calcShift2: VectorD = val dx = to.at(0) - from.at(0) val dy = to.at(1) - from.at(1) val hyp = math.hypot(dx, dy) VectorD(dy / hyp, -dx / hyp) end calcShift2
/** Calculate the amount of shift in the x and y directions. */ private def calcShift: VectorD = val xdist = from.at(0) - to.at(0) val ydist = from.at(1) - to.at(1) val hyp = math.hypot(xdist, ydist) VectorD((ydist / hyp) * GAP, -(xdist / hyp) * GAP) end calcShift
//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** Display the Route by displaying each Pathway. */ override def display(): Unit = for l <- pathway if l != null do l.display() end display
end Route

//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** @author John Miller, Casey Bowman * @version 2.0 * @date Tue Feb 4 14:56:34 EST 2020 * @see LICENSE (MIT style license file). * * @note Variable Speed Transport is a Pathway between Components */
package scalation package simulation package process //import scalation.animation.DgAnimator.VehicleState
//import scala.collection.mutable.ArrayDeque //import scala.runtime.ScalaRunTime.stringOf
import scalation.animation.CommandType._ //import scalation.database.BpTreeMap import scalation.mathstat._ import scala.collection.mutable.ArrayDeque
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `VTransport` class provides a variable-speed pathway between two other components. * The components in a `Model` conceptually form a 'graph' in which the edges * are `VTransport`s and the nodes are other `Component`s. * @see `animation.Dgraph.move2Boundary` that aligns edge with node boundaries. * @param name the name of the variable-speed transport * @param from the starting component * @param to the ending component * @param motion the dynamics model for the speed/trip-time for motion down the `VTransport` * @param isSpeed whether speed or trip-time is used for motion * @param bend the bend or curvature of the `VTransport` (0 => line) * @param shift1 the x-y shift for the transport's first end-point (from-side) * @param shift2 the x-y shift for the transport's second end-point (to-side) */ class VTransport (name: String, from_ : Component, to_ : Component, motion: Dynamics, isSpeed: Boolean = false, bend: Double = 0.0, shift1: VectorD = VectorD (0, 0), shift2: VectorD = VectorD (0, 0), segIndex: Int = -1) extends Transport (name, from_, to_, null, isSpeed, bend, shift1, shift2):
private val debug = debugf ("VTransport", false) // debug function //debug ("init", s"name = $name, p1 = $p1, pc = $pc, p2 = $p2, located at ${stringOf (at)}")
var length = 0.0 // The actual length of the road segment. if length <= 0.0 then length = curve.length val safetydist = 20.0
private [process] val vdeque = ArrayDeque [Vehicle] () // Array Deque for density tracking (entry order)
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Per-segment doubly linked list for car-following. * Each VTransport owns its own DLL — the car-following backbone. * Replaces the lane-spanning Pathway.vList for leader lookup. */ private [process] val vList = DoublyLinkedList [Vehicle]
/** Debug label for this segment's DLL. */ val dllId = s"DLL_${name}"
private[process] val easyW = new EasyWriter("simulation", "OnewayVehicle2LModel.txt") easyW.off()
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Add a vehicle to this segment's doubly linked list. * @param actor the vehicle to add * @param other the vehicle ahead (null if none) */ def addToAlist (actor: Vehicle, other: Vehicle): Unit = val otherNode = if other != null then other.myPathNode.asInstanceOf [vList.Node] else null actor.myPathNode = vList.add (actor, otherNode) actor.pathInfo = dllId end addToAlist
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Remove a vehicle from this segment's doubly linked list. * @param actor the vehicle to remove */ def removeFromAlist (actor: Vehicle): Unit = vList.remove (actor.myPathNode.asInstanceOf [vList.Node]) actor.myPathNode = null end removeFromAlist
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Get the first vehicle in this segment (lead car, head of DLL). */ def getFirst: Vehicle = val first: Vehicle = if vList.isEmpty then null else vList.head debug ("getFirst", s"the first vehicle = $first") first end getFirst
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Get the last vehicle in this segment (most recently entered, tail of DLL). */ def getLast: Vehicle = val last: Vehicle = if vList.isEmpty then null else vList.last debug ("getLast", s"the last vehicle = $last") last end getLast
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the instantaneous traffic density on this segment. * density k = number of vehicles on segment / segment length (veh/m) * Called from driveHighway after each move() to snapshot the segment state. */ def snapshotDensity (): Double = if length > 0.0 then vdeque.size.toDouble / length else 0.0 end snapshotDensity
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Move the entity (SimActor) smoothly down this VTransport (e.g., road). * Repeatedely move it along the VTransport/Edge/QCurve. * Caveat: tokens coordinates are computed using a shadow QCurve (same coordinates * as the one that will be created by the animation engine). */
override def move(): Unit =
val actor = director.theActor.asInstanceOf[Vehicle] val lastSeg = actor.segId // segment before entering this one val lastEnterTime = actor.segmentEnterTime // time entered previous segment val now = director.clock actor.segmentEnterTime = now // update the current actor's segmentEnterTime with now
//actor.prevSegId = lastSeg actor.segId = segIndex // update the current actor's segment_ID with actor.disp = 0.0 actor.pathInfo = name //update the current actor's lane_ID with the Vtransport_ID it is moving in
//val segTT = if lastSeg >= 0 then f"${now - actor.segmentEnterTime}%.2f" else "N/A" //easyW.println(s"[t=$now] Vehicle ${actor.displayLabel} enters seg=${actor.segId} (from seg=$lastSeg), enterT=$now")
//debug("move", s"actor = $actor, disp=${actor.disp} along the VTransport") vdeque += actor
tally(Vehicle.rt)
var done = false while actor.disp < length && !done do //director.log.trace(this, "moves for " + Vehicle.rt, actor, director.clock)
motion.updateV(actor, length) // update actor/vehicle's motion/position
// --- Lane-change decisions (MOBIL + exit steering) --- val route = actor.myRoute if route != null && actor.laneID >= 0 && actor.myRamp == null then // 1. MOBIL discretionary (3s cooldown) if (director.clock - actor.lastLaneChangeTime) > 3.0 then val dir = MOBIL.checkLaneChange (actor, route, actor.segId, actor.laneID) if dir != 0 then val ok = route.changeLane (actor.laneID, actor.laneID + dir, actor, actor.segId) if ok then actor.lastLaneChangeTime = director.clock end if end if // 2. Exit steering — runs independently, has its own cooldown if actor.exitRampId != null then route.exitCheckAndSteer (actor, actor.segId, director.clock) end if end if
val cp = calcPoint2(actor.disp) //debug ("move", s"${actor.displayLabel}, check if actor.disp = ${actor.disp} >= curve.length = ${curve.length}") if actor.disp >= length then done = true vdeque -= actor end if
if !done then val vColor = Vehicle.velocityColor (actor.velocity) director.animate(actor, MoveToken, vColor, null, cp) actor.schedule(Vehicle.rt) actor.yieldToDirector() end while
//println(f"[move EXIT] ${actor.displayLabel}%-12s seg=${actor.segId} disp=${actor.disp}%.2f v=${actor.velocity}%.2f length=${length}%.2f vt=$name") end move
def calcPoint2(s: Double): Array[Double] = curve.traj = s / curve.length // percentage of the curve the car has traveled thus far. val xy = curve.eval() Array(xy.x, xy.y) end calcPoint2
//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** Calculate the (x, y) point in the simulation space for the vehicle. * * @param s the current displacement along the road of the vehicle. */ def calcPoint(s: Double): Array[Double] = val prop = s / curve.length val x = p1(0) + (p2(0) - p1(0)) * prop val y = p1(1) + (p2(1) - p1(1)) * prop Array(x - RAD, y - RAD) end calcPoint
end VTransport

//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** @author John Miller, Casey Bowman * @version 2.0 * @date Tue Feb 4 14:56:34 EST 2020 * @see LICENSE (MIT style license file). * * @note Variable Speed Transport is a Pathway between Components */
package scalation package simulation package process //import scalation.animation.DgAnimator.VehicleState
//import scala.collection.mutable.ArrayDeque //import scala.runtime.ScalaRunTime.stringOf
import scalation.animation.CommandType._ //import scalation.database.BpTreeMap import scalation.mathstat._ import scala.collection.mutable.ArrayDeque
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `VTransport` class provides a variable-speed pathway between two other components. * The components in a `Model` conceptually form a 'graph' in which the edges * are `VTransport`s and the nodes are other `Component`s. * @see `animation.Dgraph.move2Boundary` that aligns edge with node boundaries. * @param name the name of the variable-speed transport * @param from the starting component * @param to the ending component * @param motion the dynamics model for the speed/trip-time for motion down the `VTransport` * @param isSpeed whether speed or trip-time is used for motion * @param bend the bend or curvature of the `VTransport` (0 => line) * @param shift1 the x-y shift for the transport's first end-point (from-side) * @param shift2 the x-y shift for the transport's second end-point (to-side) */ class VTransport (name: String, from_ : Component, to_ : Component, motion: Dynamics, isSpeed: Boolean = false, bend: Double = 0.0, shift1: VectorD = VectorD (0, 0), shift2: VectorD = VectorD (0, 0), segIndex: Int = -1) extends Transport (name, from_, to_, null, isSpeed, bend, shift1, shift2):
private val debug = debugf ("VTransport", false) // debug function //debug ("init", s"name = $name, p1 = $p1, pc = $pc, p2 = $p2, located at ${stringOf (at)}")
var length = 0.0 // The actual length of the road segment. if length <= 0.0 then length = curve.length val safetydist = 20.0
private [process] val vdeque = ArrayDeque [Vehicle] () // Array Deque for density tracking (entry order)
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Per-segment doubly linked list for car-following. * Each VTransport owns its own DLL — the car-following backbone. * Replaces the lane-spanning Pathway.vList for leader lookup. */ private [process] val vList = DoublyLinkedList [Vehicle]
/** Debug label for this segment's DLL. */ val dllId = s"DLL_${name}"
private[process] val easyW = new EasyWriter("simulation", "OnewayVehicle2LModel.txt") easyW.off()
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Add a vehicle to this segment's doubly linked list. * @param actor the vehicle to add * @param other the vehicle ahead (null if none) */ def addToAlist (actor: Vehicle, other: Vehicle): Unit = val otherNode = if other != null then other.myPathNode.asInstanceOf [vList.Node] else null actor.myPathNode = vList.add (actor, otherNode) actor.pathInfo = dllId end addToAlist
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Remove a vehicle from this segment's doubly linked list. * @param actor the vehicle to remove */ def removeFromAlist (actor: Vehicle): Unit = vList.remove (actor.myPathNode.asInstanceOf [vList.Node]) actor.myPathNode = null end removeFromAlist
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Get the first vehicle in this segment (lead car, head of DLL). */ def getFirst: Vehicle = val first: Vehicle = if vList.isEmpty then null else vList.head debug ("getFirst", s"the first vehicle = $first") first end getFirst
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Get the last vehicle in this segment (most recently entered, tail of DLL). */ def getLast: Vehicle = val last: Vehicle = if vList.isEmpty then null else vList.last debug ("getLast", s"the last vehicle = $last") last end getLast
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the instantaneous traffic density on this segment. * density k = number of vehicles on segment / segment length (veh/m) * Called from driveHighway after each move() to snapshot the segment state. */ def snapshotDensity (): Double = if length > 0.0 then vdeque.size.toDouble / length else 0.0 end snapshotDensity
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Move the entity (SimActor) smoothly down this VTransport (e.g., road). * Repeatedely move it along the VTransport/Edge/QCurve. * Caveat: tokens coordinates are computed using a shadow QCurve (same coordinates * as the one that will be created by the animation engine). */
override def move(): Unit =
val actor = director.theActor.asInstanceOf[Vehicle] val lastSeg = actor.segId // segment before entering this one val lastEnterTime = actor.segmentEnterTime // time entered previous segment val now = director.clock actor.segmentEnterTime = now // update the current actor's segmentEnterTime with now
//actor.prevSegId = lastSeg actor.segId = segIndex // update the current actor's segment_ID with actor.disp = 0.0 actor.pathInfo = name //update the current actor's lane_ID with the Vtransport_ID it is moving in
//val segTT = if lastSeg >= 0 then f"${now - actor.segmentEnterTime}%.2f" else "N/A" //easyW.println(s"[t=$now] Vehicle ${actor.displayLabel} enters seg=${actor.segId} (from seg=$lastSeg), enterT=$now")
//debug("move", s"actor = $actor, disp=${actor.disp} along the VTransport") vdeque += actor
tally(Vehicle.rt)
var done = false while actor.disp < length && !done do //director.log.trace(this, "moves for " + Vehicle.rt, actor, director.clock)
motion.updateV(actor, length) // update actor/vehicle's motion/position
// --- Lane-change decisions (MOBIL + exit steering) --- val route = actor.myRoute if route != null && actor.laneID >= 0 && actor.myRamp == null then // 1. MOBIL discretionary (3s cooldown) if (director.clock - actor.lastLaneChangeTime) > 3.0 then val dir = MOBIL.checkLaneChange (actor, route, actor.segId, actor.laneID) if dir != 0 then val ok = route.changeLane (actor.laneID, actor.laneID + dir, actor, actor.segId) if ok then actor.lastLaneChangeTime = director.clock end if end if // 2. Exit steering — runs independently, has its own cooldown if actor.exitRampIdx >= 0 then route.exitCheckAndSteer (actor, actor.segId, director.clock) end if end if
val cp = calcPoint2(actor.disp) //debug ("move", s"${actor.displayLabel}, check if actor.disp = ${actor.disp} >= curve.length = ${curve.length}") if actor.disp >= length then done = true vdeque -= actor end if
if !done then val vColor = Vehicle.velocityColor (actor.velocity) director.animate(actor, MoveToken, vColor, null, cp) actor.schedule(Vehicle.rt) actor.yieldToDirector() end while
//println(f"[move EXIT] ${actor.displayLabel}%-12s seg=${actor.segId} disp=${actor.disp}%.2f v=${actor.velocity}%.2f length=${length}%.2f vt=$name") end move
def calcPoint2(s: Double): Array[Double] = curve.traj = s / curve.length // percentage of the curve the car has traveled thus far. val xy = curve.eval() Array(xy.x, xy.y) end calcPoint2
//::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::
/** Calculate the (x, y) point in the simulation space for the vehicle. * * @param s the current displacement along the road of the vehicle. */ def calcPoint(s: Double): Array[Double] = val prop = s / curve.length val x = p1(0) + (p2(0) - p1(0)) * prop val y = p1(1) + (p2(1) - p1(1)) * prop Array(x - RAD, y - RAD) end calcPoint
end VTransport

//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** @author John Miller, Casey Bowman * @version 2.0 * @date Tue Feb 4 14:56:34 EST 2020 * @see LICENSE (MIT style license file). * * @note Vehicle Is Enhanced SimActor Supporting Changing Velocities */
package scalation package simulation package process
import scala.collection.mutable.Map import scalation.random.Uniform import scalation.mathstat.VectorD import scalation.scala2d.Colors.Color
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `Vehicle` class extends the `SimActor` and represents a vehicle in motion. * @param name_ the name of the vehicle * @param director the model to which this vehicle belongs */ abstract class Vehicle (name_ : String, director: Model) extends SimActor (name_, director) with Dynamics:
// Vehicle's target free-flow speed (m/s). Set at creation from PEMS data.] //What this is doing is counter intuitive - it is setting the generic vmax to a random value // I get the logic but we do not need this as it's introducing bug into our code because IDM // is using it directly in Dynamics line // var a = iDM(amax, b, len, car.vmax, x_n, v_n, // x_leader, v_leader, T, s, del) // So it's blockin our set pems speed. // this is only valuable for generic simulation where we want to randomize vehicle speeds. where //some vehicles are fast some are slow. (trucs and cars) //Hower, we need this overriden in VSource when we set the pems speed. so we can cars not going above pems speed. var vmax = Vehicle.speedGen.gen // this is for generic. needs pems version.
var key = -0.0 var laneID: Int = -1 var pathInfo : String = "" var segId : Int = -1 var prevSegId: Int = -1 // previous segment id (before current segId) var segmentEnterTime: Double = -1.0 // simulation clock when entering current segment
// Derived: live time spent on current segment (call with director.clock) def segmentTravelTime(now: Double): Double = if segmentEnterTime >= 0.0 then now - segmentEnterTime else 0.0 end segmentTravelTime
// Human-friendly label to use in logs/console; animator label should match this. private[process] var displayLabel: String = "" def setDisplayLabel(lbl: String): Unit = if lbl != null then displayLabel = lbl end setDisplayLabel
var myRamp : Ramp = null // current ramp this vehicle is on (null if not on a ramp) var myPathway : Pathway = null // current pathway/lane this vehicle is on (null if not on a pathway) var myFFConnector : FFConnector = null // current FF connector this vehicle is on (null if not on an FF) var myRoute : Route = null // parent Route this vehicle belongs to (set by Pathway.addToAlist) var exitRampId : String = null // off-ramp destination (null = through traffic → drives to Sink) var lastLaneChangeTime: Double = -10.0 // simulation clock when last lane change occurred (cooldown) private [process] var myPathNode: DoublyLinkedList[Vehicle]#Node = null // DLL node: pred <-> me <-> succ
inline def getCarAhead(car: Vehicle): Vehicle = val ref = car.myPathNode.ahead if ref != null then ref.elem else null end getCarAhead
inline def getCarBehind(car: Vehicle): Vehicle = val ref = car.myPathNode.behind if ref != null then ref.elem else null end getCarBehind
inline def gapToLeader: Double = val leader = getCarAhead(this) if leader != null then leader.disp - this.disp - Vehicle.len else 0.0 end gapToLeader
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The abstract method, 'act', is defined in each subclass to provide specific * behavior. */ override def act (): Unit = println (s"Vehicle.act method should be overridden")
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Show the `SimActor`s full name and activation time. */ override def toString: String = val label = if displayLabel != null && displayLabel.nonEmpty then displayLabel else me s"Vehicle($label )"//=$id segId=$segId prevSeg=$prevSegId disp=$disp tDisp=$t_disp enterT=$segmentEnterTime path=$pathInfo)" end Vehicle
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `Vehicle` object contains driver/vehicle characteristics/properties. */ object Vehicle:
val speedGen = Uniform(20.0 , 40.0)
/** defaults values for driver/vehicle characteristics/properties (PUBLIC access required) * @see https://en.wikipedia.org/wiki/Intelligent_driver_model */ val def_prop = Map ("rt" -> 0.5, // driver reaction time "amax" -> 4.0, // max acceleration "bmax" -> -2.0, // comfortable deceleration (IDM s* formula) use to be -1.5 "b_emergency" -> -9.0, // physical max braking (0.9g) — clamp floor for all CFMs "v0" -> 4.0, // starting velocity // v0 should be adjustable to 0 "vmax" -> 33.528, // max velocity "T" -> 3.0, // safe min time headway "s" -> 4.0, // safe min distance headway (bumped from 5.0 for visual spacing) "len" -> 4.0, // length of the vehicles "del" -> 4.0, // acceleration exponent (delta) "p_mobil" -> 0.2, // MOBIL politeness factor (Treiber & Kesting 2007) "da_th" -> 0.2, // MOBIL lane-change threshold (m/s²) "b_safe" -> 4.0) // MOBIL max safe braking for new follower (m/s²)
/** current values for driver/vehicle characteristics/properties */ private [process] var prop = def_prop
// //:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Return the current value for 'prop("rt") the driver reaction time */ inline def rt: Double = prop("rt") // driver reaction time inline def amax: Double = prop("amax") // max acceleration inline def bmax: Double = prop("bmax") // comfortable deceleration (IDM s* formula) inline def b_emergency: Double = prop("b_emergency") // physical max braking (0.9g) — clamp floor inline def v0: Double = prop("v0") // starting velocity inline def vmax: Double = prop("vmax") // max velocity inline def T: Double = prop("T") // min time headway inline def s: Double = prop("s") // min distance headway inline def len: Double = prop("len") // length of the vehicles inline def del: Double = prop("del") // acceleration exponent (delta) inline def p_mobil: Double = prop("p_mobil") // MOBIL politeness factor inline def da_th: Double = prop("da_th") // MOBIL lane-change threshold (m/s²) inline def b_safe: Double = prop("b_safe") // MOBIL max safe braking for new follower (m/s²)
def setInitialSpeed(v0: Double):Unit = prop("v0") = v0 end setInitialSpeed
//the parameters to be optimized by the objective function //s:Double, amax:Double, bmax:Double, T:Double ,τ:Double def setParams(params:VectorD):Map[String, Double] = //println("setParams called @@@@@")
val new_prop = Map("rt" -> params(4), // driver reaction time "amax" -> params(1), // max acceleration "bmax" -> params(2), // comfortable deceleration "b_emergency" -> def_prop("b_emergency"), // physical max braking (not calibrated) "v0" -> def_prop("v0"), // starting velocity // v0 should be adjustable to 0 "vmax" -> def_prop("vmax"), // max velocity "T" -> params(3), // safe min time headway "s" -> params(0), // safe min distance headway "len" -> def_prop("len"), // length of the vehicles "del" -> def_prop("del")) // acceleration exponent (delta)
new_prop end setParams
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Set the driver/vehicle characteristics/properties to the new property values. * @param new_prop the new property values */ private [process] def setProps (new_prop: Map [String, Double]): Unit = prop = new_prop
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Butcher's Method (fifth order) for numerically solving an ordinary differential equation. * @param Ft the "original" function value at time t * @param ft the "derivative" function value at time t * @param ft_rt the "derivative" function value at time t - rt * @param rt the time difference (reaction time) // it's a 5th order Runge-Kutta method like D * * FIX - integrate into Dynamics package */
def butcher(Ft: Double, ft: Double, ft_rt: Double, rt: Double): Double = val _1_by_90 = 1.0 / 90.0
val k1 = ft_rt //val k2 = ft_rt + 0.25 * (ft - ft_rt) val k3 = ft_rt + 0.25 * (ft - ft_rt) val k4 = ft_rt + 0.50 * (ft - ft_rt) val k5 = ft_rt + 0.75 * (ft - ft_rt) val k6 = ft
Ft + _1_by_90 * (7 * k1 + 32 * k3 + 12 * k4 + 32 * k5 + 7 * k6) * rt end butcher
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Map a vehicle's velocity to a color on a red → yellow → green gradient. * Stopped vehicles are red, free-flow vehicles are green. * Uses HSB color space for smooth transitions. * @param v the current velocity (m/s) * @return a Color from red (0 m/s) through yellow to green (vmax) */ def velocityColor (v: Double): Color = val ratio = math.max (0.0, math.min (1.0, v / vmax)) // 0.0 = stopped, 1.0 = free-flow val hue = (ratio * 120.0 / 360.0).toFloat // 0° red → 60° yellow → 120° green java.awt.Color.getHSBColor (hue, 0.85f, 0.95f) end velocityColor
end Vehicle

