var myRamp : Ramp = null // current ramp this vehicle is on (null if not on a ramp) var myPathway : Pathway = null // current pathway/lane this vehicle is on (null if not on a pathway) var myFFConnector : FFConnector = null // current FF connector this vehicle is on (null if not on an FF) var myRoute : Route = null // parent Route this vehicle belongs to (set by Pathway.addToAlist) var exitRampIdx : Int = -1 // index into route.offRampSpecs (-1 = through traffic → drives to Sink) var lastLaneChangeTime: Double = -10.0 // simulation clock when last lane change occurred (cooldown) private [process] var myPathNode: DoublyLinkedList[Vehicle]#Node = null // DLL node: pred <-> me <-> succ
inline def getCarAhead(car: Vehicle): Vehicle = val ref = car.myPathNode.ahead if ref != null then ref.elem else null end getCarAhead
inline def getCarBehind(car: Vehicle): Vehicle = val ref = car.myPathNode.behind if ref != null then ref.elem else null end getCarBehind
