//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The abstract method, 'act', is defined in each subclass to provide specific * behavior. */ override def act (): Unit = println (s"Vehicle.act method should be overridden")
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** Show the `SimActor`s full name and activation time. */ override def toString: String = val label = if displayLabel != null && displayLabel.nonEmpty then displayLabel else me s"Vehicle($label )"//=$id segId=$segId prevSeg=$prevSegId disp=$disp tDisp=$t_disp enterT=$segmentEnterTime path=$pathInfo)" end Vehicle
//:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::: /** The `Vehicle` object contains driver/vehicle characteristics/properties. */ object Vehicle:
val speedGen = Uniform(20.0 , 40.0)
/** defaults values for driver/vehicle characteristics/properties (PUBLIC access required) * @see https://en.wikipedia.org/wiki/Intelligent_driver_model */ val def_prop = Map ("rt" -> 0.5, // driver reaction time "amax" -> 4.0, // max acceleration "bmax" -> -2.0, // comfortable deceleration (IDM s* formula) use to be -1.5 "b_emergency" -> -9.0, // physical max braking (0.9g) — clamp floor for all CFMs "v0" -> 4.0, // starting velocity // v0 should be adjustable to 0 "vmax" -> 33.528, // max velocity "T" -> 3.0, // safe min time headway "s" -> 4.0, // safe min distance headway (bumped from 5.0 for visual spacing) "len" -> 4.0, // length of the vehicles "del" -> 4.0, // acceleration exponent (delta) "p_mobil" -> 0.2, // MOBIL politeness factor (Treiber & Kesting 2007) "da_th" -> 0.2, // MOBIL lane-change threshold (m/s²) "b_safe" -> 4.0) // MOBIL max safe braking for new follower (m/s²)
